COLLDATA("asabahur","ur",[[11296,"§۱۱۳۳۴ ۔ سمیہ والدہ زیاد\nان سے پہلی صحابیہ میں ان کا ذکر گزر چکا ہے، حارث بن کلدہ کی مولاۃ تھیں، قسم ثالث میں ان کا ذکر آئے گا۔"],[11297,"§۱۱۳۳۵ ۔ سناء\n(1) بنت اسماء بن صلت سلمیہ، ابو عبیدہ معمر بن مثنیٰ نے ذکر کیا ہے کہ یہ وہ ہیں جن سے نبی کریم صلی اللہ علیہ وسلم نے نکاح کیا، وہ رخصتی سے قبل وفات پا گئیں اور حفص بن نضر اور عبد القاہر بن سری سلمین سے یہ روایت کیا ہے، اور فرماتے ہیں: عبداللہ بن خازم کی پھوپھی ہیں۔ ابن اسماء بن الصلت جو خراسان کے امیر ہیں۔ میں کہتا ہوں: ابن ابو خیثمہ نے ابو عبیدہ بن عبد القاہر سے ذکر کیا ہے، ان کا نام سناء لیا ہے، جیسا یہاں مذکور ہے۔ دوسرے راویوں نے ان کا نام وسناء لیا ہے (اس کے شروع میں واؤ زیادہ ہے) حرف الف میں گزر چکا ہے کہ حضرت قتادہ نے ان کا نام اسماء بنت صلت لیا ہے، احمد بن صالح مصری نے اسی طرح فرمایا ہے۔ ابن اسحاق(2) کا قول ہے: سناء بنت اسماء، بعض نے کہا: وسناء، یہ ابو عمر(3) سے مروی ہے۔ فرماتے ہیں: اسناد سے اس میں سے کچھ ثابت نہیں اور ابن اسحاق کا قول راجح ہے۔ ابن سعد فرماتے ہیں: سناء۔ بعض نے کہا: سنا۔ ابن حبیب نے انہیں ان کے دادا کی طرف منسوب کیا ہے، اور ان کے نسب کو بنو سلیم کی طرف لے گئے ہیں، اور فرمایا: سناء بنت صلت بن حبیب بن حازم بن ہلال بن حرام بن سماک بن عفیف بن امرئ القیس بن بہثہ بن سلیم، اور ذکر کیا کہ اسماء ان کے بھائی ہیں والد نہیں، اور رخصتی سے قبل ہی وفات پا گئیں۔ رشاطی نے بعض سے بیان کیا ہے کہ ان کی موت کا سبب یہ ہوا کہ جب انہیں یہ خبر ملی کہ نبی کریم صلی اللہ علیہ وسلم نے ان سے نکاح کیا ہے تو بہت خوش ہوئیں یہاں تک کہ خوشی سے ان کا دل پھٹ گیا اور وفات پا گئیں۔","",{"fn":"(1) اسد الغابہ (۷۰۱۴) الاستيعاب (۳۴۳۵) تجرید (۲۷۸/۲)\n(2) السیر والمغازی (۲۶۷)\n(3) الاستيعاب (۱۸۶۵/۴)"}],[11298,"§۱۱۳۳۶ ۔ سناء بنت سفیان الکلابیہ\n(1) بعض کا قول ہے: یہ نبی کریم صلی اللہ علیہ وسلم کی ان ازواج میں سے ہیں جن کی رخصتی نہیں ہوئی، ابن سعد نے ان کا ذکر کیا ہے اور کلابیہ کے نام میں اختلاف ہے۔ حرف عین میں اس بارے میں ذکر کروں گا۔","",{"fn":"(1) تجرید (۲۸۷/۲)"}],[11299,"§۱۱۳۳۷ ۔ سناء بنت مخنف\nسدیہ (تصغیر کے ساتھ) میں ان کا ذکر آئے گا۔"],[11300,"§۱۱۳۳۸ ۔ سنبلہ بنت ماعز\n(1) او ماعص بن قیس بن خلدہ انصاریہ، بنو زریق سے ہیں، ابن حبیب نے بیعت کرنے والی خواتین میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۷۰۱۵) تجرید (۲۷۸/۲)"}],[11301,"§۱۱۳۳۹ ۔ سندوس\nبعض کا قول ہے: سدوس، بنت خالد بن سوید بن ثعلبہ بن عمرو بن حارثہ بن امرئی القیس بن مالک اخر۔ ابن سعد رضی اللہ عنہ فرماتے ہیں: واقدی رضی اللہ عنہ نے ان کا ذکر کیا، وہ اسلام لائیں اور بیعت کی، کسی اور نے ان کا ذکر نہیں کیا۔"],[11302,"§۱۱۳۴۰ ۔ سنیہ بنت حارث\nابن عباس رضی اللہ عنہما سے مروی ہے کہ یہ ان خواتین میں سے تھیں جنہوں نے صلح کے زمانے میں ہجرت کی، اور ان کا امتحان لیا گیا۔ انہوں نے فرمایا: میں اسلام کی طرف رغبت کی وجہ سے آئی ہوں۔"],[11303,"§۱۱۳۴۱ ۔ سُنینہ\n(1) دونوں کی تصغیر کے ساتھ (بنت مخلف بن زید، النکریہ) نون کے ضمہ (پیش) کے ساتھ، بعض کا قول ہے سب کے فتح (زبر) کے ساتھ، ابن ماکولا کا قول ہے۔(2) انہیں شرف صحابیت اور روایت حاصل ہے، ان سے حبہ بنت شماخ نے روایت کی ہے، ابن شاہین اور ابن سکن نے مخلف کے سوانح میں روایت گزر چکی ہے، ان کا نام سناء تھا، اور ابن شاہین نے سیاق کے آخر میں سنینہ لکھا ہے، جیسا کہ یہاں مذکور ہے۔ اور عبد الرحمن بن عمرو بن جبلہ کے طریق سے نقل کیا ہے، فرماتے ہیں: ہم سے حبہ بنت شماخ النکریہ نے بیان کیا، فرماتی ہیں، مجھ سے ہم میں سے ایک خاتون نے بیان کیا، جنہیں سنینہ بنت مخلف بن زید النکریہ کہا جاتا ہے، فرماتی ہیں: ”جب لوگ اسلام کی طرف جلدی کر رہے تھے۔۔۔۔ الخ۔“","",{"fn":"(1) اسد الغابہ (۷۰۱۶) تجرید (۲۷۸/۲)\n(2) الاکمال (۲۶۵ ،۲۶۴/۴)"}],[11304,"§۱۱۳۴۲ ۔ سہلہ بنت سعد الساعدیہ\n(1) سہل جو مشہور صحابی ہیں ان کی بہن ہیں، ابن مندہ نے ان کا ذکر کیا ہے اور ابن لہیعہ کے طریق سے بحوالہ عبداللہ بن ہبیرہ انہوں نے سہلہ بنت سعد الساعدیہ سے روایت کیا ہے کہ وہ فرماتی ہیں: یا رسول اللہ! جو ہار سنگھار عورت اپنے شوہر کے لیے کرتی ہے تا کہ اسے اپنی طرف مائل کرے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”اس میں دنیا کا فائدہ ہے، آخرت میں اس کا حصہ نہیں۔“(2) منصور بن عمار اس کو روایت کرنے میں متفرد ہیں، اسی طرح ابن لہیعہ سے روایت ہے کہ یہ سہلہ بنت سہل ہیں۔ طبرانی(3) نے ان کا ذکر کیا ہے اور ابن لہیعہ کے طریق سے بحوالہ عبداللہ بن ہبیرہ انہوں نے سہلہ بنت سہل سے روایت کیا ہے کہ وہ فرماتی ہیں: یا رسول اللہ! کیا ہم میں سے کسی کو احتلام ہو تو وہ غسل کرے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”ہاں! جب وہ تری دیکھے۔“ اسے عبد الملک بن یحییٰ بن بکیر کے طریق سے بحوالہ ان کے والد انہوں نے ابن لہیعہ سے روایت کیا ہے، مستغفری نے محمد بن معاویہ نیشاپوری کے طریق سے ابن لہیعہ سے اسے روایت کیا ہے، انہوں نے اس کا ذکر کیا اور یہ اضافہ فرمایا، میں نے کہا: یا رسول اللہ! ظاہر ہو گیا۔ لیکن انہوں نے فرمایا: سہیلہ بن سہیل تصغیر کے ساتھ ہے۔ ابو موسیٰ نے اس بات کا جواز پیش کیا ہے کہ وہ سہلہ بنت سہیل بن عمرو ہیں جن کا ذکر کیا گیا ہے، اور وہ بعید ہے، کیونکہ انہیں نے روایت حاصل نہیں۔ ابن اثیر(4) فرماتے ہیں: زیادہ صحیح یہ ہے کہ وہ سہلہ بنت سعد ہیں، راوی کے اس قول میں خطا ہے کہ وہ بنت سہل ہیں، صحیح یہ ہے کہ وہ اخت سہل ہیں، کیونکہ سند دونوں حدیثوں میں ایک ہے۔ میں کہتا ہوں: اس میں احتمال ہے، اور بہت سے احتمال بعید نہیں، ان کے اس قول کے اعتبار سے کہ عمار اس کی روایت کرنے میں متفرد ہیں، ان کا متفرد ہونا، نام میں ہے۔","",{"fn":"(1) اسد الغابہ (۷۰۱۷) تجرید (۲۷۹/۲)\n(2) مجمع الزوائد (۲۶۷/۱) جامع المسانید والسنن (۵۴۶/۱۵)\n(3) المعجم الکبیر (۷۴۳/۲۴)\n(4) اسد الغابہ (۳۱۶/۵)"}],[11305,"§۱۱۳۴۳ ۔ سہلہ بنت سہیل\n(1) بن عمرو قرشیہ، عامریہ، ان کے والد کے سوانح میں ان کا نسب گزر چکا ہے۔ ابتدائی دور میں اسلام لائیں۔ اور اپنے شوہر ابو حذیفہ بن عتبہ کے ساتھ حبشہ کی طرف ہجرت کی، وہاں محمد بن ابو حذیفہ پیدا ہوئے، ابن اسحاق(2) نے اس کا ذکر کیا ہے۔ ابن سعد(3) فرماتے ہیں: ان کی والدہ فاطمہ بنت عبد العزی بن ابو قیس ہیں، جو اپنے شوہر سہیل بن عمرو کے خاندان سے تھیں۔ مکہ میں ابتدائی دور میں اسلام لائیں، اور بیعت کی، پھر شماخ بن سعید بن قائف بن ارقص سلمی سے نکاح ہوا جس سے عامر پیدا ہوئے، پھر عبداللہ بن اسود بن عمرو سے نکاح ہوا جو بنو مالک بن حسل سے ہیں، ان سے سلیط پیدا ہوئے، پھر عبد الرحمن بن عوف سے نکاح ہوا جس سے سالم پیدا ہوئے، یہ سب محمد بن ابو حذیفہ کے ماں شریک بھائی تھے۔ حدیث عائشہ میں ان کا ذکر ہے۔ ابو داؤد(4) نے محمد بن اسحاق کے طریق سے بحوالہ عبد الرحمن بن قاسم بن محمد بن ابو بکر، انہوں نے اپنے والد سے، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کیا ہے کہ سہلہ بنت سہیل کو استحاضہ کا مرض تھا، وہ نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں آپ صلی اللہ علیہ وسلم نے انہیں ہر نماز کے وقت غسل کرنے کا حکم دیا، جب یہ ان پر دشوار ہوا تو آپ صلی اللہ علیہ وسلم نے انہیں حکم دیا کہ وہ ظہر اور عصر کو ایک غسل کے ساتھ اکٹھا کر کے پڑھیں۔ (الحدیث) سالم مولیٰ ابو حذیفہ کے سوانح میں ان کا ذکر گزر چکا ہے۔ ابن سعد فرماتے ہیں: انہوں نے سالم مولیٰ ابو حذیفہ کو دودھ پلایا، پھر بڑی عمر والے کو دودھ پلانے کا قصہ ذکر کیا۔ پھر خالد بن مخلد کے طریق سے بحوالہ سلیمان بن بلال، انہوں نے یحییٰ بن سعید سے نقل کیا ہے، فرماتے ہیں: مجھ سے عمرہ بنت عبد الرحمن نے روایت کیا کہ ابو حذیفہ کی زوجہ نے سالم کے گھر آنے کا ذکر کیا، آپ صلی اللہ علیہ وسلم نے انہیں حکم دیا کہ اس کو دودھ پلائیں، انہوں نے دودھ پلایا اور وہ بڑے تھے، بدر میں شریک ہوئے تھے۔ پھر واقدی سے بحوالہ محمد بن عبداللہ جو زہری کے بھتیجے ہیں، انہوں نے اپنے والد سے روایت کیا ہے، فرماتے ہیں: وہ ایک ڈبیا میں یا برتن میں بچے کو دودھ پلانے کی مقدار دودھ نکالتی تھیں اور اسے سالم ہر روز پی لیتے یہاں تک کہ پانچ روز گزر گئے، اس کے بعد وہ ان کے گھر جاتے تو کبھی ننگے سر ہوتے تھے، یہ رسول اللہ صلی اللہ علیہ وسلم کی طرف سے سہلہ کے لیے رخصت تھی۔","",{"fn":"(1) اسد الغابہ (۷۰۱۹) الاستيعاب (۳۴۳۷) تجرید (۲۷۹/۲)\n(2) السیرۃ النبویۃ (۲۵۵/۲)\n(3) الطبقات الکبریٰ (۱۹۷/۸)\n(4) ابوداؤد (۲۹۵)"}],[11306,"§۱۱۳۴۴ ۔ سہلہ بنت عاصم\n(1) بن عدی انصاریہ۔ ان کے والد کے سوانح میں ان کا نسب گزر چکا ہے۔ ابو عمر(2) کا قول ہے: ان سے عبد الرحمن بن عوف نے نکاح کیا، نبی کریم صلی اللہ علیہ وسلم سے مروی ہے کہ آپ صلی اللہ علیہ وسلم نے ان کے لیے خیبر کے دن حصہ مقرر کیا۔(3) میں کہتا ہوں: ابن مندہ نے اسے عبد العزیز بن عمران کے طریق سے بحوالہ سعید بن زیاد، انہوں نے حفص بن عمر بن عبد الرحمن بن عوف انہوں نے اپنی دادی سہلہ بنت عاصم سے روایت کیا ہے، فرماتی ہیں: میں خیبر کے دن پیدا ہوئی، تو رسول اللہ صلی اللہ علیہ وسلم نے میرا نام سہلہ رکھا اور فرمایا: ”اللہ تعالیٰ تمہارے کاموں کو آسان کرے۔“ اور میرے لیے حصہ مقرر کیا، جس دن میں پیدا ہوئی میرا نکاح عبد الرحمن بن عوف سے کر دیا۔ واقدی رحمہ اللہ کے نزدیک ایسا ہی ہے۔","",{"fn":"(1) اسد الغابہ (۷۰۲۰) الاستيعاب (۳۴۳۷) تجرید (۲۷۹/۲)\n(2) الاستيعاب (۱۸۶۶/۴)\n(3) المعجم الکبیر (۷۶۴/۲۴) مجمع الزوائد (۲۶۷/۱) جامع المسانید والسنن (۵۴۹/۱۵)"}],[11307,"§۱۱۳۴۵ ۔ سُہیمہ بنت اسلم\n(1) بن حریش، سلمہ بن اسلم کی سگی بہن ہیں، ان کی والدہ سعاد بنت رافع نجاریہ ہیں، ان سے محیصہ بن مسعود نے نکاح کیا، سُہیمہ اسلام لائیں اور بیعت کی، یہ ابن سعد(2) کا قول ہے، ابن حبیب(3) نے بیعت کرنے والی خواتین میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۷۰۲۱) تجرید (۲۷۹/۲)\n(2) الطبقات الکبریٰ (۲۴۴/۸)\n(3) المجد (۴/۲)"}],[11308,"§۱۱۳۴۶ ۔ سہیمہ بنت عمیر المزنیہ\n(1) رکانہ بن عبد یزید مطلبی کی زوجہ ہیں۔ مسند شافعی(2) میں ان کا ذکر ہے، فرماتے ہیں: ہم سے میرے چچا محمد بن علی نے بحوالہ عبداللہ بن سائب، انہوں نے نافع بن عجیر بن عبد یزید سے روایت کیا ہے کہ رکانہ بن عبد یزید نے اپنی زوجہ سہیمہ کو طلاق بائنہ دی، پھر نبی کریم صلی اللہ علیہ وسلم کے پاس آئے اور کہا: میں نے اپنی بیوی سہیمہ کو طلاق بائنہ دی ہے، اللہ کی قسم! میرا ارادہ ایک طلاق کا تھا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”تمہارا ارادہ ایک طلاق کا تھا۔“ تو سیدنا رکانہ نے کہا: اللہ کی قسم! میں نے ایک طلاق کا ارادہ کیا تھا۔ نبی کریم صلی اللہ علیہ وسلم نے ان کو لوٹا دیا، انہوں نے دوسری طلاق سیدنا عمر رضی اللہ عنہ کے زمانے میں دی اور تیسری طلاق سیدنا عثمان رضی اللہ عنہ کے زمانے میں دی۔ ابن مندہ نے عالی سند کے ساتھ اسے حضرت امام شافعی رضی اللہ عنہ سے روایت کیا ہے۔","",{"fn":"(1) اسد الغابہ (۷۰۲۳) تجرید (۲۷۹/۲)\n(2) مسند شافعی (الحدیث: ۴۳۲)"}],[11309,"§۱۱۳۴۷ ۔ سہیمہ بنت عمیر الانصاریہ\nعبداللہ بن حارث بن عمیر یا عمرو یا عمیر کی پھوپھی ہیں۔ ابن مندہ نے عبد اللہ بن حارث کے طریق سے ذکر کیا ہے، نبی کریم صلی اللہ علیہ وسلم نے میری پھوپھی سہیمہ بنت عمیر کے بارے میں ایسا فیصلہ کیا جو اس سے پہلے مسلمانوں میں سے کسی خاتون کے بارے میں نہیں کیا تھا، اس کا مفصل ذکر عبداللہ بن حارث کے سوانح میں گزر چکا ہے۔"],[11310,"§۱۱۳۴۸ ۔ سُہیمہ بنت مسعود\n(1) بن اوس بن مالک بن سواد انصاریہ ظفریہ، جابر بن عبد اللہ کی زوجہ ہیں، اور ان کے بیٹے عبد الرحمن کی والدہ ہیں۔ ابن حبیب(2) نے بیعت کرنے والی خواتین میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۷۰۲۵) تجرید (۲۷۹/۲)\n(2) المحبر (۴۱۳، ۴۱۵)"}],[11311,"§۱۱۳۴۹ ۔ سہیمہ\n(1) رفاعہ قرظی کی زوجہ ہیں، تمیمہ میں ان کا ذکر گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۷۰۲۲) تجرید (۲۷۹/۲)"}],[11312,"§۱۱۳۵۰ ۔ سوادہ\nبعض کا قول ہے: سودہ بنت عاصم بن خالد بن شداد بن عبد اللہ بن قرط بن رزاح بن عدی بن کعب قرشیہ عدویہ، بعض کا قول ہے: سوداء۔ ابو عمر فرماتے ہیں: سودا اسدیہ، بقول بعض: بنت عاصم، خضاب کے بارے میں ان کی حدیث ہے۔ میں کہتا ہوں: اسے ابن ابو عاصم اور ابن مندہ نے ابن ابو اسحاق ازدی کے طریق سے بحوالہ نائلہ مولاۃ ابو عیزار کوفیہ انہوں نے ام عاصم سے، انہوں نے سوداء سے نقل کیا ہے، فرماتی ہیں: میں نبی کریم صلی اللہ علیہ وسلم کے پاس بیعت کرنے کے لیے آئی، تو آپ صلی اللہ علیہ وسلم نے فرمایا: ”جاؤ خضاب لگا کر آؤ، پھر میں تم سے بیعت لیتا ہوں۔“"],[11313,"§۱۱۳۵۱ ۔ سوادہ\n(1) بعض کا قول ہے: سودہ بنت مسرح، میم کی زیر کے ساتھ، سین کے سکون اور راء کے زبر کے ساتھ، بعض کا قول ہے: مسرح کندہ یہ، ان کی حدیث سیدنا حسن بن علی رضی اللہ عنہما کی سیدہ فاطمہ رضی اللہ عنہا کے ہاں ولادت کے بارے میں ہے۔ میں کہتا ہوں: ابن مندہ نے اسے عروہ بن فیروز کے طریق سے ان سے روایت کیا ہے، فرماتی ہیں: جب سیدہ فاطمہ رضی اللہ عنہا کے ہاں ولادت کا وقت آیا تو میں وہاں موجود تھی، نبی کریم صلی اللہ علیہ وسلم تشریف لائے اور فرمایا: ”ان کا کیا حال ہے؟“ میں نے کہا: وہ تکلیف میں ہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”جب ان کے ہاں ولادت ہو جائے تو کسی سے بات چیت نہ کرنا۔“ فرماتی ہیں: ان کے ہاں بیٹا پیدا ہوا میں نے آپ صلی اللہ علیہ وسلم کو چپکے سے بتایا، اور انہیں زرد کپڑے میں رکھا، آپ صلی اللہ علیہ وسلم نے فرمایا: اسے میرے پاس لے آؤ۔ میں نے اسے سفید کپڑے میں لپیٹا، آپ صلی اللہ علیہ وسلم نے ان کے منہ میں اپنا لعاب ڈالا، اور سیدنا علی رضی اللہ عنہ کو بلایا، اور پوچھا: ”تم نے اس کا کیا نام رکھا ہے؟“ انہوں نے کہا: ”جعفر۔“(2) آپ صلی اللہ علیہ وسلم نے فرمایا: ”نہیں! بلکہ اس کا نام حسن ہے۔“ ابو عمر(3) نے سیدہ سودہ رضی اللہ عنہا کے سوانح میں ان کا دوبارہ ذکر کیا ہے، فرماتے ہیں: ان سے ایک حدیث مجہول سند سے مروی ہے، جب سیدہ فاطمہ رضی اللہ عنہا کے ہاں سیدنا حسن رضی اللہ عنہ کی ولادت ہوئی تو وہ دائی تھیں۔","",{"fn":"(1) اسد الغابہ (۷۰۲۵) تجرید (۲۷۹/۲)\n(2) المعجم الکبیر (۷۸۶/۲۴) مجمع الزوائد (۱۷۵/۹) جامع المسانید والسنن (۵۴۳/۱۵، ۵۴۴)\n(3) الاستيعاب (۱۸۶۸/۴)"}],[11314,"§۱۱۳۵۲ ۔ سوادہ (بے نسبت)\n(1) ابن سعد نے نبی کریم صلی اللہ علیہ وسلم سے بیعت کرنے والوں میں ان کا ذکر کیا ہے اور عبد العزیز بن خطاب اور اسماعیل بن ابان الوراق سے بحوالہ نائلہ کوفیہ، انہوں نے ام عاصم سے انہوں نے سوداء سے نقل کیا ہے، فرماتی ہیں: میں بیعت کرنے کے لیے نبی کریم صلی اللہ علیہ وسلم کے پاس آئی تو آپ صلی اللہ علیہ وسلم نے فرمایا: ”خضاب لگاؤ۔“ فرماتی ہیں: میں نے خضاب لگایا پھر میں آئی اور آپ صلی اللہ علیہ وسلم سے بیعت کی۔","",{"fn":"(1) اسد الغابہ (۷۰۲۶) تجرید (۲۷۹/۲)"}],[11315,"§۱۱۳۵۳ ۔ سودہ بنت حارثہ\n(1) بن نعمان انصاریہ۔ ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔ میں کہتا ہوں: یہ عمران بن حزم کی زوجہ ہیں۔ ابن سعد(2) فرماتے ہیں: اسلام لائیں اور بیعت کی، ان سے عبداللہ بن ابی حرام بن قیس بن مالک بن کعب بن عبد الاشہل بن حارثہ بن دینار بن نجار نے نکاح کیا، ان کی والدہ ام خالد بنت خالد بن یعیش ہیں۔","",{"fn":"(1) تجرید (۲۸۰/۲)\n(2) الطبقات الکبریٰ (۳۲۳/۸)"}],[11316,"§۱۱۳۵۴ ۔ سودہ بنت زمعہ\n(1) بن قیس بن عبد شمس قرشیہ عامریہ، ان کی والدہ شموس بنت قیس بن زید انصاریہ ہیں، جو بنو عدی بن نجار تھیں، ان سے سکران بن عمرو نے نکاح کیا جو سہیل بن عمرو کے بھائی تھے، وہ وفات پا گئے تو رسول اللہ صلی اللہ علیہ وسلم نے ان سے نکاح کیا، سیدہ خدیجہ رضی اللہ عنہا کے بعد یہ پہلی خاتون ہیں جن سے آپ صلی اللہ علیہ وسلم نے نکاح کیا، اسے ابن اسحاق(2) نے روایت کیا ہے۔ اور ابن سعد(3) نے مرسل سند سے جس کے رجال ثقات ہیں، اسے روایت کیا ہے۔ سیدہ خدیجہ رضی اللہ عنہا کے سوانح میں گزر چکا ہے کہ خولہ بنت حکیم کہنے لگیں: کیا میں آپ کی طرف سے نکاح کا پیغام نہ دوں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”کیوں نہیں!“ آپ صلی اللہ علیہ وسلم نے فرمایا: اے عورتو! تم اس کے زیادہ مناسب ہو۔ میں نے سیدہ سودہ بنت زمعہ اور سیدہ عائشہ رضی اللہ عنہا کے گھر والوں کو نکاح کا پیغام دیا، آپ صلی اللہ علیہ وسلم نے ان سے نکاح کیا، سیدہ سودہ رضی اللہ عنہا کی رخصتی مکہ میں ہوئی اور سیدہ عائشہ رضی اللہ عنہا اس وقت چھ سال کی لڑکی تھیں، جب آپ صلی اللہ علیہ وسلم مدینہ تشریف لائے تو ان کی رخصتی ہوئی۔ ابن ابو عاصم نے اسے موصولاً نقل کیا ہے، اور سیدہ عائشہ رضی اللہ عنہا کے سوانح میں اس کا ذکر آئے گا۔ ترمذی(4) نے اسے بحوالہ ابن عباس سند حسن سے نقل کیا ہے کہ سیدہ سودہ رضی اللہ عنہا کو خوف ہوا کہ رسول اللہ صلی اللہ علیہ وسلم انہیں طلاق دے دیں گے، کہنے لگیں: مجھے طلاق نہ دیں، اور مجھے اپنے پاس رہنے دیجئے اور میری باری سیدہ عائشہ رضی اللہ عنہا کو دے دیجئے۔ آپ صلی اللہ علیہ وسلم نے ایسا ہی کیا، تو یہ آیت نازل ہوئی: ”و ان پر کوئی گناہ نہیں کہ وہ آپس میں صلح کر لیں اور صلح بہتر ہے۔“(5) ابن سعد نے اسے حدیث عائشہ سے کئی طرق سے روایت کیا ہے، بعض طرق میں ہے کہ آپ صلی اللہ علیہ وسلم نے ان کی طرف طلاق کا پیغام بھیجا، اور بعض طرق میں ہے کہ آپ صلی اللہ علیہ وسلم نے ان سے فرمایا: ”عدت گزارو۔“ دونوں طریق مرسل ہیں، ان دونوں میں ہے کہ وہ آپ صلی اللہ علیہ وسلم کے راستے میں بیٹھیں اور آپ صلی اللہ علیہ وسلم کو واسطہ دیا کہ آپ صلی اللہ علیہ وسلم ان سے رجوع کر لیں، اور اپنی باری کا دن اور رات سیدہ عائشہ رضی اللہ عنہا کو دے دیا۔ معمر کے طریق سے ہے، فرماتے ہیں: مجھے یہ بات پہنچی ہے کہ انہوں نے آپ صلی اللہ علیہ وسلم سے بیان کی، اور کہنے لگیں: مجھے شوہر کی ضرورت نہیں لیکن مجھے پسند ہے کہ قیامت کے دن میں آپ صلی اللہ علیہ وسلم کی ازواج میں سے ہو جاؤں۔ صحیح میں سیدہ عائشہ رضی اللہ عنہا سے مروی ہے کہ سیدہ سودہ رضی اللہ عنہا نے مزدلفہ کی رات نبی کریم صلی اللہ علیہ وسلم سے اجازت چاہی کہ لوگوں کے ہجوم سے پہلے نکلنے کا ارادہ رکھتی ہیں وہ چونکہ فربہ اندام خاتون تھیں آپ نے اجازت مرحمت فرما دی۔ سیدہ عائشہ رضی اللہ عنہا فرماتی ہیں: اگر میں آپ سے اجازت طلب کرتی تو مجھے سوار کرائے جانے سے زیادہ پسند ہوتا۔ سیدہ عائشہ رضی اللہ عنہا کی صحیح حدیث میں ہے: ”کسی کو دیکھ کر مجھے یہ رشک نہیں ہوا کہ اس کے قالب میں میری روح ہوتی سوائے سودہ کے البتہ وہ بہت جلد غصہ سے بھڑک اٹھتی تھیں۔“ ابن سعد رحمہ اللہ کا قول ہے: ہم سے ابو معاویہ نے اعمش سے، انہوں نے ابراہیم سے روایت کیا ہے، فرماتے ہیں: سیدہ سودہ رضی اللہ عنہا نے رسول اللہ صلی اللہ علیہ وسلم سے عرض کیا، میں نے رات آپ کے ساتھ نماز پڑھی، اور رکوع کیا یہاں تک کہ میں نے اپنی ناک پکڑ لی، مجھے خوف ہوا کہ خون نہ بہنے لگے، آپ صلی اللہ علیہ وسلم بہنے لگے، سیدہ سودہ رضی اللہ عنہا کبھی کبھار آپ صلی اللہ علیہ وسلم کو ہنساتی تھیں، یہ روایت مرسل ہے، البتہ اس کے رجال صحیح والے ہیں۔ ابن سعد صحیح سند سے بحوالہ محمد بن سیرین روایت نقل کرتے ہیں کہ سیدنا عمر رضی اللہ عنہ نے سیدہ سودہ رضی اللہ عنہا کے پاس دراہم کی ایک تھیلی بھیجی، قاصد سے آپ رضی اللہ عنہا نے پوچھا یہ کیا ہے؟ لوگوں نے بتایا: یہ دراہم ہیں، کہنے لگیں: کھجوروں کی طرح اتنے زیادہ دراہم، پھر انہیں تقسیم کر دیا۔ ابن مبارک رحمہ اللہ کتاب الزہد میں ابوالا سود یتیم عروہ کی مرسل روایت سے نقل کرتے ہیں کہ سیدہ سودہ رضی اللہ عنہا نے نبی کریم صلی اللہ علیہ وسلم سے عرض کیا: یا رسول اللہ! کیا جب ہم فوت ہو جائیں تو عثمان بن مظعون ہماری نماز پڑھے پھر آپ صلی اللہ علیہ وسلم تشریف لائے گا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”بنت زمعہ، اگر تمہیں موت کا علم ہوتا تو تمہیں یہ بھی پتہ چل جاتا کہ وہ تمہارے گمان سے زیادہ سخت ہے۔“ ابن ابی خیثمہ کا قول ہے کہ سیدہ سودہ بنت زمعہ رضی اللہ عنہا کا انتقال عہد فاروقی کے اواخر میں ہوا، بقول بعض ۵۴ھ میں فوت ہوئیں، اسی کو واقدی رحمہ اللہ نے راجح قرار دیا ہے۔ ان سے ابن عباس رضی اللہ عنہما، یحییٰ بن عبد الرحمن بن اسعد بن زرارہ روایت کرتے ہیں۔","",{"fn":"(1) اسد الغابہ (۷۰۲۷) تجرید (۲۸۰/۲) (۴۱۸/۳)\n(2) السیر والمغازی (۲۵۴، ۲۵۵)\n(3) الطبقات الکبریٰ (۳۹/۸)\n(4) ترمذی (۳۰۴۰)\n(5) سورۃ النساء الآیۃ (۱۲۸)"}],[11317,"§۱۱۳۵۵ ۔ سودہ بنت ابی حبیش الجہنیہ\n(1) ابن سعد رحمہ اللہ کا قول ہے:(2) انہیں اور ان کے والد کو شرف صحابیت اور ہجرت کی سعادت حاصل ہے، اسلام لائیں اور ہجرت کے بعد بیعت کی، پھر ان سے بحوالہ ام صبیہ الجہنیہ کا سیدنا عمر رضی اللہ عنہ کے ساتھ پیش آمدہ قصہ ندا مروی ہے۔","",{"fn":"(1) اسد الغابہ (۷۰۲۸) تجرید (۲۸۰/۲)\n(2) الطبقات الکبریٰ (۲۱۷/۸)"}],[11318,"§۱۱۳۵۶ ۔ سودہ القرشیہ\n(1) ابن مندہ وغیرہ نے عبد الحمید بن بہرام کے طریق سے بحوالہ شہر بن حوشب، انہوں نے سیدنا ابن عباس رضی اللہ عنہما سے روایت کیا ہے، فرماتے ہیں: نبی کریم صلی اللہ علیہ وسلم نے سودہ قرشیہ سے نکاح کا ارادہ فرمایا، ان کی اولاد تھی، کہنے لگیں: پوری مخلوق میں سے آپ مجھے سب سے زیادہ محبوب ہیں، چونکہ میرے چھوٹے چھوٹے بچے ہیں۔ مجھے اچھا نہیں لگتا کہ وہ آپ کے سر پر چڑھے رہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”بہترین عورتیں قریش کی وہ عورتیں ہیں جو اونٹوں پر سوار ہو لیتی ہیں۔“(2) بخاری میں دوسرے طریق سے اس کی اصل ہے، لیکن ان کا نام نہیں لیا گیا۔","",{"fn":"(1) اسد الغابہ (۷۰۳۰) تجرید (۲۸۰/۲)\n(2) مسند احمد (۳۱۹/۱) حلیۃ الاولیاء (۶/۶)"}],[11319,"§۱۱۳۵۷ ۔ سیرین\n(1) سیدنا حسان بن ثابت رضی اللہ عنہ کی ام ولد ہیں۔ اسماعیل بن ابو اویس نے اپنی اسناد سے حدیث افک کے طرق میں سے حضرت عروہ وغیرہ کے طریق سے نقل کیا ہے، قصہ افک میں سیدہ عائشہ رضی اللہ عنہا سے روایت ہے کہ صفوان بن معطل سیدنا حسان بن ثابت رضی اللہ عنہ کے لیے تلوار لے کر بیٹھ گئے، پھر ان پر ایک وار کیا تو صفوان نے حسان سے کہا: ”مجھ سے تلوار کی نوک برداشت کر کیونکہ میں ایسا لڑکا ہوں جب مست ہو جاتا ہوں تو شاعر نہیں رہتا۔“ تو سیدنا حسان رضی اللہ عنہ چیخ کر لوگوں کو مدد کے لیے پکارنے لگے، اتنے میں صفوان وہاں سے بھاگ نکلے۔ سیدنا حسان رضی اللہ عنہ نے آکر سیدنا صفوان رضی اللہ عنہ کے خلاف شکایت کر دی۔ آپ صلی اللہ علیہ وسلم نے پوچھا: ”صفوان کے دار کے بدلے وہ ہبہ کریں۔“ چنانچہ انہوں نے ہبہ کر دیا تو انہوں نے اس کے عوض کھجوروں کا ایک باغ اور سیرین نامی قبطی باندی دے دی، جن سے سیدنا حسان رضی اللہ عنہ کا بیٹا عبد الرحمن پیدا ہوا۔ بشر بن مہاجر کی حدیث میں عبد اللہ بن بُریدہ سے بحوالہ ان کے والد روایت ہے، قبط کے امیر نے نبی کریم صلی اللہ علیہ وسلم کو دو باندیاں ہدیہ کیں، جو آپس میں بہنیں تھیں، ایک کو آپ صلی اللہ علیہ وسلم نے اپنی خوابگاہ کے لیے مخصوص کر لیا، جن سے سیدنا ابراہیم رضی اللہ عنہ پیدا ہوئے، اور رہی دوسری تو آپ صلی اللہ علیہ وسلم نے اسے سیدنا حسان بن ثابت رضی اللہ عنہ کو عطا کیا۔ عبد الرحمن بن حسان نے اپنی والدہ سیرین سے روایت کیا ہے۔ فرماتی ہیں: جب ابراہیم علیہ السلام صاحبزادہ نبی صلی اللہ علیہ وسلم جان کنی کے عالم میں تھے تو میں اور میری بہن جب بھی چھینکیں اور آپ صلی اللہ علیہ وسلم ہمیں چھینکنے سے منع فرما دیتے۔۔۔۔ (الحدیث)(2) ابو نعیم نے بسر بن محمد مودب کے طریق سے، بحوالہ ابو اویس انہوں نے حسین بن عبد اللہ سے انہوں نے عکرمہ سے، انہوں نے ابن عباس رضی اللہ عنہما سے روایت کیا ہے، فرماتے ہیں، رسول اللہ صلی اللہ علیہ وسلم سیدنا حسان رضی اللہ عنہ کے پاس سے گزرے، آپ صلی اللہ علیہ وسلم کے ساتھ آپ صلی اللہ علیہ وسلم کے صحابہ دو قطاریں باندھے کھڑے تھے اور آپ صلی اللہ علیہ وسلم کی باندی سیرین بھی تھیں، آپ صلی اللہ علیہ وسلم ان دونوں قطاروں میں سے گزرنے لگے، تو وہ ان لوگوں کو اشعار سنا رہی تھیں، آپ صلی اللہ علیہ وسلم نے نہ انہیں حکم دیا اور نہ منع کیا اسے ابن وہب نے بحوالہ اویس انہی الفاظ میں نقل تو کیا ہے لیکن یوں کہا ہے کہ ایک گلوکارہ باندی ان کے سامنے گا رہی تھی۔","",{"fn":"(1) اسد الغابہ (۷۰۳۲) تجرید (۲۸۰/۲)\n(2) اسد الغابہ (۳۲۰/۶)"}],[11320,"§۱۱۳۵۸ ۔ سجاح بنت الحارث تمیمیہ\nیہ وہی ہیں جنہوں نے ارتداد میں نبوت کا دعویٰ کیا تھا، کچھ لوگوں نے اس کی پیروی کر لی، پھر مسیلمہ سے صلح کر کے شادی کر لی، اس کے قتل ہونے کے بعد اسلام کی طرف لوٹ آئیں، اسلام لائیں اور سیدنا معاویہ رضی اللہ عنہ کی خلافت تک زندہ رہیں، تاریخ مظفری کے مصنف نے اس کا ذکر کیا ہے۔"],[11321,"§۱۱۳۵۹ ۔ سعدہ بنت قمامہ\n(1) ابو عمر کا قول ہے:(2) ان سے قدامہ نے روایت کی، یہ عورتوں کی امامت کرتی تھیں اور ان کے درمیان کھڑی ہوتی تھیں، بعض کا قول ہے: انہوں نے نبی کریم صلی اللہ علیہ وسلم کا زمانہ پایا۔","",{"fn":"(1) اسد الغابہ (۶۹۸۲) تجرید (۲۷۵/۲)\n(2) الاستيعاب (۱۸۶۰/۴)"}],[11322,"§۱۱۳۶۰ ۔ سلمیٰ بنت جابر الاحمسیہ\nسیدہ زینب رضی اللہ عنہا کے سوانح میں ان کے حالات گزر چکے ہیں۔"],[11323,"§۱۱۳۶۱ ۔ سلمیٰ بنت مالک\nبن حذیفہ بن بدر فزاریہ، ان کا ذکر قسم اول میں گزر چکا ہے۔"],[11324,"§۱۱۳۶۲ ۔ سمیہ\nحارث بن کلدہ کی مولاۃ ہیں، ان کی شرعی باندی تھیں جن سے نافع، نفیع پیدا ہوئے۔ لیکن جب انہیں دیکھا کہ وہ رنگ کے سیاہ فام ہیں تو انکار کر دیا، بعد میں انہوں نے اپنی زوجہ صفیہ بنت ابو عبید بن اسید بن ابو علاج ثقفیہ کو ہبہ کر دیں، انہوں نے اپنے رومی غلام جسے عبید کہا جاتا تھا، اس سے ان کا نکاح کر دیا، جس سے زیاد پیدا ہوئے تو سیدہ صفیہ رضی اللہ عنہا نے انہیں آزاد کر دیا، بلاذری نے یہ بحوالہ عوانہ ذکر کیا ہے کہ گواہ یشگری روم سے سیدہ سمیہ کو قیدی بنا کر لائے اور حارث بن کلدہ کو ہبہ کر دیا۔ پھر ان کا تذکرہ کیا ہے۔ انہوں نے نبی کریم صلی اللہ علیہ وسلم کا زمانہ پایا، ایسی کوئی روایت نہیں جو دلالت کرے کہ انہوں نے حالت اسلام میں نبی کریم صلی اللہ علیہ وسلم کو دیکھا ہو، ممکن ہے وہ اس قول کے عموم میں داخل ہوں۔ حجۃ الوداع کے موقع پر قریش اور ثقیف کے باقی ماندہ تمام لوگ اسلام لائے اور حاضر تھے۔"],[11325,"§۱۱۳۶۳ ۔ سلامہ بنت سعد\n(1) بن شہید، بنو طلحہ کی والدہ ہیں۔ ابن اثیر(2) نے بحوالہ ابن حبیب نقل کیا ہے کہ یہ سلافہ میم کے بدلے فاء کے ساتھ ہے۔","",{"fn":"(1) اسد الغابہ (۶۹۹۳) تجرید (۲۷۷/۲)\n(2) اسد الغابہ (۳۱۰/۵)"}],[11326,"§۱۱۳۶۴ ۔ سلمیٰ، غیر منسوبہ\n(1) ان سے ان کے پوتے عبید اللہ بن علی نے روایت کیا۔ ابن مندہ رحمہ اللہ فرماتے ہیں: اسحاق نے قائد بن عبد الرحمن سے جو مولیٰ عبید اللہ بن علی ہیں، وہ اپنی دادی سلمیٰ سے روایت کرتے ہیں، فرماتی ہیں: ہمارے پاس رسول اللہ صلی اللہ علیہ وسلم تشریف لائے، ہم نے آپ صلی اللہ علیہ وسلم کے لیے حریرہ تیار کیا۔۔۔۔ (الحدیث)(2) ابو نعیم نے اس کا تعاقب کیا ہے کہ وہ ابو رافع کی زوجہ ہیں، ان کا ذکر پہلے گزر چکا ہے، عبید اللہ بن علی بن ابو رافع سے بحوالہ ان کی دادی موصولاً حدیث نقل کی ہے کہ ان کی دادی نے اسے بیان کیا، پھر اسے ذکر کیا، وہ پہلی روایت کی طرح ہے۔","",{"fn":"(1) اسد الغابہ (۷۰۱۰) تجرید (۲۷۸/۲)\n(2) المعجم الکبیر (۷۶۱، ۷۶۲/۲۴) مجمع الزوائد (۲۳/۵)"}],[11327,"§۱۱۳۶۵ ۔ سودہ\n(1) ابو طفیل کی زوجہ ہیں، تابعیہ ہیں، ان سے مرسل روایت ہے۔ ابو نعیم نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے اور عبید اللہ بن عثمان بن خثیم کے طریق سے نقل کیا ہے، فرماتے ہیں: میں ابو طفیل کے پاس گیا، تو وہ انتہائی خوش تھے، میں نے کہا: موقع اچھا ہے کچھ پوچھ لیتا ہوں، میں نے کہا: اے ابو طفیل، وہ لوگ جن پر نبی کریم صلی اللہ علیہ وسلم نے لعنت کی ہے، وہ کون ہیں؟ وہ مجھے بتانے ہی لگے تھے کہ ان کی زوجہ سودہ نے کہا: کیا تمہیں یہ حدیث پہنچی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”بے شک میں انسان ہوں، میں نے اگر کسی کے لیے کوئی بددعا دی ہو تو اللہ تعالیٰ اسے اس کے لیے پاکیزگی اور رحمت بنا دے۔“(2)","",{"fn":"(1) اسد الغابہ (۷۰۲۹) تجرید (۲۸۰/۲)\n(2) جامع المسانید والسنن (۵۴۵/۱۵)"}],[11328,"§۱۱۳۶۶ ۔ شراف\n(1) دحیہ بن خلیفہ کلبی کی بہن ہیں، طبرانی(2) نے اور ابو نعیم نے ان سے جابر جعفی کے طریق سے بحوالہ ابن ابی ملیکہ نقل کیا ہے، فرماتے ہیں، رسول اللہ صلی اللہ علیہ وسلم نے بنو کلب کی ایک خاتون کو نکاح کا پیغام دیا۔ آپ نے سیدہ عائشہ رضی اللہ عنہا کو اسے دیکھنے کے لیے بھیجا آپ دیکھ کے واپس آگئیں۔ کہنے لگیں: مجھے کوئی انوکھی بات تو معلوم نہیں ہوئی۔ تو رسول اللہ صلی اللہ علیہ وسلم ان سے فرمانے لگے: تم نے جب اس کا تل دیکھا تو تمہارا ایک ایک رونگٹا کھڑا نہیں ہوا؟ آپ نے عرض کیا: کوئی راز بھی رہنے دیا کریں۔ ابو موسیٰ نے ذیل میں شراف کے سوانح میں نقل کیا ہے، فرماتے ہیں: بعض کا قول ہے کہ نبی کریم صلی اللہ علیہ وسلم نے ان سے نکاح کیا لیکن رخصتی نہیں ہوئی۔ ابن عبد البر(3) نے اس پر یقین کیا ہے۔ میں کہتا ہوں: ابن سعد کے ہاں ان کا ذکر تصریحاً ہے، بحوالہ ہشام بن کلبی، انہوں نے شرقی بن قطامی سے روایت کیا ہے، فرماتے ہیں: جب خولہ بنت ہذیل وفات پاگئیں تو رسول اللہ صلی اللہ علیہ وسلم نے شراف بنت خلیفہ سے جو سیدنا دحیہ کی بہن ہیں ان سے نکاح کیا، اور رخصتی نہیں ہوئی، پھر سیدہ عائشہ رضی اللہ عنہا سے یہ حدیث روایت کی ہے، بحوالہ محمد بن عمر، انہوں نے ثوری سے، انہوں نے جابر جعفی سے اسے روایت کیا ہے۔","",{"fn":"(1) اسد الغابہ (۷۰۳۴) تجرید (۲۸۰/۲)\n(2) المعجم الکبیر (۸۰۳/۲۴)\n(3) الاستيعاب (۱۸۶۸/۴)"}],[11329,"§۱۱۳۶۷ ۔ شرفہ الدار بنت الحارث\n(1) بن قیس بن ہیشہ انصاریہ، بنو معاویہ سے ہیں۔ ابن حبیب(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۷۰۳۵) تجرید (۲۸۰/۲)\n(2) المحبر (۴۱۳، ۴۱۵)"}],[11330,"§۱۱۳۶۸ ۔ شریرہ\n(1) تصغیر کے ساتھ ہے، بنت حارث بن عوف بن مرہ، سعید بن عقیر نے ذکر کیا ہے کہ وہ حارثہ بن سلامہ بن حارث خصی کی زوجہ ہیں اور حکم بن حارثہ کی والدہ ہیں، انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے بیعت کی۔(2)","",{"fn":"(1) اسد الغابہ (۷۰۳۶) تجرید (۲۸۱/۲)\n(2) اسد الغابہ (۳۲۱/۵)"}],[11331,"§۱۱۳۶۹ ۔ الشَّعثاء\n(1) سیدنا حسان بن ثابت کی زوجہ ہیں جن کے بارے میں انہوں نے اپنے قصیدوں کے شروع میں تشبیب کہی ہے۔ سہیلی نے بیان کیا ہے کہ ان کی زوجہ تھیں اور ان سے ایک بیٹی ہوئی جسے ام فراس کہا جاتا تھا، بعض کا قول ہے: سلام بن مشکم کی بیٹی ہیں، جو یہود مدینہ کے رئیس تھے، جن کے بارے میں سیدنا ابو سفیان بن حرب فرماتے ہیں، جب یہ وہاں اپنی آمد کے دوران اس کے پاس ٹھہرے تھے: ”مجھے پیاس کی حالت میں سلام بن مشکم نے شراب پلا کر سیراب کر دیا۔“ رشاطی نے خزرج کے نسب میں کہا ہے: ام فراس بنت حسان بن ثابت، شعثاء بنت ہلال خزاعیہ ان کی والدہ ہیں۔ اسی طرح ابن اعرابی نے اپنے نوادر میں لکھا ہے کہ شعثاء، خزاعیہ ہیں۔","",{"fn":"(1) اسد الغابہ (۷۰۳۷) تجرید (۲۸۱/۲)"}],[11332,"§۱۱۳۷۰ ۔ الشفاء بنت عبداللہ\n(1) بن عبد شمس بن خلف بن شداد بن عبد اللہ بن قرط بن رزاح بن عدی بن کعب قرشیہ عدویہ، بعض کا قول ہے: خلف کے بجائے خالد ہیں، بعض نے کہا: شداد کی جگہ مراد ہیں، بعض نے کہا: ضرار، سلیمان بن ابو حثمہ کی والدہ ہیں، بقول بعض: ان کا نام لیلیٰ ہے، یہ احمد بن صالح مصری کا قول ہے۔ ابو عمر(2) فرماتے ہیں: ابن سعد(3) کا قول ہے، ان کی والدہ فاطمہ بنت وہب بن عمرو بن عائذ بن عمران مخزومیہ ہیں۔ شفاء ہجرت سے پہلے اسلام لائیں یہ اولین صحابیات میں سے ہیں، نبی کریم صلی اللہ علیہ وسلم سے بیعت کی، وہ عورتوں میں عقلمند اور فضل والی تھیں، نبی کریم صلی اللہ علیہ وسلم ان کے ہاں جاتے اور ان کے گھر قیلولہ فرماتے تھے، انہوں نے آپ صلی اللہ علیہ وسلم کے لیے بستر اور ازار مخصوص کیا تھا، جس میں آپ صلی اللہ علیہ وسلم آرام فرماتے تھے، یہ ان کی اولاد کے پاس رہا، یہاں تک کہ اسے مروان بن حکم نے لے لیا، ان سے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”حفصہ کو پھنسی کا دم سکھاؤ جیسا کہ تم نے اسے لکھنا سکھایا ہے۔“ نبی کریم صلی اللہ علیہ وسلم نے مدینہ میں حکاکین کے مقام میں انہیں ایک حویلی دی وہ اس میں اپنے بیٹے سلیمان کے ساتھ فروکش ہوئیں، سیدنا عمر رضی اللہ عنہ ان کی رائے کو مقدم رکھتے تھے، اور ان کی رعایت کرتے اور فضیلت دیتے۔ اور بعض دفعہ کوئی بازاری ذمہ داری بھی انہیں سونپ دیتے۔ ان سے ان کے دونوں پوتوں ابوبکر اور عثمان نے، جو سلیمان بن ابو حثمہ کے بیٹے ہیں، روایت کی ہے۔ اسی طرح ان سے ان کے بیٹے سلیمان اور ابو سلمہ بن عبد الرحمن، ام المومنین سیدہ حفصہ رضی اللہ عنہا اور ان کے مولا ابو اسحاق نے روایت کی۔ مسند(4) میں مسعودی کے طریق سے، عبد الملک بن عمیر سے بحوالہ آل ابو حثمہ کے کسی آدمی سے، انہوں نے شفاء بنت عبد اللہ سے روایت کی ہے، وہ ہجرت کرنے والوں میں شامل تھیں کہ آپ صلی اللہ علیہ وسلم سے افضل اعمال کے بارے میں سوال کیا گیا، آپ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ پر ایمان، اس کی راہ میں جہاد اور حج مبرور۔“(5) ابن مندہ نے پھوڑے پھنسی کی حدیث ثوری کے طریق سے نقل کی ہے، جو انہوں نے ابن منکدر سے، انہوں نے ابو بکر بن سلیمان بن ابو حثمہ سے انہوں نے سیدہ حفصہ رضی اللہ عنہا سے روایت کیا ہے کہ قریش کی شفاء نامی خاتون پھوڑے پھنسی کا دم کرتی تھیں، آپ صلی اللہ علیہ وسلم نے ان سے فرمایا: ”سیدہ حفصہ رضی اللہ عنہا کو یہ سکھا دو۔“ ثوری رحمہ اللہ سے اس کے موصول اور مرسل ہونے میں اختلاف ہے۔ ابن مندہ اور ابو نعیم نے طویل حدیث نقل کی ہے جو عثمان بن عمر بن عثمان بن سلیمان بن ابو حثمہ سے بحوالہ ان کے والد عثمان منقول ہے جو انہوں نے سیدہ شفاء سے روایت کی ہے کہ وہ جاہلیت میں جھاڑ پھونک کرتی تھیں، جب انہوں نے نبی کریم صلی اللہ علیہ وسلم کی طرف ہجرت کی حالانکہ آپ صلی اللہ علیہ وسلم کی ہجرت سے پہلے وہ مکہ میں آپ صلی اللہ علیہ وسلم سے بیعت کر چکی تھیں، پھر وہ آپ صلی اللہ علیہ وسلم کے پاس آئیں اور کہنے لگیں: یا رسول اللہ! میں جاہلیت میں جھاڑ پھونک کرتی تھی اور میں چاہتی ہوں کہ آکر آپ کو سناؤں، آپ صلی اللہ علیہ وسلم نے فرمایا: ”سناؤ!“ انہوں نے اس دم کو آپ صلی اللہ علیہ وسلم کو سنایا، وہ پھوڑے پھنسی کا دم کرتی تھیں، آپ صلی اللہ علیہ وسلم نے فرمایا: ”اس سے دم کرو اور حفصہ رضی اللہ عنہا کو سکھا دو۔“(6) یہاں تک ابن مندہ کی روایت ہے، اور ابو نعیم نے ان الفاظ کا اضافہ کیا ہے: ”اللہ کے نام سے، یہ پیٹھ کا درمیانی حصہ سخت ہوتا ہے، خیر، جوان کے مونہوں سے لوٹی ہے، جو کسی کو نقصان نہیں دیتی، اے لوگوں کے رب، بیماری کو ختم کر دے۔“ فرماتے ہیں: وہ یہ دم زعفران کی لکڑی پر سات مرتبہ کہتیں، پھر اسے کسی پاک جگہ رکھ دیتیں، بعد میں شراب کے صاف سرکے سے چمچ بھر کر لیتیں اور پھر پھوڑے پھنسی پر اسے لگا دیتیں۔ ابو نعیم نے طبرانی سے صاحب بن کیسان کے طریق سے، بحوالہ ابو بکر بن سلیمان بن ابو حثمہ نقل کیا ہے کہ شفاء بنت عبد اللہ فرماتی ہیں، نبی کریم صلی اللہ علیہ وسلم ہمارے پاس تشریف لائے اور حفصہ میرے پاس بیٹھی ہوئی تھی، آپ صلی اللہ علیہ وسلم نے فرمایا: ”تم یہ پھوڑے پھنسی کا دم کیوں نہیں سکھا دیتی، جیسا کہ تم نے اسے لکھنا سکھایا ہے۔“ ابن ابو عاصم(7) نے اور ابو نعیم نے اپنے طریق سے ان کی سند کے ساتھ بحوالہ زہری نقل کیا ہے، انہوں نے ابو سلمہ سے انہوں نے شفاء بنت عبد اللہ سے روایت کیا ہے، فرماتی ہیں: میں نبی کریم صلی اللہ علیہ وسلم کے پاس آئی تاکہ آپ صلی اللہ علیہ وسلم سے کچھ سوال کروں، آپ صلی اللہ علیہ وسلم میرے سامنے معذرت کرنے لگے اور میں نے کہا اس کی کیا ضرورت ہے؟ اتنے میں نماز کا وقت ہو گیا، میں یہاں سے نکلی کر اپنی بیٹی کے پاس گئی جو ضحیل بن حزن کی زوجہ تھیں، میں نے دیکھا کہ شریل گھر میں ہیں، میں نے اسے کہا: نماز کا وقت ہو گیا ہے اور تم گھر میں بیٹھے ہو، میں اسے ملامت کرنے لگی، اس نے کہا: اے میری خالہ! مجھے ملامت نہ کرو، ہمارے پاس ایک کپڑا تھا جسے نبی کریم صلی اللہ علیہ وسلم نے مجھ سے مانگ لیا، میں نے کہا: میرے ماں باپ آپ صلی اللہ علیہ وسلم پر قربان، میں انہیں ملامت کر رہی تھی، اور ان کا یہ حال ہے مجھے معلوم بھی نہیں۔ شرحبیل فرماتے ہیں: ہماری ایک قمیص تھی جس پر ہم نے پیوند لگا رکھا تھا۔ اس کی سند میں عبد الوہاب بن ضحاک ہیں جو بہت کمزور راوی ہیں، عاتکہ بنت اسید بن ابو العیص کے سوانح میں ان کا تذکرہ ہے۔","",{"fn":"(1) نسب قریش (۳۶۸)\n(2) الاستيعاب (۱۸۶۸، ۱۸۶۹/۴)\n(3) الطبقات الکبریٰ (۱۹۶/۸)\n(4) مسند احمد (۳۷۲/۶)\n(5) مسند احمد (۲۸۶/۶) مستدرک حاکم (۴۱۴/۴) المعجم الکبیر (۷۸۹/۲۴) (۷۹۵/۲۴)\n(6) الاحاد والمثانی (۳/۶) ہیثمی فی مجمع الزوائد (۳۲۴/۱۰) جامع المسانید والسنن (۵۶۱، ۵۷۲/۱۵)\n(7) الاحاد والمثانی (۴۱۶)"}],[11333,"§۱۱۳۷۱ ۔ الشفاء بنت عوف\n(1) بن عبد بن حارث بن زہرہ، زبیر فرماتے ہیں: ام عبد الرحمن بن عوف ہیں، اپنی ماں شریک بہن خیرہ بنت ابو قیس بن مناف کے ساتھ ہجرت کی، ابو عمر(2) فرماتے ہیں: اس قول کے مطابق عبد عوف، عبد الرحمن کے دادا ہوئے، اور عوف ان کے نانا ہوئے، جو دونوں آپس میں بھائی ہیں اور عبد الرحمن بن حارث بن زہرہ کے بیٹے ہیں، ان کے والد عوف کا نام، ان کے چچا کے نام پر رکھا گیا۔ ابن اثیر(3) فرماتے ہیں، ابن ابو عاصم(4) نے عبد الرحمن بن عوف کے سوانح میں ذکر کیا ہے کہ ان کی والدہ عنقاء ہیں، انہیں شفاء بنت عوف بن عبد حارث بن زہرہ کہا جاتا تھا، اس قول کے مطابق یہ ان کے والد کی چچا زاد ہیں۔ ارویٰ بنت کریز کے سوانح میں ابن عباس رضی اللہ عنہما سے منقول ہے کہ عبد الرحمن بن عوف کی والدہ اسلام لائیں۔ ابن سعد(5) فرماتے ہیں: شفاء بنت عوف کی والدہ سلمیٰ بنت عامر بن بیاضہ بن سبیع خزاعی ہیں، سیدہ شفاء رضی اللہ عنہا مہاجر خواتین میں سے ہیں، ان کے بارے میں میت کی طرف سے غلام آزاد کرنے کی سنت جاری ہوئی، وہ نبی کریم صلی اللہ علیہ وسلم کی زندگی میں وفات پاگئیں، تو سیدنا عبد الرحمن نے پوچھا: یا رسول اللہ! میں کیا میں اپنی والدہ کی طرف سے غلام آزاد کر سکتا ہوں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”ہاں“۔ انہوں نے ان کی طرف سے غلام آزاد کیا۔","",{"fn":"(1) اسد الغابہ (۷۰۳۹) تجرید (۲۸۱/۲)\n(2) الاستيعاب (۱۸۷۰/۴)\n(3) ابن اثیر فی اسد الغابہ (۳۲۳/۵)\n(4) الاحاد والمثانی (۱۷۳/۱)\n(5) الطبقات الکبریٰ (۱۸۰/۸)"}],[11334,"§۱۱۳۷۲ ۔ الشفاء بنت عوف\n(1) عبد الرحمن بن عوف کی بہن ہیں، زبیر کا قول ہے: اپنی بہن عاتکہ کے ساتھ ہجرت کی، عاتکہ، ام مسور ہیں۔ بعض کا قول ہے: شفاء، ام مسور ہیں، ابو احمد عسکری نے یہ بیان کیا۔","",{"fn":"(1) اسد الغابہ (۷۰۴۱) تجرید (۲۸۱/۲)"}],[11335,"§۱۱۳۷۳ ۔ شقیقہ بنت مالک\n(1) بن قیس بن محرث بن حارث بن ثعلبہ، بنو مازن بن نجار سے ہیں، شموس کی بہن ہیں، ابن حبیب(2) نے بھی بیعت کرنے والی صحابیات میں ان کا شمار کیا ہے۔ صاحب تجرید کا قول صحیح نہیں کہ ان کے حالات معلوم نہیں ہیں۔ ابن سعد(3) نے بھی ان کا ذکر کیا ہے۔ اور فرمایا: ان کی والدہ سہیمہ بنت عویمر مازنی ہیں، ان سے حارث بن سراقہ بن حارث بن عدی نے نکاح کیا، جس سے عبداللہ اور ام عبید پیدا ہوئے، فرماتے ہیں: شقیقہ اسلام لائیں اور بیعت کی۔","",{"fn":"(1) اسد الغابہ (۷۰۴۲) تجرید (۲۸۱/۲)\n(2) المحبر (۴۲۸)\n(3) الطبقات الکبریٰ (۳۰۵/۸)"}],[11336,"§۱۱۳۷۴ ۔ الشماء\n(1) تشدید کے ساتھ، ان کا ذکر شیماء میں آئے گا۔","",{"fn":"(1) اسد الغابہ (۷۰۴۹) تجرید (۲۸۱/۲)"}],[11337,"§۱۱۳۷۵ ۔ الشموس بنت ابی عامر\n(1) بن صلحی ابن زید بن امیہ انصاریہ، بنو عمرو بن عوف سے ہیں۔ عاصم اور جمیلہ جو ثابت بن ابو الافلح کی اولاد ہے، ان کی والدہ ہیں۔ ابن حبیب(2) نے بیعت کرنے والی خواتین میں ان کا ذکر کیا ہے، جمیلہ بنت ثابت بن ابو الافلح کے سوانح میں ان کا ذکر گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۷۰۴۳) تجرید (۲۸۱/۲)\n(2) المحبر (۴۲۶)"}],[11338,"§۱۱۳۷۶ ۔ الشموس بنت عمرو\n(1) بن حرام بن زید انصاریہ، مسعود بن اوس ظفری کی زوجہ ہیں۔ ابن حبیب(2) نے بیعت کرنے والوں میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۷۰۴۴) تجرید (۲۸۱/۲)\n(2) المحبر (۴۲۶)"}],[11339,"§۱۱۳۷۷ ۔ الشموس بنت مالک\nان کی بہن شقیقہ کے سوانح میں ان کا ذکر گزر چکا ہے۔ ابن حبیب اور ابن سعد(1) نے بیعت کرنے والوں میں ان کا ذکر کیا ہے۔ ابن سعد کا قول ہے: یہ شقیقہ کی سگی بہن ہیں۔","",{"fn":"(1) الطبقات الکبریٰ (۲۸۷/۸)"}],[11340,"§۱۱۳۷۸ ۔ الشموس بنت النعمان\n(1) بن عامر بن مجمع انصاریہ، مدنیہ۔ ان سے عبید بن ودیعہ نے روایت کی کہ نبی کریم صلی اللہ علیہ وسلم نے جب مسجد بنائی تو جبرائیل علیہ السلام کعبے کی جانب آپ صلی اللہ علیہ وسلم کی امامت کرتے، اور آپ صلی اللہ علیہ وسلم کو مسجد کے قبلے کی جانب کھڑا کرتے۔ ابو عمر(2) نے مختصراً ان کا ذکر کیا ہے، ابن ابو عاصم نے موصولاً ان کا ذکر کیا ہے، مذکورہ حدیث یعقوب بن محمد زہری کے طریق سے، عاصم بن سوید سے بحوالہ عقبہ مروی ہے۔ اور اسے زبیر بن بکار نے اخبار مدینہ میں محمد بن حسن مخزومی سے بحوالہ عاصم طویل حدیث روایت کی ہے۔ اسی طرح حسن بن سفیان اور ابن مندہ نے سلمہ کے طریق سے بحوالہ عاصم بن سوید نقل کیا ہے، لیکن شیخ عاصم کی مخالفت کی ہے۔ فرماتے ہیں: بحوالہ اپنے والد، انہوں نے شموس بنت نعمان سے روایت کی ہے، فرماتی ہیں: گویا میں نبی کریم صلی اللہ علیہ وسلم کو دیکھ رہی ہوں جب آپ صلی اللہ علیہ وسلم تشریف لائے اور اس مسجد قباء کی بنیاد رکھی، میں نے آپ صلی اللہ علیہ وسلم کو دیکھا کہ بڑا پتھر اٹھاتے یہاں تک کہ وہ پتھر آپ کو جھکا دیتا اور میں آپ صلی اللہ علیہ وسلم کے شکم مبارک پر مٹی کی سفیدی دیکھ رہی تھی، اتنے میں ایک شخص آیا اور کہنے لگا: یا رسول اللہ! مجھے دے دیجئے، میں اٹھاؤں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”نہیں! اس جیسا ایک اور پتھر اٹھاؤ۔“ یہاں تک کہ اس کی بنیاد رکھ دی۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”بے شک جبرائیل کعبے کی جانب امامت کرتے ہیں، لوگوں کا کہنا ہے، قبلے کی سیدھ میں یہی مسجد تھی۔“ محمد بن حسن کی روایت میں مذکورہ سند سے جو وہ عقبہ تک لے گئے ہیں، مروی ہے کہ شموس بنت نعمان نے انہیں بتایا، اور وہ بیعت کرنے والی صحابیات میں سے ہیں، پھر انہوں نے حدیث نقل کی، جس میں ہے: قریش یا انصار کا ایک شخص آیا اس میں ہے، لوگ کہتے ہیں: آپ صلی اللہ علیہ وسلم کو جبرائیل علیہ السلام نظر آئے جنہوں نے آپ صلی اللہ علیہ وسلم کی قبلہ رخ امامت کرائی، عتبہ فرماتے ہیں: ہم کہتے ہیں: اس سے زیادہ درست قبلہ کی جانب کوئی مسجد نہیں ہے۔ ابن اثیر(3) کو شبابہ کی روایت میں اشکال ہے کہ وہ کعبہ کی طرف امامت کرا رہے تھے، کیونکہ اس وقت قبلہ بیت المقدس تھا، پھر کعبہ کو بنا دیا گیا، اس کا جواب میرے دل میں یہ آیا کہ انہوں نے مطلق کعبہ کہا اور قبلہ مراد تھی، یا حقیقت میں کعبہ ہی ہے، جب اس کی سمت واضح کر دی گئی، جب اس کی طرف پیٹھ کریں تو بیت المقدس سامنے ہوتا، اس میں یہ نکتہ ہے کہ جلد ہی کعبہ، قبلہ قرار دیا جائے گا، لہذا کسی اور نقشے کی ضرورت نہیں پڑے گی، پھر مجھے محمد بن حسن والی روایت کا سیاق ملا، جس سے پہلے احتمال کو ترجیح ہوتی ہے۔","",{"fn":"(1) اسد الغابہ (۷۰۴۶) تجرید (۲۸۱/۲)\n(2) الاستيعاب (۱۸۷۰/۴)\n(3) اسد الغابہ (۳۲۴/۵)"}],[11341,"§۱۱۳۷۹ ۔ الشموس الانصاریہ\nخلافت فاروقی رضی اللہ عنہ میں ابو محجن کے ساتھ ان کا ایک قصہ پیش آیا جس کا تقاضا یہ ہے کہ وہ شرط مذکورہ میں سے ہوں اس لیے کہ جو خاتون اس طور پر شادی شدہ ہو کہ جس کے دیکھنے کے لیے کسی حیلے اور کسی سازش کی ضرورت پڑے اور اس کا خاوند اس کے خلاف شکایت کرے تو اس نے دور نبوی پایا ہوگا اور قصہ بھی فتح قادسیہ سے پہلے کا ہے۔ اس قصے کو میں مردوں کی کنیتوں میں ابو محجن کے حالات کے دوران ذکر کر چکا ہوں۔"],[11342,"§۱۱۳۸۰ ۔ شُمیلہ بنت الحارث\n(1) بن عمرو بن حارثہ بن ہیثم انصاریہ ظفریہ، ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۷۰۴۷) تجرید (۲۸۱/۲)"}],[11343,"§۱۱۳۸۱ ۔ الشیماء بنت الحارث\n(1) بن عبد العزی بن رفاعہ۔ ابو نعیم کا قول ہے: ان کا تذکرہ ہے اور ابو سلیمان یعنی طبرانی نے ان کا ذکر کیا ہے، ان کی کوئی حدیث مروی نہیں۔ یہ نبی کریم صلی اللہ علیہ وسلم کی رضاعی بہن ہیں۔ ابو عمر(2) فرماتے ہیں: الشیماء یا شماء ان کا نام حذافہ ہے۔ ابن اسحاق(3) نے بروایت یونس بن بکیر وغیرہ بحوالہ ان کے ذکر کیا ہے کہ نبی کریم صلی اللہ علیہ وسلم کے رضاعی بہن بھائی یہ ہیں: عبداللہ، انیسہ، حذیفہ، بنو حارث اور حذافہ یہی شیماء ہیں۔ ان کا یہ نام مشہور ہو گیا، فرماتے ہیں: انہوں نے ذکر کیا کہ شیماء نبی صلی اللہ علیہ وسلم کو اپنی والدہ کے ساتھ گود لیتی تھیں۔ ابن اسحاق بحوالہ ابو وجزہ سعدی فرماتے ہیں کہ شیماء جب رسول اللہ صلی اللہ علیہ وسلم کے پاس لائی گئیں تو انہوں نے کہا: یا رسول اللہ! میں آپ کی رضاعی بہن ہوں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”اس کی کیا نشانی ہے؟“ انہوں نے کہا: میں آپ کو اپنے کندھے پر اٹھائے ہوئے تھی کہ آپ نے مجھے دانتوں سے کاٹا تھا۔ آپ صلی اللہ علیہ وسلم نے وہ نشانی پہچان لی، اور اپنی چادر ان کے لیے بچھا دی، پھر ان سے فرمایا: ”یہاں بیٹھو!“ انہیں یہاں بٹھا دیا اور اختیار دیا: ”اگر تم چاہو تو میرے پاس عزت و احترام سے رہو اور اگر چاہو تو میں تمہیں مال و اسباب دوں اور اپنی قوم کے پاس چلی جاؤ۔“ کہنے لگیں: بلکہ مجھے مال و اسباب دے کر اپنی قوم کی طرف بھیج دیجئے۔ آپ صلی اللہ علیہ وسلم نے اسے مال عطا کیا اور انہیں ان کی قوم کی طرف لوٹا دیا، نیز سعد بن بکر کا قول ہے کہ آپ صلی اللہ علیہ وسلم نے انہیں محول نامی غلام اور ایک لونڈی دی۔ انہوں نے ان کا آپس میں نکاح کر دیا۔ تو یوں ان کے پاس غلام لونڈی کی نسل برقرار رہی۔ مستغفری نے سلمہ بن فضل کے طریق سے بحوالہ ابن اسحاق اسی طرح نقل کیا ہے۔ ابن سعد(4) فرماتے ہیں: شیماء اپنی والدہ کے ساتھ نبی کریم صلی اللہ علیہ وسلم کی گود لیتیں اور کندھے پر بٹھاتی تھیں۔ ابو عمر کا قول ہے: رسول اللہ صلی اللہ علیہ وسلم کے شہسواروں نے ہوازن پر شب خون مارا، یہ قیدیوں میں شامل تھیں۔ انہوں نے کہا: میں تمہارے ساتھی کی بہن ہوں، جب وہ انہیں لے کر آئے، تو کہنے لگیں: اے محمد (صلی اللہ علیہ وسلم)! میں آپ کی بہن ہوں۔ آپ صلی اللہ علیہ وسلم نے انہیں علامت سے پہچان لیا، اور انہیں مرحبا کہا، اپنی چادر بچھا کر انہیں بٹھایا اور آپ صلی اللہ علیہ وسلم کی آنکھوں سے آنسو بہنے لگے، آپ صلی اللہ علیہ وسلم نے ان سے فرمایا: ”اگر تمہیں پسند ہے کہ تم اپنی قوم کے پاس لوٹ جاؤ تو میں تمہیں پہنچا دوں، اور اگر تمہیں پسند ہے تو میرے پاس عزت و احترام سے رہو۔“ کہنے لگیں: بلکہ مجھے لوٹا دیجئے۔ وہ اسلام لائیں اور رسول اللہ صلی اللہ علیہ وسلم نے انہیں چوپائے، بکریاں، تین غلام اور ایک لونڈی دی۔ محمد بن معلی ازدی نے کتاب الترغیب میں ذکر کیا ہے۔ فرماتے ہیں: سیدہ شیماء فرماتی ہیں: بچپن میں نبی صلی اللہ علیہ وسلم کو جھولا جھلاتے کہہ رہی تھیں: ”اے ہمارے رب! ہمارے لیے محمد (صلی اللہ علیہ وسلم) کو سلامت رکھنا، تاکہ ہم انہیں جوان اور رعنا دیکھ سکیں، پھر ہم انہیں دیکھیں کہ وہ سردار اور قابل اتباع بن چکے ہیں، اور ان کے دشمنوں اور حاسدین کو تباہ فرما اور انہیں ایسی عزت عطا فرما جو ہمیشہ رہے۔“ ابو عمرہ ازدی جب یہ اشعار پڑھتے تو فرماتے: اللہ تعالیٰ نے کس احسن انداز سے ان کی دعا قبول کی ہے۔","",{"fn":"(1) اسد الغابہ (۷۰۴۹) تجرید (۲۸۱/۲)\n(2) الاستيعاب (۱۸۷۰، ۱۸۷۱/۴)\n(3) السیرۃ النبویۃ (۷۹، ۷۸/۴)\n(4) الطبقات الکبریٰ (۲۵۰/۸)"}],[11344,"§۱۱۳۸۲ ۔ شخبرہ\n(1) بنو تمیم بن اسد سے ہیں، مستغفری نے ان کا ذکر کیا ہے، اور ابوموسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے، وہ لفظی غلطی ہے۔ صحیح یہ ہے کہ شخیرہ سین کے ساتھ ہے جیسا کہ گزر چکا ہے۔","",{"fn":"(1) اسد الغابة (۷۰۳۳) تجرید (۲۸۰/۲)"}],[11345,"§۱۱۳۸۳ ۔ الشفاء بنت عبدالرحمن الأنصاریہ\n(1) مدنیہ، ان سے ابوسلمہ بن عبدالرحمن نے روایت کی، ابو عمر(2) نے ان کا مختصر ذکر کیا ہے۔ ابن مندہ نے بھی ان کا ذکر کیا ہے، لیکن یہ نہیں لکھا کہ انصاریہ ہیں، نہ مدینہ لکھا ہے، اور یہ اضافہ کیا ہے کہ میرے خیال میں یہ پہلی والی ہیں یعنی شفاء بنت عبداللہ بن سلیمان بن ابوشحمہ ایسا ہی ہے جیسے انہوں نے خیال کیا، اور حدیث جس کی طرف انہوں نے اشارہ کیا، وہی ہے جو شفاء بنت عبداللہ کے سوانح میں ذکر کی گئی ہے، زہری کے طریق سے، بحوالہ ابوسلمہ بن عبدالرحمن انہوں نے ان سے شرحبیل بن حسنہ کے قصے میں روایت کی ہے، گویا بعض راویوں نے ان کے والد کے نام میں غلطی کی۔ فرماتے ہیں: عبدالرحمن، جنہوں نے انہیں انصاریہ کہا ہے، انہیں وہم ہوا ہے۔","",{"fn":"(1) اسد الغابة (۷۰۳۷) الاستيعاب (۳۴۴۶) تجرید (۲۸۱/۲)\n(2) الاستيعاب (۱۸۷۰/۴)"}],[11346,"§۱۱۳۸۴ ۔ شقیرہ الأسدیہ\n(1) حبشیہ، ابن مندہ نے ان کا ذکر کیا ہے اور فرمایا: حبشیہ ہیں، اور وہ روایت جو شعیرہ کے بارے میں گزری ہے بیان کی ہے۔ یہی صحیح ہے۔ اس کی طرف ابونعیم نے اشارہ کیا ہے۔ ابوموسیٰ نے جو ان سے روایت کیا ہے، اس میں مستغفری نے ان کا نام لیا ہے۔ ام زفر کے سوانح میں شکیرہ کاف کے ساتھ ہے صحیح یہ ہے کہ وہ قاف کے ساتھ ہے۔","",{"fn":"(1) اسد الغابة (۷۰۴۰) تجرید (۲۸۱/۲)"}],[11347,"§۱۱۳۸۵ ۔ سمیہ\nان سے مرسل حدیث مروی ہے۔ حماد نے بحوالہ ثابت ان سے اور انہوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کی۔ اسے دوسری مرتبہ روایت کیا اور ان کے اور نبی کریم صلی اللہ علیہ وسلم کے درمیان سیدہ عائشہ رضی اللہ عنہا راویہ ہیں، امام احمد رحمہ اللہ نے اسے اپنی مسند میں نقل کیا ہے اور دو طرق سے بحوالہ عفان، انہوں نے حماد سے مسند عائشہ رضی اللہ عنہا میں نقل کیا ہے۔"],[11348,"§۱۱۳۸۶ ۔ شہیدہ\n(1) ام ورقہ انصاریہ، ابن مندہ نے اسماء اعلام میں ان کا ذکر کیا ہے، وہ وہم ہے، کیونکہ یہ ان کا وصف ہے۔ اس بارے میں ان کی صریح حدیث ہے، جو کنیتوں میں آئے گی۔ اس میں ہے، سیدنا عمر رضی اللہ عنہ کا قول ہے کہ جب انہیں ان کے مدبر غلام نے شہید کیا، رسول اللہ صلی اللہ علیہ وسلم نے سچ فرمایا: “ہمارے ساتھ چلو تا کہ ہم شہیدہ سے ملاقات کریں۔”(2)","",{"fn":"(1) اسد الغابة (۷۰۴۸) تجرید (۲۸۱/۲)\n(2) السنن الكبرى (۴۰۶/۱) (۱۳۰/۳) جامع المسانيد والسنن (۵۶۴/۱۵)"}],[11349,"§۱۱۳۸۷ ۔ صخرہ بنت ابی جہل\nاس کا نام عمرو بن ہشام بن مغیرہ مخزومی ہے۔ ان سے ابوسعید بن حارث بن ہشام نے نکاح کیا، جس سے اولاد ہوئی پھر ان سے خالد بن عاص بن ہشام نے نکاح کیا جس سے ام حارث بن خالد پیدا ہوئے۔ زبیر بن بکار رحمہ اللہ نے ان کا ذکر کیا ہے۔ فاکہی رحمہ اللہ نے کتاب مکہ میں ان کا قصہ نقل کیا ہے، یہ اس قسم سے ہیں کیونکہ ان کے والد بدر کے دن مقتول ہوا، یہ فتح کے دن حاضر ہونے والوں میں تھیں۔ یہ ممتاز ہیں، پھر حجتہ الوداع میں شریک تھیں، نبی کریم صلی اللہ علیہ وسلم کے بعد زندہ رہیں، نکاح کیا اور اولاد ہوئی۔"],[11350,"§۱۱۳۸۸ ۔ اصعبہ بنت جبل\n(1) بن عمرو بن اوس، معاذ کی بہن ہیں، جن کے سوانح میں ان کا نسب گزر چکا ہے۔ ابن سعد(2) نے بیعت کرنے والوں میں ان کا ذکر کیا ہے، فرماتے ہیں: ان سے ثعلبہ بن عبید بن ثعلبہ نے نکاح کیا، جس سے عبید پیدا ہوئے۔","",{"fn":"(1) تجرید (۲۸۲/۲)\n(2) الطبقات الكبرى (۳۰۰/۸)"}],[11351,"§۱۱۳۸۹ ۔ الصعبہ بنت الحضرمی\n(1) علاء بن حضرمی کی بہن ہیں، جن کے سوانح میں ان کا نسب مذکور ہے۔ طلحہ بن عبید اللہ جو عشرہ مبشرہ میں سے ہیں، ان کی والدہ ہیں۔ واقدی رحمہ اللہ کا قول ہے: نبی کریم صلی اللہ علیہ وسلم کے زمانے میں وفات پاگئیں، بعض آل طلحہ نے مجھے بتایا کہ وہ اسلام لائیں۔ بخاری(2) نے تاریخ صغیر میں محمد بن یعقوب کے طریق سے، عبداللہ بن رافع سے بحوالہ ان کی والدہ نقل کیا ہے، فرماتی ہیں، سیدہ صعبہ بنت حضرمی باہر نکلیں، میں نے سنا وہ اپنے بیٹے طلحہ سے کہہ رہی تھیں: سیدنا عثمان رضی اللہ عنہ کا محاصرہ سخت ہو گیا ہے، اگر تم ان سے بات کرو تا کہ اس گھیرے کو توڑ دو۔ میں کہتا ہوں: یہ واقدی رحمہ اللہ کے قول سے زیادہ صحیح ہے۔ ابن اثیر(3) جیسا کہ ان کی عادت ہے اہل سیر و نسب کے اقوال کو جید اسناد والوں پر مقدم کرتے ہیں۔","",{"fn":"(1) اسد الغابة (۷۰۵۰) تجرید (۲۸۲/۲)\n(2) التاريخ الصغير (۱۰۸/۱)\n(3) اسد الغابة (۳۲۶/۵)"}],[11352,"§۱۱۳۹۰ ۔ الصعبہ بنت رافع بن امرئ القیس\nانصاریہ اشہلیہ، حواء میں ان کا ذکر گزر چکا ہے۔"],[11353,"§۱۱۳۹۱ ۔ الصعبہ بنت سہل\n(1) بن زید بن عامر بن عمرو بن جشم انصاریہ، ابن حبیب نے بیعت کرنے والوں میں ان کا ذکر کیا ہے۔ ابن سعد(2) فرماتے ہیں: اسلام لائیں اور بیعت کی، یہ محمد بن عمر سے مروی ہے۔","",{"fn":"(1) اسد الغابة (۷۰۵۱)\n(2) الطبقات الكبرى (۲۳۸/۸)"}],[11354,"§۱۱۳۹۲ ۔ صفیہ بنت بجیر الہذلیہ\n(1) انہوں نے ماء زمزم پینے کے بارے میں نبی کریم صلی اللہ علیہ وسلم سے روایت کی۔ ابو عمر(2) نے مختصرا ان کا تذکرہ کیا ہے۔","",{"fn":"(1) اسد الغابة (۷۰۵۲) الاستيعاب (۳۴۵۱) تجرید (۲۸۲/۲)\n(2) الاستيعاب (۱۸۷۱/۴)"}],[11355,"§۱۱۳۹۳ ۔ صفیہ بنت صفیح\nبن حارث بن ابی صعب بن ہنیہ بن سعد بن ثعلبہ دوسیہ۔ سیدنا ابو ہریرہ رضی اللہ عنہ کی والدہ ہیں۔ ابن فتحون نے ان کا ذکر کیا ہے۔ فرماتے ہیں: طبری اور بغوی رحمہما اللہ نے ان کا نام لیا ہے اور نسب بیان کیا ہے۔ میں کہتا ہوں: ان کے اسلام لانے کی روایت حرف الف میں امیمہ کے سوانح میں گزر چکی ہے۔"],[11356,"§۱۱۳۹۴ ۔ صفیہ بنت بشامہ\n(1) اعور کی بہن ہیں جو بنو عنبر بن تمیم سے ہیں۔ ابن حبیب(2) نے محبر میں ایسی خواتین میں ان کا ذکر کیا ہے جنہیں نبی کریم صلی اللہ علیہ وسلم نے نکاح کا پیغام دیا اور ان کی رخصتی نہیں ہوئی۔ میں کہتا ہوں: ابن سعد نے ابن عباس رضی اللہ عنہما سے ایسی سند سے جس میں کلبی رحمہ اللہ بھی ہیں اسے مسنداً نقل کیا ہے کہ نبی کریم صلی اللہ علیہ وسلم نے انہیں نکاح کا پیغام دیا تھا، وہ قیدی ہو کر آئی تھیں، نبی کریم صلی اللہ علیہ وسلم نے انہیں اختیار دیا، فرمایا: “اگر تم چاہو تو مجھے اختیار کر لو، اور اگر چاہو تو اپنے شوہر کے پاس چلی جاؤ۔” کہنے لگیں: “میں اپنے شوہر کو اختیار کرتی ہوں۔” نبی کریم صلی اللہ علیہ وسلم نے انہیں واپس بھیج دیا تو بنو تمیم نے ان پر لعنت کی۔","",{"fn":"(1) اسد الغابة (۷۰۵۳) تجرید (۲۸۲/۲)\n(2) المحبر (۹۶)"}],[11357,"§۱۱۳۹۵ ۔ صفیہ بنت ثابت\n(1) بن فاکہ بن ثعلبہ انصاریہ، بنو خطمہ سے ہیں: ابن حبیب نے بیعت کرنے والوں میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابة (۷۰۵۴) تجرید (۲۸۲/۲)"}],[11358,"§۱۱۳۹۶ ۔ صفیہ بنت الحارث\nبن طلحہ بن ابو طلحہ عبدریہ، ان کا باپ بدر کے دن حالت کفر میں مارا گیا، اس کے بعد ان سے عبداللہ بن خلف خزاعی نے نکاح کیا، اس سے طلحہ بن عبداللہ نے نکاح کیا جو طلحہ طلحات کے نام سے معروف ہیں، ان کی بہن رملہ ہیں، زبیر نے ان کا ذکر کیا ہے، اس کا تقاضا یہ ہے کہ انہیں شرف صحابیت حاصل ہے کیونکہ اہل مکہ حجتہ الوداع میں حاضر تھے اور مکہ میں اس وقت صرف مسلمان ہی تھے، سیدہ صفیہ رضی اللہ عنہا کی یہ روایت بحوالہ سیدہ عائشہ رضی اللہ عنہا سنن میں ہے۔ وہ ان کے پاس واقعہ جمل میں قصر بنو خلف میں آئی تھیں، ان سے محمد بن سیرین وغیرہ نے روایت کی۔"],[11359,"§۱۱۳۹۷ ۔ صفیہ بنت الحارث\nبن کلدہ ثقفیہ۔ مشہور صحابی عقبہ بن غزوان جو امیر بصرہ تھے، ان کی زوجہ ہیں، عمر بن شبہ نے اخبار بصرہ میں ان کا بحوالہ ابوالحسن مدائنی ذکر کیا ہے۔ ان کی بہن اردہ بنت حارث بن کلدہ کے سوانح میں ان کا ذکر گزر چکا ہے۔"],[11360,"§۱۱۳۹۸ ۔ صفیہ بنت حیی\n(1) بن اخطب بن سعنہ بن ثعلبہ بن عبید بن کعب بن ابو حبیب، بنو نضیر سے ہیں، اور لاوی بن یعقوب کی اولاد سے ہیں، پھر حضرت ہارون بن عمران جو حضرت موسیٰ علیہ السلام کے بھائی ہیں، کی اولاد سے ہیں، سلام بن مشکم کی زوجہ تھیں، اس کے بعد کنانہ بن ابو الحقیق کی زوجیت میں آئیں، خیبر کے دن کنانہ مارا گیا، سیدہ صفیہ رضی اللہ عنہا قیدی بنالی گئیں اور دحیہ کے حصہ میں آئیں۔ آپ صلی اللہ علیہ وسلم نے ان سے واپس لے کر آزاد کر کے نکاح کر لیا۔ صحیحین(2) میں یہ حدیث انس سے مختصر اور طویل ثابت ہے۔ ابن اسحاق(3) نے یونس بن بکیر کی روایت سے جو ان کے حوالے سے مروی ہے، فرماتے ہیں: مجھ سے میرے والد اسحاق بن یسار نے بیان کیا، وہ فرماتے ہیں: جب رسول اللہ صلی اللہ علیہ وسلم نے ابو الحقیق کے قلعے قموس کو فتح کیا تو سیدنا بلال رضی اللہ عنہ صفیہ بنت حیی اور ان کی چچا زاد کو لے کر یہودی لاشوں کے پاس سے گزرے، جب انہیں سیدہ صفیہ رضی اللہ عنہا کے ساتھ عورت نے دیکھا تو اپنا چہرہ پیٹنے اور چیخنے چلانے لگی اور مٹی اپنے چہرے پر ڈالنے لگی، آپ صلی اللہ علیہ وسلم نے فرمایا: “اس شیطان کو مجھ سے دور کرو۔” اور سیدہ صفیہ رضی اللہ عنہا کے بارے میں حکم دیا وہ آپ صلی اللہ علیہ وسلم کے پیچھے بٹھا دی گئیں اور ان پر کپڑا ڈال دیا گیا، تو لوگوں نے جان لیا کہ آپ صلی اللہ علیہ وسلم نے انہیں اپنے لیے پسند فرما لیا ہے، اور سیدنا بلال(4) رضی اللہ عنہ سے فرمایا: “کیا تمہارے دل سے رحمت نکال لی گئی تھی جب تم نے ان عورتوں کو ان کے مقتولوں کے پاس سے گزارا؟” سیدہ صفیہ رضی اللہ عنہا نے ان سے پہلے دیکھا کہ چاند ان کی گود میں آگرا ہے، انہوں نے اپنی والدہ سے اس کا ذکر کیا تو انہوں نے ان کے چہرے پر طمانچہ مارا اور کہا: “تمہارے اندر اتنی خود سری آگئی ہے، تم یہ چاہتی ہو کہ عرب کے بادشاہ کی بیوی بنو!” اس کا نشان ان کے چہرے پر باقی رہا، یہاں تک کہ وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس لائی گئیں، آپ صلی اللہ علیہ وسلم نے ان سے اس بارے میں سوال کیا تو انہوں نے اپنے خواب کے بارے میں بتایا۔ ابن سعد رحمہ اللہ نے بحوالہ واقدی رحمہ اللہ ان کی اسناد سے قصہ خیبر میں نقل کیا ہے۔ فرماتے ہیں: آپ صلی اللہ علیہ وسلم خیبر میں رہے، یہاں تک کہ سیدہ صفیہ رضی اللہ عنہا خون حیض سے پاک ہو گئیں۔ آپ صلی اللہ علیہ وسلم نے انہیں اپنے پیچھے سوار کر لیا، جب خیبر سے چھ میل دور منزل پر پہنچے تو آپ صلی اللہ علیہ وسلم نے اپنے اہل کے ساتھ رات گزارنے کا ارادہ کیا تو انہوں نے انکار کر دیا۔ آپ صلی اللہ علیہ وسلم نے اپنے دل میں بات محسوس کی، جب صہباء مقام آیا جو خیبر سے بارہ میل کی مسافت پر ہے، آپ صلی اللہ علیہ وسلم وہاں اترے، ام سلیم نے انہیں کنگھی کی اور عطر لگایا۔ ام سنان اسلمیہ فرماتی ہیں، وہ نہایت خوبصورت تھیں، آپ صلی اللہ علیہ وسلم اپنی ہونے والی بیوی کے پاس گئے، جب صبح ہوئی تو میں نے ان سے پوچھا، نبی کریم صلی اللہ علیہ وسلم نے ان سے کیا فرمایا تھا، انہوں نے کہا مجھ سے فرمایا: “پہلی مرتبہ پڑاؤ پر تم کیوں رکی رہیں؟” میں نے کہا: “مجھے خوف ہوا کہ آپ یہودیوں کے قریب ہیں، اس سے آپ صلی اللہ علیہ وسلم کے ہاں ان کا مرتبہ اور بڑھ گیا۔ ابن سعد نے یہی فرمایا کہ ہمیں عفان نے خبر دی کہ ہم سے حماد نے ثابت سے، انہوں نے سمیہ سے، بحوالہ سیدہ عائشہ رضی اللہ عنہا روایت کی، رسول اللہ صلی اللہ علیہ وسلم ایک سفر میں تھے، سیدہ صفیہ رضی اللہ عنہا کا اونٹ بیمار پڑ گیا، سیدہ زینب بنت جحش رضی اللہ عنہا کے پاس زائد اونٹ تھا، آپ صلی اللہ علیہ وسلم نے ان سے فرمایا: “صفیہ کا اونٹ بیمار ہو گیا ہے، تم اسے اونٹ دے دو۔” کہنے لگیں: کیا میں اس یہودیہ کو اونٹ دوں؟ آپ صلی اللہ علیہ وسلم نے انہیں ذی الحجہ اور محرم دو یا تین مہینے چھوڑ دیا کہ ان کے پاس تشریف نہ لاتے تھے، سیدہ زینب رضی اللہ عنہا فرماتی ہیں: یہاں تک کہ وہ آپ صلی اللہ علیہ وسلم سے نا امید ہو گئیں۔ ابن ابو عاصم نے قاسم بن عوف کے طریق سے بحوالہ ابو ہریرہ رضی اللہ عنہ نقل کیا ہے، فرماتے ہیں: جب نبی کریم صلی اللہ علیہ وسلم خیبر کے مقام پر اترے تو سیدہ صفیہ رضی اللہ عنہا شادی کے کپڑوں میں ملبوس تھیں۔ انہوں نے خواب میں دیکھا کہ سورج اتر کر ان کے سینے پر آ گیا ہے، انہوں نے اپنے شوہر سے یہ بیان کیا، تو اس نے کہا: تم یہ چاہتی ہو کہ اس سردار کی زوجہ بنو جو یہاں اترا ہے۔ فرماتے ہیں: آپ صلی اللہ علیہ وسلم نے اس قلعے کو فتح کیا اور ان کے شوہر کو گرفتار کر کے قتل کر دیا۔ (الحدیث) اس روایت میں ہے: آپ صلی اللہ علیہ وسلم نے چبوترے پر کھجوریں پھیلا دیں، اور کہا: کھاؤ یہ رسول اللہ صلی اللہ علیہ وسلم کا سیدہ صفیہ رضی اللہ عنہا سے نکاح کا ولیمہ ہے۔ ابن سعد رحمہ اللہ نے عطاء بن یسار کے طریق سے ذکر کیا ہے۔ فرماتے ہیں: جب سیدہ صفیہ رضی اللہ عنہا خیبر سے آئیں، تو حارثہ بن نعمان کے گھر اتاری گئیں، انصار کی خواتین نے سنا تو آئیں اور ان کے حسن و جمال کو دیکھنے لگیں، سیدہ عائشہ رضی اللہ عنہا بھی نقاب اوڑھے آئیں، جب وہ باہر نکلیں تو آپ صلی اللہ علیہ وسلم ان کے پیچھے آئے اور فرمایا: “اے عائشہ! کیسی لگیں؟” انہوں نے کہا: مجھے ایک یہودیہ نظر آئی ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: اس طرح نہ کہو، وہ اسلام لا چکی ہیں اور ان کا اسلام سنور گیا ہے۔ ام سنان اسلمیہ اور امیہ بنت ابو قیس کے سوانح میں ان کا ذکر کیا ہے۔ عبداللہ بن عمر رضی اللہ عنہما کے طریق سے نقل کیا ہے، فرماتے ہیں: جب رسول اللہ صلی اللہ علیہ وسلم نے سیدہ صفیہ رضی اللہ عنہا کو دیکھا تو وہاں خواتین میں سیدہ عائشہ رضی اللہ عنہا کو نقاب کئے دیکھا، آپ صلی اللہ علیہ وسلم نے انہیں پہچان لیا اور ان کے کپڑے کا ایک کونہ پکڑا اور فرمایا: “اے سرخ رنگت والی تمہیں یہ کیسی لگیں؟” صحیح سند سے حضرت سعید بن مسیب سے مرسل حدیث سے نقل کیا ہے۔ فرماتے ہیں: سیدہ صفیہ رضی اللہ عنہا آئیں اور ان کے کانوں میں سونے کی بالیاں تھیں، انہوں نے سیدہ فاطمہ رضی اللہ عنہا اور ان کے ساتھ دوسری خواتین کو دے دیں۔ ترمذی(5) نے کنانہ کے طریق سے جو صفیہ کے مولیٰ ہیں نقل کیا ہے، کہ انہوں نے ان سے بیان کیا، فرماتی ہیں: نبی کریم صلی اللہ علیہ وسلم میرے پاس تشریف لائے اور مجھے سیدہ عائشہ اور سیدہ حفصہ رضی اللہ عنہما کی طرف سے کوئی بات پہنچی تھی، میں نے آپ صلی اللہ علیہ وسلم سے بیان کیا، آپ صلی اللہ علیہ وسلم نے فرمایا: “تم نے یہ کیوں نہیں کہا: تم دونوں مجھ سے بہتر کیسے ہو سکتی ہو جبکہ محمد میرے شوہر، ہارون میرے والد اور موسیٰ میرے چچا ہیں؟” انہیں یہ بات پہنچی تھی کہ انہوں نے کہا ہے: ہم ان سے رسول اللہ صلی اللہ علیہ وسلم کے نزدیک زیادہ عزت والی ہیں، ہم آپ صلی اللہ علیہ وسلم کی ازواج ہیں اور آپ صلی اللہ علیہ وسلم کے چچا کی بیٹیاں ہیں۔ ابو عمر فرماتے ہیں: سیدہ صفیہ رضی اللہ عنہا عقل مند، بردبار اور صاحب فضیلت تھیں، ہم نے روایت کیا کہ ان کی لونڈی سیدنا عمر رضی اللہ عنہ کے پاس آئی اور کہنے لگی: سیدہ صفیہ رضی اللہ عنہا ہفتے کے دن کو پسند کرتی ہیں اور یہودیوں سے صلہ رحمی کرتی ہیں، آپ رضی اللہ عنہ نے ان کی طرف آدمی بھیجا اور اس بارے میں سوال کیا، کہنے لگیں: رہا ہفتے کا دن تو جب سے اللہ تعالیٰ نے مجھے جمعے کا دن عطا کیا ہے میں ہفتے کے دن کو پسند نہیں کرتی، اور رہے یہود تو میرے ان میں رشتہ دار ہیں، میں ان سے صلہ رحمی کرتی ہوں، پھر لونڈی سے پوچھا: تمہیں اس پر کس نے آمادہ کیا: کہنے لگیں: شیطان نے آپ رضی اللہ عنہ نے فرمایا: جاؤ تم آزاد ہو۔ ابن سعد نے حسن سند سے بحوالہ زید بن اسلم نقل کیا ہے، فرماتے ہیں: نبی کریم صلی اللہ علیہ وسلم کی ازواج مرض وفات میں آپ صلی اللہ علیہ وسلم کے پاس جمع ہوئیں تو سیدہ صفیہ بنت حیی کہنے لگیں: اللہ کی قسم! اے اللہ کے نبی کاش میں آپ (صلی اللہ علیہ وسلم) کی جگہ ہوتی تو ازواج مطہرات رضی اللہ عنہن ان کو دیکھنے لگیں، آپ صلی اللہ علیہ وسلم نے فرمایا: “کلی کرو۔” وہ کہنے لگیں: کس چیز سے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: “تمہارا اس کی طرف اشارہ کرنے کی وجہ سے اللہ کی قسم وہ سچی ہے، سیدہ صفیہ رضی اللہ عنہا نے نبی کریم صلی اللہ علیہ وسلم سے روایت کی اور ان سے ان کے بھتیجے اور مولیٰ کنانہ اور دوسرے مولیٰ یزید بن معتب نے، زید العابدین علی بن حسین، اسحاق بن عبداللہ بن حارث اور مسلم بن صفوان نے روایت کی۔ بعض کا قول ہے: ۳۶ھ میں وفات پائی، یہ ابن حبان نے روایت کی ہے اور ابن مندہ نے اسی پر اعتماد کیا ہے، وہ غلط ہے۔ کیونکہ حضرت علی بن حسین رحمہ اللہ اس وقت پیدا نہیں ہوئے تھے۔ جبکہ ان کا سیدہ صفیہ رضی اللہ عنہا سے حدیث روایت کرنا صحیحین میں ثابت ہے۔ واقدی رحمہ اللہ کا قول ہے: ۵۰ھ میں وفات پائی،(6) یہ زیادہ صحیح ہے۔ ابن سعد نے امیہ بنت ابو قیس غفاریہ کی روایت سے نقل کیا ہے۔ اس سند میں واقدی ہیں: فرماتے ہیں: میں ان خواتین میں سے تھی، جنہوں نے سیدہ صفیہ رضی اللہ عنہا کو تیار کیا تھا، میں نے انہیں فرماتے ہوئے سنا: میرا نکاح جب رسول اللہ صلی اللہ علیہ وسلم سے ہوا تو میں تقریباً سترہ برس کی تھی، فرماتے ہیں، سیدہ صفیہ رضی اللہ عنہا خلافت معاویہ میں ۵۰ھ میں وفات پا گئیں۔ ابن سعد نے بھی حسن سند سے بحوالہ کنانہ مولیٰ صفیہ نقل کیا ہے، فرماتے ہیں: سیدہ صفیہ رضی اللہ عنہا ایک خچر پر سوار ہو کر آئیں تا کہ سیدنا عثمان رضی اللہ عنہ سے دشمنوں کو دور کریں، انہیں اشتر ملا جس نے خچر کے منہ پر چھڑی ماری، انہوں نے کہا: مجھے واپس لے چلو ایسا نہ ہو کہ میری رسوائی کرے، فرماتے ہیں: انہوں نے سیدنا حسن کو اپنے اور سیدنا عثمان رضی اللہ عنہ کے گھر کے درمیان ٹھہرایا یوں وہ ان کی طرف کھانا اور پانی بھیجتی تھیں۔","",{"fn":"(1) اسد الغابة (۷۰۵۵) الاستيعاب (۳۴۵۲) تجرید (۲۸۲/۲)\n(2) بخاری (۳۷۱) مسلم (۳۴۸۲، ۴۶۴۱)\n(3) السيرة النبوية (۲۶۰/۳، ۲۶۱) شرح السنة (۲۰۰/۶)\n(4) البداية والنهاية (۳۷۲/۳)\n(5) ترمذی (۳۸۹۲)\n(6) اسد الغابة (۳۲۸/۵)"}],[11361,"§۱۱۳۹۹ ۔ صفیہ بنت الخطاب\n(1) سیدنا عمر رضی اللہ عنہ کی بہن ہیں، سیدنا عمر رضی اللہ عنہ کے سوانح میں ان کا نسب گزر چکا ہے، دار قطنی رحمہ اللہ نے کتاب اخوہ میں ان کا ذکر کیا ہے فرماتے ہیں: ان سے سفیان بن عبد الاسد نے نکاح کیا، جس سے اسود پیدا ہوئے۔ قدامہ بن مظعون کے سوانح میں گزر چکا ہے کہ انہوں نے ان سے نکاح کیا، ابوعلی غسانی نے اپنے استدراک میں ان کا ذکر کیا ہے، فرماتے ہیں: ابو عمر(2) نے قدامہ کے حالات میں ان کا ذکر کیا ہے اور علیحدہ ذکر نہیں کیا۔","",{"fn":"(1) اسد الغابة (۷۰۵۶) الاستيعاب (۳۴۵۳)\n(2) الاستيعاب (۱۸۷۲/۴)"}],[11362,"§۱۱۴۰۰ ۔ صفیہ بنت الزبیر\n(1) بن عبدالمطلب بن ہاشم ہاشمیہ، ابن سعد(2) نے بنو ہاشم کے ان لوگوں میں کیا ہے جنہیں رسول اللہ صلی اللہ علیہ وسلم نے خیبر کی کھجوریں کھانے کو دیں، ان کے چالیس وسق تھے، فرماتے ہیں: ان کی والدہ عاتکہ بنت ابو وہب مخزومیہ ہیں، جو ضباعہ کی سگی بہن ہیں۔","",{"fn":"(1) تجرید (۲۸۲/۲)\n(2) الطبقات الكبرى (۳۲/۸)"}],[11363,"§۱۱۴۰۱ ۔ صفیہ بنت شیبہ\n(1) بن عثمان عبدریہ، ان کے والد کے سوانح میں ان کا نسب ذکر ہو چکا ہے، ان کے صحابی ہونے میں اختلاف ہے، یہ قول بعید ہے کہ انہیں دیدار حاصل نہیں، صحیح بخاری میں ان کی حدیث تعلیقاً ثابت ہے، فرماتے ہیں: ابان بن صالح نے بحوالہ حسن بن مسلم، انہوں نے صفیہ بنت شیبہ روایت کی، فرماتی ہیں، میں نے نبی کریم صلی اللہ علیہ وسلم سے سنا: ابن مندہ(2) نے محمد بن جعفر بن زبیر کے طریق سے، عبید اللہ بن عبد اللہ بن ابوثور، انہوں نے صفیہ بنت شیبہ سے نقل کیا ہے۔ فرماتی ہیں: اللہ کی قسم! گویا میں آپ صلی اللہ علیہ وسلم کو دیکھ رہی ہوں جب آپ صلی اللہ علیہ وسلم کعبہ میں داخل ہوئے ... الحدیث۔ انہوں نے ازواج مطہرات سیدہ عائشہ، ام حبیبہ اور ام سلمہ اس کے علاوہ اسماء بنت ابوبکر، ام عثمان بنت سفیان شیبہ کی ام ولد وغیرہ سے روایت کیا، ان سے ان کے بیٹے منصور بن صفیہ، جو عبد الرحمن حجبی کے بیٹے ہیں اور بھتیجے عبدالحمید بن جبیر بن شیبہ، حسن بن مسلم، قتادہ، مغیرہ بن حکیم، عبید اللہ بن عبد اللہ بن ابوثور، میمون بن مہران اور دوسرے لوگوں نے روایت کی۔ ابن معین فرماتے ہیں: ابن جریج نے ان کا زمانہ پایا لیکن ان سے سنا نہیں۔ ابن حبان نے ثقات تابعین میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابة (۷۰۵۸)، الاستيعاب (۳۴۵۴)، تجرید (۲۸۳/۲)\n(2) السيرة النبوية (۴۲/۴)، اسد الغابة (۳۲۹/۵)"}],[11364,"§۱۱۴۰۲ ۔ صفیہ بنت عبدالمطلب\n(1) بن ہاشم قریشیہ ہاشمیہ، رسول اللہ صلی اللہ علیہ وسلم کی پھوپھی اور زبیر بن عوام کی والدہ ہیں جو عشرہ مبشرہ میں سے ہیں۔ سیدنا حمزہ رضی اللہ عنہ کی سگی بہن ہیں، ان کی والدہ ہالہ بنت وہب ہیں جو رسول اللہ صلی اللہ علیہ وسلم کی خالہ ہیں۔ ان سے سب سے پہلے حارث بن حرب بن امیہ نے نکاح کیا وہ وفات پاگئے تو ان سے عوام بن خویلد بن اسد بن عبد العزی نے نکاح کیا، ان سے زبیر اور سائب پیدا ہوئے، اسلام لائیں اور روایت کی، سیدنا عمر رضی اللہ عنہ کی خلافت تک زندہ رہیں، یہ ابو عمر کا قول ہے۔ میں کہتا ہوں: اپنے بیٹے زبیر کے ساتھ ہجرت کی، ابن ابو خیثمہ اور ابن مندہ نے ام عروہ بنت جعفر بن زبیر کی روایت سے بحوالہ ان کے والد انہوں نے اپنی دادی صفیہ سے روایت کیا ہے: جب نبی کریم صلی اللہ علیہ وسلم خندق کی طرف نکلے تو اپنی ازواج کو فارع نامی قلعے میں ٹھہرا دیا، ان کے ساتھ سیدنا حسان بن ثابت رضی اللہ عنہ کو حفاظت کے لئے مقرر کیا۔ فرماتے ہیں: یہود میں سے ایک آدمی آیا اور قلعے پر چڑھنے لگا یہاں تک کہ جھانک کر ہمیں دیکھ لیا۔ میں نے سیدنا حسان رضی اللہ عنہ سے کہا: جاؤ اسے قتل کرو، انہوں نے کہا: اگر میں یہ کر سکتا تو رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ہوتا، سیدہ صفیہ رضی اللہ عنہا فرماتی ہیں: میں اس کی طرف بڑھی اور اسے تلوار ماری یہاں تک کہ اس کا سر کاٹ لیا، میں نے سیدنا حسان رضی اللہ عنہ سے کہا: اٹھو، اس کا سر یہودیوں پر پھینک دو، وہ قلعے سے نیچے ہیں، انہوں نے کہا: اللہ کی قسم! میں یہ بھی نہیں کر سکتا، وہ فرماتی ہیں: میں نے اس کا سر یہودیوں پر پھینک دیا، وہ کہنے لگے: ہم جانتے ہیں، وہ اپنے گھر والوں کو اکیلا چھوڑنے والا نہیں ہے، پھر وہ منتشر ہو گئے۔ ابن اسحاق نے یونس بن بکیر کی روایت میں جو ان سے مروی ہے، بحوالہ ان کے والد، انہوں نے یحییٰ بن عباد بن عبداللہ بن زبیر سے، انہوں نے اپنے والد سے نقل کیا ہے، فرماتے ہیں: سیدہ صفیہ رضی اللہ عنہا فارع نامی قلعے میں تھیں ........ پھر قصہ بیان کیا، اس میں ہے: میں نے نقاب کیا اور ایک کھونٹا اٹھا کر قلعے سے اتر کر اس کی طرف آئی اور کھونٹے سے اسے مارا، بالآخر اسے قتل کر دیا۔ یونس نے بحوالہ ہشام، انہوں نے عروہ سے، انہوں نے اپنے والد سے، انہوں نے صفیہ سے اسی طرح روایت کیا، اور یہ اضافہ کیا: یہ پہلی خاتون ہیں جنہوں نے مشرکین میں سے ایک آدمی کو قتل کیا۔ ابن سعد(2) نے اسے اپنے والد اسامہ سے، انہوں نے ہشام سے، بحوالہ اپنے والد نقل کیا ہے: جب نبی کریم صلی اللہ علیہ وسلم دشمنوں سے جنگ کرنے تشریف لے گئے تو ازواج مطہرات کو سیدنا حسان رضی اللہ عنہ کے قلعے میں چھوڑا، کیونکہ وہ سب سے محفوظ قلعہ تھا، سیدنا حسان رضی اللہ عنہ غزوہ خندق سے پیچھے رہ گئے تھے، ایک یہودی آیا اور قلعے کے ساتھ باتیں سننے کے لئے کھڑا ہو گیا، سیدہ صفیہ رضی اللہ عنہا نے سیدنا حسان رضی اللہ عنہ سے فرمایا: اس کی طرف جاؤ اور اسے قتل کر دو۔ حماد کے طریق سے ہشام سے بحوالہ ان کے والد روایت ہے کہ سیدہ صفیہ رضی اللہ عنہا احد کے دن آئیں، لوگوں کو شکست ہو چکی تھی، ان کے ہاتھوں میں نیزہ تھا، جس سے ان کے چہروں پر مار رہی تھیں، نبی کریم صلی اللہ علیہ وسلم نے فرمایا: “اے زبیر، عورت ہے ابن سعد فرماتے ہیں: سیدنا عمر رضی اللہ عنہ کی خلافت میں وفات پائی۔ سیدہ صفیہ رضی اللہ عنہا نے نبی کریم صلی اللہ علیہ وسلم سے روایت کی، ان سے ....(3) طبرانی نے حفص بن غیاث کے طریق سے بحوالہ جعفر بن محمد انہوں نے ان کے والد سے روایت کیا ہے، فرماتے ہیں: جب نبی کریم صلی اللہ علیہ وسلم وفات پا گئے تو سیدہ صفیہ رضی اللہ عنہا اپنی چادر سے اشارہ کرتے ہوئے کہہ رہی تھیں: آپ صلی اللہ علیہ وسلم کے بعد کئی واقعات اور مصیبتیں پیش آئیں۔ آپ صلی اللہ علیہ وسلم اگر موجود ہوتے تو حوادثات کم ہوتے”۔ ابن اسحاق نے سیرت میں ابراہیم بن سعد وغیرہ کی روایت سے ان کا ذکر کیا ہے کہ انہوں نے نبی کریم صلی اللہ علیہ وسلم کے مرثیہ میں شعر کہے: “رسول اللہ صلی اللہ علیہ وسلم کی وفات کی وجہ سے جب ان کا دن قریب آگیا، اے میری آنکھ! تو لگا تار آنسو بہا”۔ سیرت میں یونس بن بکیر کی روایت سے بحوالہ ابن اسحاق مروی ہے: مجھ سے زہری اور عاصم بن عمر بن قتادہ، محمد بن یحییٰ وغیرہ نے سیدنا حمزہ رضی اللہ عنہ کی شہادت کے بارے میں روایت کی، فرماتے ہیں: سیدہ صفیہ بنت عبدالمطلب اپنے بھائی کو دیکھنے آئیں، ان سے سیدنا زبیر رضی اللہ عنہ ملے اور فرمایا: امی! رسول اللہ صلی اللہ علیہ وسلم آپ سے کہہ رہے ہیں کہ واپس لوٹ جائیں۔ ٹھہر کر انہوں نے کہا: کس وجہ سے، مجھے خبر ملی ہے کہ میرے بھائی کا مثلہ ہوا ہے۔ یہ اللہ کے راستے میں ہوا ہے تو اس میں ہمیں راضی رہنا چاہئے۔ میں ضرور صبر کروں گی اور اللہ سے ثواب کی امید رکھتی ہوں، ان شاء اللہ، سیدنا زبیر رضی اللہ عنہ آئے اور رسول اللہ صلی اللہ علیہ وسلم کو خبر دی، آپ صلی اللہ علیہ وسلم نے فرمایا: “اسے جانے دو” وہ ان کے پاس آئیں، اور اللہ سے ان کے لئے مغفرت طلب کی، پھر آپ صلی اللہ علیہ وسلم نے حکم دیا تو وہ دفن کئے گئے۔(4) سیدہ صفیہ رضی اللہ عنہا نے نبی کریم صلی اللہ علیہ وسلم کے مرثیہ میں یہ اشعار کہے: “آج کا دن جو آپ صلی اللہ علیہ وسلم پہ گزرا ہے، اس کا سورج اگر چہ روشن تھا یوں لگتا ہے وہ بے نور ہو گیا”۔","",{"fn":"(1) اسد الغابة (۵۰۵۹)، الاستيعاب (۳۴۵۵)، تجرید (۲۸۳/۲)\n(2) الطبقات الكبرى (۲۷/۸)\n(3) بياض في الأصل\n(4) السيرة النبوية (۷۷/۳)"}],[11365,"§۱۱۴۰۳ ۔ صفیہ بنت عبیدہ\nبن حارث بن مطلب بن عبد مناف مطلبیہ، ابن سعد نے ان کے والد کے سوانح میں ان کا ذکر کیا ہے۔ ۲ھ میں ان کی وفات ہوئی۔"],[11366,"§۱۱۴۰۴ ۔ صفیہ بنت عبید\nبن اسد بن ابو علاج ثقفیہ، حارث بن کلدہ کی زوجہ ہیں، ان کے سوانح میں گزر چکا ہے کہ اسلام لائیں اور انہیں شرف صحابیت حاصل ہے۔ زیاد کی والدہ سمیہ کے سوانح میں گزر چکا ہے کہ حارث نے انہیں سیدہ صفیہ کو ہبہ کر دیا، انہوں نے اپنے غلام عبید سے ان کا نکاح کر دیا۔"],[11367,"§۱۱۴۰۵ ۔ صفیہ بنت عبید\nبن ربیعہ بن عبد شمس عبشمیہ، شماس بن عثمان بن شرید کی زوجہ ہیں، بلاذری نے اس کا ذکر کیا ہے۔"],[11368,"§۱۱۴۰۶ ۔ صفیہ بنت عطیہ\nان سے غیاث بن عبد العزیز نے روایت کی، یہ ان کی دادی ہیں، ابوداؤد کے ہاں ابو بحر بکراوی کی روایت سے ان کی حدیث ہے، جو ان سے مروی ہے، وہ ان سے روایت کرتے ہیں: میں عبد القیس کی خواتین کے ساتھ سیدہ عائشہ رضی اللہ عنہا کے پاس آئی، ہم نے ان سے کھجور اور کشمش کے بارے میں سوال کیا .... الحدیث بخاری فرماتے ہیں: اسے عبدالواحد بن واصل نے غیاث سے انہوں نے اپنی دادی سے روایت کیا ہے، فرماتی ہیں، کبھی کبھار ہم رسول اللہ صلی اللہ علیہ وسلم کی نبیذ میں مٹھی بھر کشمش ڈال دیتے ہیں، فرمایا: پہلا قول زیادہ صحیح ہے۔"],[11369,"§۱۱۴۰۷ ۔ صفیہ بنت عمر\n(1) بن خطاب قرشیہ عدویہ: طبرانی نے ان کا ذکر کیا ہے، ابونعیم، پھر ابو موسیٰ نے ان کی پیروی کی ہے۔ محمد بن سہل اسدی کے طریق سے، شریک سے بحوالہ عبدالکریم، انہوں نے عکرمہ سے، انہوں نے ابن عباس سے نقل کیا ہے: کہ صفیہ بنت عمر بن خطاب خیبر کے دن نبی کریم صلی اللہ علیہ وسلم کے ساتھ تھیں۔","",{"fn":"(1) اسد الغابة (۷۰۶۱)، تجرید (۲۸۳/۲)"}],[11370,"§۱۱۴۰۸ ۔ صفیہ بنت عمرو\nبن عبدود عامریہ خندق کے دن ان کا باپ مارا گیا، اس کے قتل کا قصہ سیدنا علی رضی اللہ عنہ کے ہاتھوں مشہور ہے۔ سہل بن عمرو کی زوجہ ہیں، جن سے عمرو بن سہل پیدا ہوئے، لوگ کہنے لگے تم نیک بخت ہو، پھر انس بن سہل پیدا ہوئے تو لوگوں نے کہا: تم نے نجابت اور شرافت کو جمع کر لیا ہے۔ ہشام بن کلبی نے ابوعوانہ سے یہ ذکر کیا ہے۔"],[11371,"§۱۱۴۰۹ ۔ صفیہ بنت محمیہ\n(1) حارث بن محمیہ کی بہن اور عبداللہ بن حارث کی پھوپھی ہیں۔ ان دونوں کا ذکر گزر چکا ہے۔ فضل بن عباس بن عبدالمطلب نے ان سے نکاح کیا، ابن اثیر(2) فرماتے ہیں: مسلم(3) میں ربیعہ بن حارث بن عبدالمطلب کی حدیث میں ان کا ذکر ہے۔ جب انہوں نے اور سیدنا عباس رضی اللہ عنہ نے نبی کریم صلی اللہ علیہ وسلم سے گورنری کا مطالبہ کیا، آپ صلی اللہ علیہ وسلم نے محمیہ سے فرمایا: اپنی بیٹی کا فضل سے نکاح کر دو لیکن اس کا نام نہیں لیا۔","",{"fn":"(1) اسد الغابة (۷۰۶۲)، الاستيعاب (۳۴۵۷)، تجرید (۲۸۳/۲)\n(2) اسد الغابة (۳۳۰/۵)\n(3) مسلم (۲۴۷۸) (۲۴۷۹)"}],[11372,"§۱۱۴۱۰ ۔ صفیہ\n(1) رسول اللہ صلی اللہ علیہ وسلم کی خادمہ ہیں، ان سے امتہ اللہ بنت رزینہ نے کسوف کے بارے میں مرفوع حدیث روایت کی ہے، یہ ابو عمر(2) کا قول ہے۔","",{"fn":"(1) اسد الغابة (۷۰۵)، الاستيعاب (۳۴۵۸)، تجرید (۲۸۲/۲)\n(2) الاستيعاب (۱۸۷۳/۷)"}],[11373,"§۱۱۴۱۱ ۔ صفیہ\n(1) بے نسبت، صحابیہ ہیں، ان سے اسحاق بن عبد اللہ بن حارث نے روایت کی، فرماتی ہیں، میرے پاس رسول اللہ صلی اللہ علیہ وسلم تشریف لائے، میں نے آپ صلی اللہ علیہ وسلم کے سامنے کندھے کا گوشت پیش کیا، آپ صلی اللہ علیہ وسلم نے کھایا اور نماز پڑھی، وضو نہیں کیا۔ ابو عمر(2) نے اسی طرح مختصر ذکر کیا ہے۔ تہذیب میں مزی کی کاوش کا تقاضا یہ ہے کہ وہ صفیہ بنت حیی ہیں۔","",{"fn":"(1) اسد الغابة (۷۰۶۴)، الاستيعاب (۳۴۵۹)، تجرید (۲۸۳/۲)\n(2) الاستيعاب (۱۸۷۴/۴)"}],[11374,"§۱۱۴۱۲ ۔ صفیہ اخری\n(1) بے نسبت۔ صحابہ میں سے ایک خاتون ہیں، اہل کوفہ کے پاس ان کی حدیث ہے، ان سے مسلم بن صفوان نے روایت کی، ابن عبدالبر(2) نے اسی طرح روایت کیا ہے۔ ابن مندہ کو یقین ہے کہ یہ وہی صفیہ ہیں جن کا ذکر کیا گیا ہے۔ ابو نعیم نے ان کی پیروی کی ہے کہ وہ نبی کریم صلی اللہ علیہ وسلم کی زوجہ بنت حیی ہیں۔ ادریس مرہبی کے طریق سے بحوالہ مسلم بن صفوان، انہوں نے سیدہ صفیہ سے حدیث نقل کی ہے، فرماتی ہیں: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “لوگ بیت اللہ پر حملہ کرنے سے نہیں رکیں گے یہاں تک کہ جب وہ بیداء مقام پر ہوں گے تو شروع سے لے کر آخر تک دھنسا دیے جائیں گے .... الحدیث(3)","",{"fn":"(1) اسد الغابة (۷۰۶۳)، الاستيعاب (۳۴۶۰)، تجرید (۲۸۳/۲)\n(2) الاستيعاب (۱۸۷۴/۴)\n(3) مسند احمد (۳۳۶/۶)"}],[11375,"§۱۱۴۱۳ ۔ صفیہ\n(1) بے نسبت۔ ابو منصور دیلمی نے مسند فردوس میں حسن بن ابو جعفر سے انہوں نے محمد بن عبدالرحمن سے انہوں نے سیدہ صفیہ رضی اللہ عنہا سے انہوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کیا ہے، فرمایا: “زمزم کا پانی ہر بیماری کی شفا ہے حسن میں ضعف ہے۔ اور ان کے شیخ کو میں نہیں پہچانتا، مجھے معلوم نہیں کہ اس نے سیدہ صفیہ رضی اللہ عنہا سے سنا یا نہیں؟","",{"fn":"(1) اسد الغابة (۷۰۵۲) تجرید (۲۸۲/۲)"}],[11376,"§۱۱۴۱۴ ۔ الصماء بنت بسر المازنیہ\n(1) انہیں، ان کے والدین اور بھائی عبداللہ بن بسر کو شرف صحابیت حاصل ہے، ہفتے کو روزے کی ممانعت کے بارے میں نبی کریم صلی اللہ علیہ وسلم سے روایت کی۔(2) بعض کا قول ہے: عبد اللہ کی پھوپھی ہیں، بعض نے کہا: ان کی خالہ ہیں، ابن مندہ نے ولید بن مسلم وغیرہ کے طریق سے بحوالہ ثور بن یزید، انہوں نے خالد بن معدان سے، انہوں نے عبداللہ بن بسر سے انہوں نے اپنی بہن صماء سے روایت کیا ہے۔ اور عالی سند سے ابو عاصم سے بحوالہ ثور، معاویہ بن صالح کے طریق سے، انہوں نے ابوعبداللہ بن بسر سے، انہوں نے اپنے والد سے، انہوں نے اپنی پھوپھی صماء سے نقل کیا ہے، اور فضیل بن فضالہ سے بحوالہ عبداللہ بن بسر انہوں نے اپنی خالہ صماء سے نقل کیا ہے، اصحاب سنن نے ان کی حدیث ثور کے طریق سے نقل کی ہے، نسائی نے ان کے طرق کی تخریج اور ان کے راویوں کے بیان اختلاف کا ذکر زیادہ کیا ہے۔ انہوں نے رحیم اول کو ترجیح دی، ابو زرعہ دمشقی فرماتے ہیں: مجھ سے دخیم نے فرمایا: اہل بیت چار ہیں، جنہیں شرف صحابیت حاصل ہے، بسر اور اس کے دونوں بیٹے عبد اللہ اور عطیہ اور ان کی بہن صماء۔","",{"fn":"(1) اسد الغابة (۷۰۶۵)، الاستيعاب (۳۴۶۱)، تجرید (۲۸۳/۲)\n(2) ابوداؤد (۲۴۲۱) ترمذی (۷۴۴)"}],[11377,"§۱۱۴۱۵ ۔ الصمیتہ\n(1) لیٹیہ، بعض کا قول ہے: داریہ، نسائی اور ابن ابو عاصم نے ان کی حدیث عقیل کے طریق سے، بحوالہ زہری انہوں نے عبید اللہ سے، انہوں نے عبد اللہ بن عقبہ سے، انہوں نے سمیتہ سے نقل کی ہے۔ رسول اللہ صلی اللہ علیہ وسلم کی پرورش میں تھیں، فرماتی ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: “تم میں سے جس سے ہو سکے وہ مدینہ میں مرے تو ضرور ایسا کرے، کیونکہ جو اس میں مرے گا، قیامت کے دن میں اس کا سفارشی اور گواہ ہوں گا۔” ابن مندہ فرماتے ہیں: اسے صالح نے ابو اخضر سے بحوالہ زہری رحمہ اللہ نقل کیا ہے، فرماتے ہیں: وہ یتیمہ سیدہ عائشہ رضی اللہ عنہا کی پرورش میں تھیں۔ میں کہتا ہوں: دونوں روایتوں میں بعد نہیں، کیونکہ جو سیدہ عائشہ رضی اللہ عنہا کی پرورش میں ہوں گی وہ نبی کریم صلی اللہ علیہ وسلم کی پرورش میں ہیں۔ اور صالح بن ابو اخضر ضعیف ہے۔ اسے یونس نے زہری رحمہ اللہ سے انہوں نے عبید اللہ سے انہوں نے صمیتہ سے جو بنو لیث کی خاتون ہیں روایت کیا ہے، وہ بیان کرتے ہیں کہ انہوں نے سنا ..... پھر حدیث ذکر کی۔ اس میں یہ اضافہ ہے: زہری رحمہ اللہ فرماتے ہیں: پھر میں عبید اللہ بن عبد اللہ بن عمر سے ملا اور ان کی حدیث کے بارے میں سوال کیا، انہوں نے مجھ سے صمیتہ کے حوالے سے حدیث بیان کی، یہ ابن وہب کی بحوالہ یونس روایت ہے، جو عقیل کی روایت کے موافق ہے، اسے عتبہ نے بحوالہ یونس روایت کیا ہے عبید اللہ اور صمیتہ کے درمیان صفیہ بنت ابو عبید کا ذکر کیا ہے۔ اسے ابن ابو ذئب کے بحوالہ زہری روایت کیا فرماتے ہیں: بحوالہ عبید اللہ، انہوں نے ایک یتیم عورت سے انہوں نے صفیہ بنت ابو عبید، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے حدیث ذکر کی۔","",{"fn":"(1) اسد الغابة (۷۰۶۶)، الاستيعاب (۳۴۶۲)، تجرید (۲۸۳/۲)"}],[11378,"§۱۱۴۱۶ ۔ صفیہ بنت ابی عبید الثقفیہ\n(1) عبداللہ بن عمر بن خطاب کی زوجہ ہیں، ان کے والد کے سوانح میں ان کا نسب گزر چکا ہے۔ ابو عمر(2) نے ان کا ذکر کیا ہے اور فرمایا: انہیں روایت حاصل ہے، ان سے مولیٰ ابن عمر نے روایت کی، اسی طرح فرمایا: انہوں نے روایت کی، اس سے ظاہر ہوتا ہے کہ انہوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کی، یہ ابن سعد(3) رحمہ اللہ کے قول کے خلاف ہے۔ انہوں نے ان راویوں میں ان کا ذکر کیا ہے جنہوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت نہیں کی اور آپ صلی اللہ علیہ وسلم کی ازواج سے روایت کی، ابن سعد کا اسی طرح قول ہے: ان کی والدہ علیلہ بنت اسید بن ابو عاص ہیں، جو عتاب امیر مکہ کی بہن ہیں۔ ابن مندہ کا قول ہے: انہوں نے نبی کریم صلی اللہ علیہ وسلم کا زمانہ پایا اور سیدہ عائشہ اور حفصہ رضی اللہ عنہما سے روایت کی، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے حدیث نہیں سنی۔ دار قطنی کا قول ہے: انہوں نے نبی کریم صلی اللہ علیہ وسلم کا زمانہ نہیں پایا، یہ انہوں نے سنن میں کتاب الوتر میں عبداللہ بن نافع کے طریق سے جو مولی ابن عمر ہیں، ان کی والدہ سے بحوالہ ام سلمہ وتر کی قضا کے بارے میں مرفوع حدیث نقل کرنے کے بعد فرمایا، ایک روایت میں ہے: بحوالہ عبد اللہ بن نافع، انہوں نے اپنے والد سے، انہوں نے صفیہ بنت ابو عبید سے روایت کیا ہے، پھر حدیث ذکر کی، اس میں یہ اضافہ ہے: نافع کا ام سلمہ رضی اللہ عنہا سے حدیث کا سماع درست نہیں، اور سند میں پے در پے تین راوی ضعیف ہیں۔ واقدی رحمہ اللہ نے موسیٰ بن ضمرہ بن سعید سے بحوالہ ان کے والد ذکر کیا ہے: ان سے سیدنا عبد اللہ بن عمر رضی اللہ عنہما نے خلافت عمر میں نکاح کیا، یہ اس قول کے زیادہ قریب ہے کہ ان کی ولادت نبی کریم صلی اللہ علیہ وسلم کے زمانے میں ہوئی۔ لہذا ادراک کی نفی کے قول کو ادراک سماع پر محمول کیا جائے گا، گویا وہ نبی کریم صلی اللہ علیہ وسلم کی وفات کے بعد بالغ ہوئیں۔ ان سے ان کے شوہر کے بیٹے سالم، ان کے خاوند کے مولی نافع، عبداللہ بن دینار، موسی بن عقبہ نے روایت کی، عجلی اور ابن حبان نے ثقات میں ان کا ذکر کیا ہے۔ ابن سعد نے خالد بن مخلد سے، انہوں نے عبداللہ بن عمری سے، انہوں نے نافع سے بحوالہ ابن عمر روایت کیا ہے: سیدنا عمر رضی اللہ عنہ نے میری طرف سے چار سو دینار سیدہ صفیہ رضی اللہ عنہا کے مہر میں دیئے، میں نے چپکے سے اس میں دو سو درہم کا اضافہ کر دیا۔ صحیح سند کے ساتھ ان سے روایت ہے کہ انہوں نے سیدنا عمر رضی اللہ عنہ کو فجر کی نماز میں سورہ کہف پڑھتے ہوئے سنا۔ ابن سعد رحمہ اللہ فرماتے ہیں: سیدنا ابن عمر رضی اللہ عنہما کے ہاں ان سے واقد، ابو بکر، ابو عبیدہ، عبد اللہ، عمر، حفصہ اور سودہ رضی اللہ عنہم پیدا ہوئے۔ پھر جید سند سے بحوالہ نافع نقل کیا ہے، فرماتے ہیں: سیدہ صفیہ رضی اللہ عنہا بوڑھی ہوگئی تھیں اور سواری پر کعبہ کا طواف کرتی تھیں۔ صحیحین میں ہے: سیدنا عمر رضی اللہ عنہ حجۃ الوداع سے لوٹ کر آئے تو انہیں کہا گیا: سیدہ صفیہ رضی اللہ عنہا سواری پر پیچھے آرہی ہیں، انہوں نے چلنے میں جلدی کی اور دو نمازوں کو اکٹھا کر کے پڑھا .... (الحدیث) اس کا مطلب ہوا، یہ سیدنا ابن زبیر رضی اللہ عنہما کی خلافت کا واقعہ ہے۔","",{"fn":"(1) اسد الغابة (۷۰۶۰)، الاستيعاب (۳۴۵۶)، تجرید (۲۸۳/۲)\n(2) الاستيعاب (۱۸۷۳/۴)\n(3) الطبقات الكبرى (۳۴۶/۸، ۳۴۷)"}],[11379,"§۱۱۴۱۷ ۔ الصہباء بنت ربیعہ\nبن بحیر بن عبد بن علقمہ بن حارث بن عقبہ ثعلبیہ، ان کی کنیت ام حبیب ہے، انہوں نے نبی کریم صلی اللہ علیہ وسلم کا زمانہ پایا، عین نمر کے قیدیوں میں سے تھیں، سیدنا خالد بن ولید رضی اللہ عنہ نے انہیں دوسرے قیدیوں کے ساتھ سیدنا ابو بکر صدیق رضی اللہ عنہ کی طرف بھیجا، وہ سیدنا علی رضی اللہ عنہ کے حصے میں آئیں جن سے عمر اکبر اور رقیہ پیدا ہوئے۔"],[11380,"§۱۱۴۱۸ ۔ صفیہ (بے نسبت)\nان سے اسحاق بن عبداللہ نے روایت کی۔"],[11381,"§۱۱۴۱۹ ۔ صفیہ (بے نسبت)\n(1) ان سے مسلم بن صفوان نے روایت کی، پہلی قسم میں ان دونوں کا ذکر گزر چکا ہے۔ ہم نے ان دونوں کے بارے میں قول ذکر کیا ہے کہ یہ صفیہ بنت حیی ہیں، مسلم بن صفوان نے ان سے جو روایت کی ہے، غالب گمان ہے کہ صفیہ بنت حیی ہیں، اور دوسری کا احتمال ہے۔ واللہ اعلم!","",{"fn":"(1) تجرید (۲۸۳/۲)"}],[11382,"§۱۱۴۲۰ ۔ ضباعہ بنت الزبیر\n(1) بن عبد المطلب ہاشمیہ، نبی کریم صلی اللہ علیہ وسلم کی چچا زاد ہیں، مقداد بن اسود کی زوجہ ہیں، ان سے عبداللہ اور کریمہ پیدا ہوئے، زبیر کا قول ہے: زبیر بن عبدالمطلب کی ضباعہ سے نسل چلی، ام حکم ان کی بہن ہیں، یہ ابن سعد(2) رحمہ اللہ کا قول ہے۔ فرماتے ہیں: عاتکہ بنت ابو وہب بن عمرو بن عائذ بن عمران بن مخزوم ان کی والدہ ہیں، ان کے بیٹے عبداللہ یوم جمل میں سیدہ عائشہ رضی اللہ عنہا کا ساتھ دیتے ہوئے شہید ہوئے، ضباعہ نے نبی کریم صلی اللہ علیہ وسلم سے اور اپنے شوہر مقداد سے روایت کی۔ ان سے ابن عباس، عائشہ اور ان کی بیٹی کریمہ بنت مقداد، ابن المسیب، عروہ، اعرج وغیرہ نے روایت کی۔ ابوداؤد، نسائی، ترمذی میں حج میں شرط لگانے کے بارے میں ان کی حدیث ابن عباس رضی اللہ عنہما سے مروی ہے کہ ضباعہ بنت زبیر نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں اور کہنے لگیں: میں حج کرنا چاہتی ہوں، کیا میں شرط لگاؤں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: “ہاں”۔ انہوں نے عرض کیا: “میں کیا کہوں؟” آپ صلی اللہ علیہ وسلم نے فرمایا: “تم کہو: میں حاضر ہوں! اے اللہ میں حاضر ہوں! جس جگہ تم محصور ہوئی وہاں سے احرام کھول دینا۔”(3) ابن مندہ کا قول ہے: یہ روایت عکرمہ سے مشہور ہے۔ اسے عبدالکریم نے روایت کیا ہے: مجھ سے ابن عباس رضی اللہ عنہما سے سننے والے نے روایت کیا، فرماتے ہیں: مجھ سے ضباعہ نے روایت کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے انہیں حکم دیا کہ اپنے احرام باندھنے میں شرط لگائیں، فرماتے ہیں: اسے عروہ نے سیدہ عائشہ رضی اللہ عنہا سے روایت کیا ہے اور زہری رحمہ اللہ نے اور ہشام نے ان سے روایت کیا ہے۔ پھر حجاج بن نصر کے طریق سے بحوالہ ہشام، انہوں نے ابو زبیر سے انہوں نے جابر سے حدیث بیان کی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے ضباعہ سے فرمایا: “حج کرو اور شرط لگاؤ۔” پھر موسیٰ بن خلف کے طریق سے بحوالہ قتادہ، انہوں نے اسحاق بن عبداللہ ہاشمی سے انہوں نے ام عطیہ سے، انہوں نے ان کی بہن ضباعہ سے روایت کیا ہے کہ انہوں نے نبی کریم صلی اللہ علیہ وسلم کو کندھے کا گوشت کھاتے دیکھا پھر نماز کے لیے اٹھے اور وضو نہیں فرمایا، فرماتے ہیں: اسے ہمام نے قتادہ سے بحوالہ اسحاق بن عبد اللہ، انہوں نے اپنی دادی ام حکیم سے، انہوں نے اپنی بہن ضباعہ سے روایت کیا ہے اور وہ موسیٰ بن خلف کی روایت سے زیادہ راجح ہے۔ ابو عمر کو موسیٰ بن خلف کی روایت سے دھوکا ہوا ہے۔ انہوں نے ضباعہ بنت حارث انصاریہ کا عنوان قائم کیا ہے، جو ام عطیہ کی بہن ہیں، اس بناء پر کہ ام عطیہ انصاریہ ہیں۔ ابن اثیر(4) رحمہ اللہ نے اشارہ کیا ہے کہ وہ وہم ہے۔","",{"fn":"(1) اسد الغابة (۷۰۶۸) الاستيعاب (۳۴۶۴) تجرید (۲۸۴/۲)\n(2) الطبقات الكبرى (۳۱/۸)\n(3) الاستيعاب (۱۸۷۴/۴)\n(4) اسد الغابة (۳۳۳/۵)"}],[11383,"§۱۱۴۲۱ ۔ ضباعہ بنت عامر\n(1) بن قرط بن سلمہ بن قیر بن کعب بن ربیعہ بن عامر بن صعصعہ، ابونعیم نے ان کا ذکر کیا ہے اور عبداللہ بن اصلح کے طریق سے بحوالہ کلبی نقل کیا ہے، مجھے عبدالرحمن عامری نے اپنی قوم کے شیوخ کے حوالے سے بتایا، وہ فرماتے ہیں: ہمارے پاس رسول اللہ صلی اللہ علیہ وسلم تشریف لائے اور ہم عکاظ بازار میں تھے، آپ صلی اللہ علیہ وسلم نے ہمیں اپنی مدد و حمایت کے لیے بلایا، ہم آپ صلی اللہ علیہ وسلم کی مدد کے لیے گئے، اتنے میں بیحجرہ بن فراس قشیری آیا، اس نے رسول اللہ صلی اللہ علیہ وسلم کی اونٹنی کو چھیڑا جس نے آپ صلی اللہ علیہ وسلم کو نیچے گرا دیا۔ ہمارے پاس ان دنوں ضباعہ بنت عامر بن قرط تھیں، یہ ان خواتین میں سے تھیں جو مکہ میں رسول اللہ صلی اللہ علیہ وسلم پر ایمان لائیں اور اپنے رشتہ داروں سے ملاقات کے لیے آئی تھیں، کہنے لگیں: اے آل عامر، مجھے عامر کا کیا فائدہ، تمہاری موجودگی میں نبی کریم صلی اللہ علیہ وسلم کے ساتھ یہ سلوک کیا جاتا ہے، اور اسے تم میں سے کوئی روکنے والا نہیں۔ اس کے تین چچا زاد بیحجرہ کی طرف بڑھے، ان میں سے ہر ایک نے ایک ایک آدمی کو پکڑا اور زمین پر دے مارا، پھر اس کے سینے پر بیٹھ کر ان کے چہروں پر طمانچے مارنے لگے، آپ صلی اللہ علیہ وسلم نے فرمایا: “اے اللہ! ان لوگوں کو برکت دے”۔ یہ لوگ اسلام لائے اور شہید ہوئے۔(2) یہ سند کے منقطع ہونے کے ساتھ ضعیف ہے۔ مجھے ضباعہ کا ذکر دوسری روایت میں ملا ہے۔ ہشام بن کلبی نے انساب میں ان کا ذکر کیا ہے۔ بحوالہ ان کے والد، انہوں نے ابو صالح سے، انہوں نے ابن عباس رضی اللہ عنہما سے روایت کیا ہے، فرماتے ہیں: ضباعہ قشیریہ حوزہ بن علی حنفی کی زوجہ تھیں، وہ وفات پا گیا تو اس کے مال کی وارث بن گئیں، ان کے چچا زاد اور عبداللہ بن جدعان نے انہیں نکاح کا پیغام دیا، ان کے والد نے مال کو پسند کیا اور ابن جدعان سے ان کا نکاح کر دیا، جب وہ ان کی طرف لے جائی جا رہی تھیں تو ان کا چچا زاد ان کے پیچھے گیا اور کہا: اے ضباعہ! سمندر جیسے مرد تمہیں زیادہ پسند ہیں یا وہ مرد جو دیواروں پر نیزہ مارتے ہیں؟ انہوں نے کہا: وہ مرد جو دیواروں پر نیزہ مارتے ہیں۔ وہ عبداللہ بن جدعان کے پاس آئیں اور ان کے پاس ٹھہریں، انہیں ہشام بن مغیرہ نے جو قریش کے آدمیوں میں سے تھے، پسند کیا اور ضباعہ سے کہا: کیا تم اپنے حسن و جمال کے ساتھ اس بوڑھے کمینے پر راضی ہو؟ اس سے طلاق مانگو میں تم سے شادی کروں گا۔ انہوں نے ابن جدعان سے طلاق مانگی، اس نے کہا: مجھے معلوم ہوا ہے کہ ہشام تم میں رغبت رکھتا ہے، میں تمہیں طلاق نہیں دوں گا یہاں تک کہ تم قسم کھاؤ اگر تم نے شادی کی تو سو(۱۰۰) سیاہ اونٹنیاں جن کی آنکھیں کالے ڈوروں والی ہوں اساف اور نائلہ کے درمیان ذبح کرو گی، اور تم سوت کا تنا جو مکہ کے دونوں کناروں کے درمیان پورا ہو جائے اور تم بیت اللہ کا طواف بے لباس ہو کر کرو۔ اس نے کہا: مجھے سوچنے کی مہلت دو۔ اس شخص نے انہیں چھوڑ دیا اور ان کے پاس ہشام آیا، اس نے اسے بتایا، اس نے کہا: سو اونٹنیوں تمہاری طرف سے ذبح کرنا تو میرے لیے اتنا ہی آسان ہے جتنا ایک اونٹ، اور رہا دھاگہ تو بنو مغیرہ کی عورتیں تمہارے لیے سوت کات دیں گی، اور رہا بیت اللہ کا طواف کرنا تو میں قریش سے کہوں گا، وہ تمہارے لیے بیت اللہ کو ایک گھڑی کے لیے خالی کر دیں، اس سے طلاق مانگو۔ انہوں نے طلاق مانگی تو اس نے طلاق دے دی۔ انہوں نے اس کے لیے قسم کھائی۔ ان سے ہشام نے نکاح کیا، جس سے سلمہ پیدا ہوئے، وہ بہترین مسلمان تھے۔ ہشام نے جو ان سے وعدہ کیا تھا پورا کیا۔ ابن عباس رضی اللہ عنہما فرماتے ہیں: مجھے مطلب بن ابو وداعہ سہمی نے بتایا: جو رسول اللہ صلی اللہ علیہ وسلم کی ولادت کے وقت کے تھے، جب قریش نے ضباعہ کے لیے بیت اللہ خالی کیا میں اور محمد باہر نکلے اس وقت ہم چھوٹے لڑکے تھے، ہمیں چھوٹا سمجھ کر کسی نے ہمیں منع نہیں کیا، ہم نے اسے دیکھا جب آئی، تو ایک ایک کر کے کپڑے اتارنے لگی، وہ کہہ رہی تھی: “آج کے دن بعض یا سارا ظاہر ہوا، جو ظاہر ہوا میں اسے حلال نہ کروں گی۔” اس نے اپنے کپڑے اتارے، پھر اپنے بال بکھیرے اور اپنے پیٹ اور پیٹھ کو ڈھانپ لیا یہاں تک کہ اس کی پازیبوں تک چلے گئے اور اس کے جسم سے کچھ ظاہر نہ تھا، وہ طواف کرنے لگی اور یہ شعر پڑھنے لگی۔ جب ہشام بن مغیرہ وفات پاگئے، تو اسلام لائیں اور ہجرت کی، نبی کریم صلی اللہ علیہ وسلم نے ان کے بیٹے سلمہ کی طرف نکاح کا پیغام بھیجا، انہوں نے کہا: یا رسول اللہ! اس میں کوئی رکاوٹ نہیں لیکن میں ان سے پوچھ لوں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: “ٹھیک ہے”۔ وہ ان کے پاس آئے، وہ کہنے لگیں: انا للہ! کیا رسول اللہ صلی اللہ علیہ وسلم کے بارے میں تم مجھ سے اجازت طلب کر رہے ہو؟ میں کوشش کرتی ہوں کہ آپ صلی اللہ علیہ وسلم کی ازواج میں میرا حشر ہو، ان کی طرف جاؤ اور ان سے کہو: اس سے پہلے کہ کوئی چیز ظاہر ہو، ہاں کہہ دو۔ سیدنا سلمہ رضی اللہ عنہ واپس لوٹے اور آپ صلی اللہ علیہ وسلم کو یہ بات بتائی، نبی کریم صلی اللہ علیہ وسلم خاموش ہو گئے، اور کچھ بھی نہ فرمایا، سیدنا سلمہ رضی اللہ عنہ کے سپرد یہ معاملہ کرنے کے بعد لوگوں نے آپ صلی اللہ علیہ وسلم سے یہ کہہ دیا تھا کہ ضباعہ پہلے جیسی نہیں رہیں، ان کے چہرے پر جھریاں بڑھ گئی ہیں، اور ان کے منہ سے دانت گر گئے ہیں۔ ابن سعد(3) رحمہ اللہ نے اس میں سے کچھ ان کے سوانح میں بحوالہ ہشام بن کلبی ذکر کیا ہے، ان سے اس سند سے مروی ہے: ضباعہ عرب کی عورتوں میں خوبصورت ترین تھیں، ڈیل ڈول والی تھیں، جب زمین پر بیٹھتی تو بہت سی جگہ لے لیتیں ان کے بالوں سے ان کا جسم ڈھانپا جاتا تھا۔","",{"fn":"(1) اسد الغابة (۷۰۶۹) الاستيعاب (۳۴۶۵) تجرید (۲۸۴/۲)\n(2) السيرة النبوية (۱۶۴/۱) الطبقات الكبرى (۱۰۹/۸، ۱۱۰)\n(3) الطبقات (۱۰۹/۸)"}],[11384,"§۱۱۴۲۲ ۔ ضباعہ بنت عمرو\n(1) بن محصن بن عمرو بن عتیک انصاریہ، بنو نجار سے ہیں، ابن سعد(2) نے بیعت کرنے والی خواتین میں ان کا ذکر کیا ہے، اور فرمایا: ان کی والدہ عمرہ بنت ہزال بن عمرو بن قمر بوس ہیں، ان کے شوہر کا نام عبید بن عمیر بن وہب ہے۔","",{"fn":"(1) تجرید (۲۸۴/۲)\n(2) الطبقات الكبرى (۳۳۱/۸)"}],[11385,"§۱۱۴۲۳ ۔ ضبیعہ بنت حدیم السہمیہ\nعبد اللہ بن حذافہ کی والدہ ہیں، صحیح کی روایت سے ان کے صحابیہ ہونے کا پتہ چلتا ہے۔ صحیح مسلم کی کتاب فضائل میں ہے کہ انہوں نے اپنے بیٹے سے اس پر نکیر کرتے ہوئے کہا، جب اس نے پوچھا: میرا باپ کون ہے؟ انہوں نے کہا: تمہارا باپ حذافہ ہے، اگر تیری ماں جاہلیت کے کسی کام سے آلودہ ہوئی ہے۔"],[11386,"§۱۱۴۲۴ ۔ ضمرہ زوج ابی قیس بن الأسلت\nطبری رحمہ اللہ نے ذکر کیا ہے کہ یہ آیت ان کے بارے میں اتری: “تمہارے باپوں نے جن عورتوں سے نکاح کیا تم ان سے نکاح نہ کرو۔”(1)","",{"fn":"(1) سورة النساء الآية (۲۲)"}],[11387,"§۱۱۴۲۵ ۔ الضیزنہ بنت ابی قیس\n(1) اسلام لائیں اور ہجرت کی، شفاء بنت عوف میں ان کا ذکر گزر چکا ہے۔","",{"fn":"(1) الاستيعاب (۳۴۶۶) تجرید (۲۸۴/۲)"}],[11388,"§۱۱۴۲۶ ۔ ضباعہ بنت الحارث\n(1) انصاریہ۔ ام عطیہ کی بہن ہیں۔ ابو عمر(2) نے ایک حدیث(3) میں ان کا ذکر کیا ہے، جو قسم اول میں ضباعہ بنت زبیر کے سوانح میں گزر چکی ہے۔","",{"fn":"(1) اسد الغابة (۷۰۶۷) الاستيعاب (۳۴۶۳) تجرید (۲۸۳/۲)\n(2) الاستيعاب (۱۸۷۴/۴)\n(3) مسند احمد (۴۱۹/۶) المعجم الكبير (۸۳۹/۲۴) مجمع الزوائد (۲۵۳/۱) جامع المسانيد والسنن (۵۹۳/۱۵)"}],[11389,"§۱۱۴۲۷ ۔ الضحاک بنت مسعود\n(1) خویصہ کی بہن ہیں، ابن مندہ نے ان کا ذکر کیا ہے، وہ وہم ہے۔ ابونعیم نے ان کا تعاقب کیا ہے کہ وہ ام ضحاک ہیں، صحیح بیان کنیتوں میں آئے گا۔","",{"fn":"(1) اسد الغابة (۷۰۷۰) تجرید (۲۸۴/۲)"}],[11390,"§۱۱۴۲۸ ۔ الطاہرہ بنت خویلد\nسیدہ خدیجہ رضی اللہ عنہا جو نبی کریم صلی اللہ علیہ وسلم کی زوجہ ہیں، ان کی بہن ہیں، زبیر بن بکار نے ان کا ذکر کیا ہے۔"],[11391,"§۱۱۴۲۹ ۔ طریہ\nسیدنا حسان بن ثابت رضی اللہ عنہ(1) کی مولاۃ ہیں، حرف سین مہملہ میں سیدہ سیرین رضی اللہ عنہا کے سوانح میں ان کا ذکر گزر چکا ہے۔","",{"fn":"(1) اسد الغابة (۷۰۷۱) تجرید (۲۸۴/۲)"}],[11392,"§۱۱۴۳۰ ۔ طعیمہ\n(1) ان کا ذکر ہے، جبکہ حدیث مذکور نہیں، ابن مندہ نے اسی طرح ذکر کیا ہے۔","",{"fn":"(1) اسد الغابة (۷۰۷۲) تجرید (۲۸۴/۲)"}],[11393,"§۱۱۴۳۱ ۔ طیبہ\nابو موسیٰ اشعری کی والدہ ہیں، حرف ظاء معجمہ میں ان کا ذکر ہے۔"],[11394,"§۱۱۴۳۲ ۔ طیبہ بنت النعمان\nحرف ظاء معجمہ میں ان کا ذکر آئے گا۔"],[11395,"§۱۱۴۳۳ ۔ طلیحہ بنت عبد اللہ\n(1) ابوعمر(2) نے بحوالہ لیث، انہوں نے زہری رحمہ اللہ سے نقل کیا ہے کہ وہ رشید ثقفی کے نکاح میں تھیں، انہوں نے طلاق دے دی، تو انہوں نے اپنی عدت میں نکاح کر لیا۔ میں کہتا ہوں: انہوں نے نبوت کا زمانہ پایا۔","",{"fn":"(1) اسد الغابة (۷۰۷۴) الاستيعاب (۳۴۶۷) تجرید (۲۸۴/۲)\n(2) الاستيعاب (۱۸۷۵/۴)"}],[11396,"§۱۱۴۳۴ ۔ طفیہ\n(1) بنت وہب، ابو موسیٰ اشعری کی والدہ ہیں، طبرانی نے ان کا ذکر کیا ہے۔ فرماتے ہیں: اسلام لائیں اور مدینہ میں وفات پائی۔ مستغفری نے بحوالہ ابن قتیبہ ذکر کیا ہے کہ انہوں نے فرمایا، اسلام لائیں اور ہجرت کی۔ ثم ہشام بن کلبی(2) اور ابو احمد عسکری نے ذکر کیا ہے کہ وہ ظبیہ ہیں جیسا کہ آگے آ رہا ہے۔","",{"fn":"(1) اسد الغابة (۷۰۷۳) تجرید (۲۸۴/۲)\n(2) المعارف (۲۶۶)"}],[11397,"§۱۱۴۳۵ ۔ طعیمہ بنت جر\nتجرید کے استدراک میں ان کا تذکرہ ہے، طعیمہ بنت جریج کے سوانح میں ان کا تذکرہ ہے۔ ان کے آباء واجداد میں سے کسی کا نام رہ گیا ہے۔"],[11398,"§۱۱۴۳۶ ۔ ظبیہ بنت البراء بن معرور\n(1) ابو قتادہ انصاری کی زوجہ ہیں۔ مصعب بن ثابت بن عبد اللہ بن ابو قتادہ نے بحوالہ ان کے دادا، انہوں نے ابو قتادہ سے ان کی حدیث روایت کی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے ظبیہ بنت براء بن معرور جو ابو قتادہ کی زوجہ ہیں، فرمایا: “تم پر نماز جمعہ اور جہاد فرض نہیں۔” انہوں نے عرض کیا: “یا رسول اللہ! مجھے تسبیح جہاد سکھا دیجئے۔” آپ صلی اللہ علیہ وسلم نے فرمایا: “کہو! اللہ پاک ہے، اس کے سوا کوئی معبود نہیں اور اللہ سب سے بڑا ہے، اللہ کے لیے ہی تمام تعریف ہے۔”","",{"fn":"(1) اسد الغابة (۷۰۷۵) الاستيعاب (۳۴۶۸) تجرید (۲۸۵/۲)"}],[11399,"§۱۱۴۳۷ ۔ ظبیہ بنت النعمان\nبن ثابت بن ابو الح، ان کی پھوپھی جمیلہ بنت ثابت کے سوانح میں ان کا ذکر گزر چکا ہے۔"],[11400,"§۱۱۴۳۸ ۔ ظبیہ بنت وہب\n(1) بنو عتک سے ہیں، اسلام لائیں، مدینہ میں وفات پائی، یہ ہشام بن کلبی کا قول ہے، ابو احمد عسکری فرماتے ہیں: ام ابو موسیٰ اشعری ہیں۔ واقدی رحمہ اللہ نے اسی پر یقین کیا ہے۔","",{"fn":"(1) اسد الغابة (۷۰۷۶) تجرید (۲۸۵/۲)"}],[11401,"§۱۱۴۳۹ ۔ ظمیاء بنت اشرس تمیمیہ\nبنو ہذلہ بن عوف بن سعد بن زید مناة بن تمیم سے ہیں، صحابیہ ہیں، ایک طویل حدیث میں ان کا ذکر ہے، فاکہی نے کتاب مکہ میں اسے نقل کیا ہے، فرماتے ہیں: محمد بن اسماعیل بن ابو رزین نے مجھ سے بیان کیا، وہ فرماتے ہیں: ہم سے حجاج بن محمد نے بحوالہ حفص بن عبدالرحمن اموی بیان کیا، فرماتے ہیں: وہ کہتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم جب مدینہ تشریف لائے تو لوگ اسلام لے آئے، اور آپ کے پاس اپنے چشموں اور گھروں سے آنے لگے، بنو سعد بن زید مناة بن تمیم نے بنو ہذلہ بن عوف سے ایک عورت جسے ظمیاء بنت اشرس کہا جاتا تھا، کو اس پانی کے چشمے پر روانہ کیا، جو گھروں میں تھا، جس کا جاہلیت میں قبیلہ عبد القیس نے دعوی کر رکھا تھا کہ یہ ہمارا ہے، جس کی وجہ سے ان کے درمیان جنگ ہوئی، عبدالقیس نے بنو حارث میں سے کسی شخص کو سفیر بنا کر بھیجا، جو چل کر مقامِ جرف کے پانی پر اترا، اس نے پانی پر ایک عورت دیکھی جو اسے عبور کر چکی تھی وہ بنو سعد کی ایلچی تھی، اس عبدری نے اس سے سوال کیا: اس کا کہاں کا ارادہ ہے؟ وہ کہنے لگی: میں اس نبی کے پاس جانے کا ارادہ رکھتی ہوں جو یثرب میں فروکش ہوا ہے، لیکن میں بچھڑ گئی ہوں، وہ شخص اس سے شرمانے لگا۔ اس نے کہا: ہمارے پاس زائد اونٹ ہے، انہوں نے اسے سوار کرالیا اور اس سے آنے کا سبب نہیں پوچھا، یہاں تک کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آگئے، وہ عورت آگے بڑھی اور بولی: یا رسول اللہ! بنو ہذلہ بن عوف نے مجھے آپ کی طرف بھیجا ہے۔ پھر حارث بن حسان کے عورت کے ساتھ قصے کی طرح ذکر کیا، کہنے لگی: اگر عبدالقیس کا ان گھروں پر قبضہ ہو گیا تو قبیلہ مضر ہلاک ہو جائے گا۔ عبدری نے کہا: اللہ کی پناہ کہ میں عاد کے ایلچی کی طرح ہوں، پھر اس کا طویل قصہ ذکر کیا۔"],[11402,"§۱۱۴۴۰ ۔ عاتکہ بنت ابی ازیہر\nبن انیس بن حمق بن مالک دوسری، ان کے والد بدر میں حالت کفر میں قتل ہوئے۔ ان سے پھر ابوسفیان بن حرب نے نکاح کیا وہ ان کے بیٹے محمد اور عبہ کی والدہ ہیں۔"],[11403,"§۱۱۴۴۱ ۔ عاتکہ بنت اسید\n(1) بن ابو عیص بن امیہ امویہ، عتاب بن اسید امیر مکہ کی بہن ہیں۔ ابن سعد(2) رحمہ اللہ کا قول ہے: فتح کے دن اسلام لائیں، ابوعمر(3) فرماتے ہیں: انہیں شرف صحابیت حاصل ہے، مجھے معلوم نہیں کہ ان سے کوئی روایت مروی ہو، زبیر بن بکار نے کتاب المنسب میں محمد بن سلام سے ذکر کیا ہے، فرماتے ہیں: سیدنا عمر بن خطاب رضی اللہ عنہ نے سیدہ شفاء بنت عبداللہ عدویہ کی طرف پیغام بھیجا کہ میرے پاس آؤ فرماتی ہیں: میں گئی، میں نے دیکھا، عاتکہ بنت اُسید بن ابوالعیص ان کے دروازے پر کھڑی ہیں، ہم دونوں اندر گئیں، انہوں نے ہم سے تھوڑی دیر بات کی، اتنے میں ایک چادر منگوائی اور انہیں عطاء کی، پھر دوسری چادر منگوائی اور مجھے عطا کی، فرماتی ہیں، میں نے کہا: اے عمر! میں اس سے پہلے اسلام لائی اور میں آپ کی چچا زاد ہوں، مجھے آپ نے بلوایا ہے اور یہ از خود آئیں سیدنا عمر فرمانے لگے: میں نے یہ چادر تمہارے لیے ہی رکھی تھی لیکن جب تم دونوں اکٹھی ہو گئیں تو مجھے یاد آیا کہ ان کی رسول اللہ صلی اللہ علیہ وسلم سے تم سے زیادہ رشتہ داری ہے۔","",{"fn":"(1) اسد الغابة (۷۰۷۷) الاستيعاب (۳۴۶۹) تجرید (۲۸۵/۲)\n(2) السيرة النبوية (۴۳/۳)\n(3) السيرة النبوية (۴۳/۳)"}],[11404,"§۱۱۴۴۲ ۔ عاتکہ بنت خالد الخزاعیہ\nام معبد ہیں، اور اپنی کنیت سے مشہور ہیں، کنیتوں میں ان کا ذکر آئے گا۔"],[11405,"§۱۱۴۴۳ ۔ عاتکہ بنت زید\n(1) بن کعمرو بن نفیل عدویہ، سعید بن زید کی بہن ہیں جو عشرہ مبشرہ میں سے ہیں۔ ان کے والد کے سوانح میں ان کا نسب گزر چکا ہے، ان کی والدہ ام کریز بنت عبداللہ بن عمار بن مالک حضرمیہ ہیں۔ ابونعیم نے حدیث عائشہ سے نقل کیا ہے کہ سیدہ عاتکہ عبداللہ بن ابوبکر صدیق رضی اللہ عنہ کی زوجہ تھیں۔ ابو عمر(2) کا قول ہے: مہاجرات میں سے ہیں۔ ان سے عبداللہ بن ابوبکر صدیق رضی اللہ عنہ نے نکاح کیا، وہ بہت حسین و جمیل تھیں، ان پر اُس کے حسن کا جادو چل گیا، جس نے انہیں جہادی مہموں میں شرکت سے غافل کر دیا۔ صورت حال دیکھ کر ان کے والد نے انہیں طلاق دینے کا حکم دیا، جس کے متعلق وہ یہ اشعار کہتے ہیں: “لوگ کہتے ہیں اسے طلاق دے دو اور اس کی جگہ خیمہ لگا کر مقیم ہو جاؤ، نفس کو سوتے شخص کے خوابوں کی تمنا دکھاؤ، ان گھر والوں کو جنہیں میں نے اپنی کثرت کے باوجود جمع کیا، انہیں جدا کرنا، بڑے کاموں میں سے ایک ہے۔” پھر ان کے والد نے اصرار کیا، تو انہوں نے طلاق دے دی، لیکن وہ دل سے نہ دی، ایک دن ان کے والد نے انہیں یہ اشعار پڑھتے سنا: “مجھے نہیں لگتا کہ مجھ جیسے شخص نے اس جیسی عورت کو طلاق دی ہو اور نہ میں نے یہ دیکھا ہے کہ کوئی عورت اس جیسی ہوا سے بغیر جرم کے طلاق مل گئی ہو”۔ تو ان کے والد کا دل نرم پڑ گیا، انہیں اجازت دے دی تو ان سے رجوع کر لیا۔ بعد میں طائف کے محاصرہ کے دوران انہیں تیر لگا جس میں زخمی ہوئے اور مدینہ میں آکے فوت ہو گئے۔ تو عاتکہ نے ان اشعار میں ان کا مرثیہ کہا: “میں نے قسم کھائی ہے کہ میری آنکھ ہمیشہ تیرے لیے غمگین رہے گی اور میرا جسم ہمیشہ غبار آلود رہے گا۔” ایک قول ہے کہ پھر ان سے زید بن خطاب نے نکاح کیا، وہ یمامہ میں شہید ہوئے، اس کے بعد سیدنا عمر رضی اللہ عنہ نے ان سے نکاح کیا، پھر ان کا سیدنا علی رضی اللہ عنہ کے ساتھ یہ قصہ پیش آیا کہ آپ نے انہیں ان کا یہ قول یاد دلایا: “میں نے قسم کھائی ہے کہ میری آنکھ ہمیشہ غمگین رہے گی۔” پھر سیدنا عمر رضی اللہ عنہ بھی شہید ہوئے، انہوں نے مشہور اشعار سے ان کا مرثیہ کہا۔ ابن سعد(3) رحمہ اللہ نے حسن سند سے یحیی بن عبدالرحمن بن حاطب نقل کیا ہے، سیدہ عاتکہ رضی اللہ عنہا سیدنا عبداللہ بن ابوبکر سے محبت کرتی تھیں۔ انہوں نے اپنے مال میں سے ایک حصہ ان کے لیے مقرر کیا کہ وہ ان کے بعد نکاح نہ کریں، وہ وفات پاگئے تو سیدنا عمر رضی اللہ عنہ نے سیدہ عاتکہ رضی اللہ عنہا کی طرف پیغام بھیجا کہ جو اللہ نے تمہارے لیے حلال کیا ہے تو نے حرام کر رکھا ہے، ان کے گھر والوں کو وہ مال واپس دے دو جو تم نے ان سے لیا ہے۔ انہوں نے ایسا ہی کیا۔ تو سیدنا عمر رضی اللہ عنہ نے انہیں نکاح کا پیغام بھیجا، اور ان سے نکاح کر لیا۔ بعض کا قول ہے: سیدنا علی رضی اللہ عنہ نے انہیں نکاح کا پیغام دیا تھا، انہوں نے کہا: میں نہیں چاہتی کہ آپ قتل ہوں، بعض نے کہا: سیدنا عبداللہ بن زبیر نے سیدنا زبیر سے انہیں ملنے والی میراث پر اسی(۸۰) ہزار دراہم پر صلح کرنی تھی۔ ابوعمر(4) نے تمہید میں ذکر کیا ہے، جب سیدنا عمر رضی اللہ عنہ نے انہیں نکاح کا پیغام دیا تو انہوں نے شرط لگائی کہ انہیں نہ ماریں گے، نہ حق بات سے اور مسجد نبوی میں نماز پڑھنے سے روکیں گے، پھر سیدنا زبیر رضی اللہ عنہ کے سامنے بھی یہی شرط رکھی، انہوں نے یہ حیلہ کیا، جب وہ عشاء کی نماز کے لیے نکلیں تو وہ چھپ گئے۔ جب وہ ان کے پاس سے گزریں، تو انہوں نے چھیڑا۔ جب واپس لوٹیں تو کہنے لگیں: إِنَّا لِلّٰہ! لوگوں میں فساد آ گیا ہے! اس کے بعد کبھی باہر نہ نکلیں۔ میں کہتا ہوں: ابن مندہ نے ابن ابو زناد کے طریق سے، موسیٰ بن عقبہ سے انہوں نے سالم سے نقل کیا ہے کہ عاتکہ بنت زید سیدنا عمر رضی اللہ عنہ کی زوجہ تھیں، اور مسجد نبوی میں بہت آنا جانا تھا۔ سیدنا عمر رضی اللہ عنہ یہ ناپسند کرتے تھے۔ انہیں کہا گیا تو فرمایا: میں اسے ترک نہیں کروں گی جب تک مجھے منع نہ کیا جائے۔ سیدنا عمر رضی اللہ عنہ نے انہیں منع کرنا پسند نہ کیا۔ سیدنا عمر رضی اللہ عنہ کے بعد ان سے ایک اور شخص نے نکاح کیا، اس نے انہیں منع کیا، میں نے سالم سے پوچھا: وہ کون ہے؟ انہوں نے فرمایا: زبیر بن عوام۔","",{"fn":"(1) اسد الغابة (۷۰۷۹) تجرید (۲۸۵/۲)\n(2) الاستيعاب (۱۸۷۷/۴)\n(3) الطبقات الكبرى (۱۹۴/۸)\n(4) الاستيعاب (۱۸۷۷/۴)"}],[11406,"§۱۱۴۴۴ ۔ عاتکہ بنت ابوسفیان\nبن حارث بن عبدالمطلب ہاشمیہ، معتب بن ابولہب کی زوجہ ہیں، ان سے خالدہ پیدا ہوئیں ان سے عبداللہ بن حارث بن نوفل بن حارث بن عبدالمطلب نے جو ببہ کے لقب سے مشہور تھے، نکاح کیا۔ زبیر بن بکار نے ان کا ذکر کیا ہے۔ اور ابن سعد(1) نے ام عمرو بنت مقوم بن عبدالمطلب کے سوانح میں ان کا ذکر کیا ہے کہ ابوسفیان بن حارث نے ان سے نکاح کیا، جس سے عاتکہ پیدا ہوئیں۔","",{"fn":"(1) الطبقات الكبرى (۱۹۳/۸)"}],[11407,"§۱۱۴۴۵ ۔ عاتکہ بنت ابی الصلت الثقفیہ\nامیہ کی بہن ہیں، سہیلی نے مبہمات القرآن میں سورۃ اعراف کی تفسیر کے آخر میں ان کا ذکر کیا ہے۔"],[11408,"§۱۱۴۴۶ ۔ عاتکہ بنت عبدالمطلب\n(1) بن ہاشم، نبی کریم صلی اللہ علیہ وسلم کی پھوپھی ہیں۔ ابوامیہ بن مغیرہ کی زوجہ ہیں، جو ام سلمہ رضی اللہ عنہا کے والد ہیں، وہ رسول اللہ صلی اللہ علیہ وسلم کی زوجہ ہیں، ان سے عبداللہ اور قریبہ وغیرہ پیدا ہوئے۔ ابوعمر(2) کا قول ہے: ان کے اسلام لانے میں اختلاف ہے۔ اکثر نے اس کا انکار کیا ہے۔ اروی کے سوانح میں ہے: عقیلی نے صحابہ میں ان کا اور عاتکہ کا ذکر کیا ہے۔ رہے ابن اسحاق تو وہ فرماتے ہیں: نبی کریم صلی اللہ علیہ وسلم کی پھوپھیوں میں سے صرف سیدہ صفیہ رضی اللہ عنہا ہی ایمان لائی تھیں۔ ابن فتحون نے استیعاب کے حاشیہ میں ان کا ذکر کیا ہے، اور ان کے اسلام لانے پر ان کا وہ شعر دلالت کرتا ہے، جس میں انہوں نے نبی کریم صلی اللہ علیہ وسلم کی مدح اور نبوت کی تعریف بیان کی ہے۔ دار قطنی نے کتاب الاخوۃ میں فرمایا: ان کے ایک شعر میں ان کی تصدیق کا ذکر ہے، اور ان سے روایت نہیں، ابن مندہ نے صحابہ میں ان کا ذکر کرنے کے بعد فرمایا: ان سے ام کلثوم بنت عقبہ(3) نے روایت کی۔ پھر محمد بن عبدالعزیز بن عمر بن عبدالرحمن بن عوف کے طریق سے بحوالہ زہری انہوں نے حمید بن عبد الرحمن بن عوف سے، انہوں نے ام کلثوم بنت عقبہ سے انہوں نے عاتکہ بنت عبدالمطلب سے حدیث بیان کی، انہوں نے واقعہ بدر کے بارے میں مختصر خواب بیان کیا ہے، ابن اسحاق نے سیرۃ نبویہ میں اسے یونس بن بکیر کی ان سے روایت میں مختصر ذکر کیا ہے۔ فرماتے ہیں: مجھ سے حسین بن عبد اللہ بن عبید اللہ بن عباس نے بحوالہ عکرمہ انہوں نے ابن عباس اور یزید بن رومان بن عروہ سے روایت کی، دونوں فرماتے ہیں: عاتکہ بنت عبدالمطلب نے ابوسفیان کے بارے میں ضمضم بن عمرو کے اطلاع لانے سے تین رات پہلے خواب دیکھا، فرماتی ہیں: میں نے ایک شخص کو اپنے اونٹ پر آتے دیکھا، وہ انبح مقام پر ٹھہر گیا، اور کہا: اے آل بدر، تین دن کے اندر اپنی قتل گاہوں پر پہنچو، پھر انہوں نے خواب بیان پر کیا۔ اس میں ہے: پھر اس نے ایک چٹان لی، اور اسے پہاڑ کی چوٹی سے گرا دیا، وہ نیچے آیا، اور ریزہ ریزہ ہو گیا۔ کوئی گھر یا عمارت ایسی نہ بچی جس میں اس کا کوئی ریزہ نہ گیا ہو۔ اس قصے میں ابو جہل کی سیدنا عباس رضی اللہ عنہ پر تنکیر ہے، اس نے کہا: تم میں یہ عورت نبی کب سے بن گئی اور سیدنا عباس رضی اللہ عنہ نے ارادہ کیا کہ انہیں کھری کھری سنائیں۔ ابو جہل ضمضم بن عمرو کے آنے کی وجہ سے غافل ہو گیا، وہ قریش کو جنگ کے لیے آمادہ کرنے لگا، تاکہ مسلمانوں کو اس قافلے پر حملہ کرنے سے روکے جو ابوسفیان کی معیت میں تھا، انہوں نے تیاری کی اور بدر کی طرف نکلے، اللہ تعالیٰ نے سیدہ عاتکہ رضی اللہ عنہا کے خواب کو سچا کر دکھایا۔(4) زبیر بن بکار نے ذکر کیا ہے کہ وہ ابوطالب اور عبد اللہ کی سگی بہن ہیں۔ ابن سعد(5) رحمہ اللہ کا قول ہے: عاتکہ مکہ میں اسلام لائیں اور مدینہ کی طرف ہجرت کی، وہ قصہ بدر کے بارے میں مشہور خواب دیکھنے والی ہیں۔","",{"fn":"(1) اسد الغابة (۷۰۸۰) تجرید (۲۸۵/۲)\n(2) الاستيعاب (۱۸۷۶/۴، ۱۸۸۰)\n(3) نسب قريش (۱۸)\n(4) المعجم الكبير (۸۵۹/۲۴) مجمع الزوائد (۷۱/۶) السيرة النبوية (۱۸۸/۲، ۱۸۹)\n(5) الطبقات الكبرى (۳۰، ۲۹/۸)"}],[11409,"§۱۱۴۴۷ ۔ عاتکہ بنت عوف\n(1) عبدالرحمن کی بہن ہیں جو عشرہ مبشرہ میں سے ایک ہیں، ان کے بھائی کے سوانح میں ان کا نسب گزر چکا ہے۔ ابن سعد(2) کا قول ہے: شفاء بنت عوف بن عبد الحارث بن زہرہ ان کی بہن ہیں۔ ان سے مخرمہ بن نوفل نے نکاح کیا، جس سے مسور صفوان اکبر اور صلت اکبر اور ام صفوان پیدا ہوئے۔ عاتکہ بنت عوف اور ان کی بہن شفاء بنت عوف دونوں اسلام لائیں اور رسول اللہ صلی اللہ علیہ وسلم سے بیعت کی۔ ابوعمر(3) فرماتے ہیں: انہوں نے اور ان کی بہن شفا نے ہجرت کی، حرف شین معجمہ میں ان کا ذکر گزر چکا ہے۔","",{"fn":"(1) اسد الغابة (۷۰۸۱) الاستيعاب (۳۴۷۳) تجرید (۲۸۵/۲)\n(2) الطبقات (۱۸۰/۸)\n(3) الاستيعاب (۱۸۸۰/۴)"}],[11410,"§۱۱۴۴۸ ۔ عاتکہ بنت نعیم الانصاریہ\n(1) ابوعمر(2) کا قول ہے: حمید بن نافع کے پاس ان کی حدیث ابن لہیعہ سے بحوالہ ابوالاسود مروی ہے، انہوں نے زینب بنت ابو سلمہ سے انہوں نے عاتکہ بنت نعیم سے جو عبداللہ بن نعیم کی بہن ہیں روایت کیا ہے کہ وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئیں اور کہنے لگیں: ان کی بیٹی کا شوہر وفات پا گیا ہے، اس نے نوحہ کیا ہے، یہاں تک کہ اس کی آنکھیں خراب ہوگئی ہیں، مجھے اس کی بینائی جانے کا خوف ہے۔ کیا وہ سرمہ لگا سکتی ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: “نہیں یہ (عدت) چار مہینے اور دس دن ہے۔ تم میں سے عورت ایک سال تک نوحہ کرتی تھی پھر باہر آتی اور ایک مینگنی پھینکتی کہ ایک سال گزر گیا ہے”۔(3) میں کہتا ہوں: ابن مندہ نے عثمان بن صالح سے بحوالہ ابن لہیعہ یہی حدیث روایت کی ہے لیکن زینب بنت ابوسلمہ اور عاتکہ کے درمیان ام سلمہ کا ذکر کیا، اور عاتکہ انصاریہ کا نسب بیان کیا۔ ابونعیم عدویہ نے ان کا نسب بیان کیا ہے اور یہی صحیح ہے۔ طبرانی رحمہ اللہ نے اسے دوسرے طریق سے بحوالہ ابن لہیعہ ذکر کیا ہے۔ انہوں نے حمید بن نافع کے بدلے قاسم بن محمد کا ذکر کیا ہے۔ ابونعیم نے ان کے درست ہونے کی طرف اشارہ کیا ہے، اس کے سیاق میں ہے: بحوالہ ام سلمہ، بنت نعیم بن عبد اللہ عدوی نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں ... پھر حدیث ذکر کی۔","",{"fn":"(1) اسد الغابة (۷۰۸۲) الاستيعاب (۳۴۷۴) تجرید (۲۸۵/۲)\n(2) الاستيعاب (۱۸۸۰/۴)\n(3) بخاری (۱۲۸۰) مسلم (۳۷۰۹) ابوداؤد (۲۲۹۹) ترمذی (۱۱۹۵) نسائی (۳۵۰۰)"}],[11411,"§۱۱۴۴۹ ۔ عاتکہ بنت الولید\n(1) بن مغیرہ مخزومیہ، خالد بن ولید کی بہن ہیں، جو صفوان بن امیہ کی زوجہ ہیں، مستغفری نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ محمد بن ثور سے بحوالہ ابن جریج مسند ذکر کیا ہے۔ اسلام آیا اور ابوسفیان بن حرب کے پاس چھ بیویاں تھیں اور صفوان بن امیہ کے پاس بھی چھ بیویاں تھیں۔ ام وہب بنت ابو امیہ بن قیس، جو خوبصورت دراز قد خواتین میں سے تھیں فاختہ بنت اسود بن مطلب، امیمہ بنت ابوسفیان بن حرب، عاتکہ بنت مغیرہ، برزہ بنت مسعود بن عمرو بنت ملاعب الاسنہ عامر بن مالک۔ انہوں نے ام وہب کو طلاق دے دی، وہ اسلام لا چکی تھیں۔ اسلام نے ان کے اور فاختہ بنت اسود کے درمیان تفریق کرا دی۔ ابوسفیان کے والد نے ان سے نکاح کیا تھا، بعد میں انہوں نے ان سے نکاح کیا۔ پھر سیدنا عمر بن خطاب رضی اللہ عنہ کی خلافت میں عاتکہ کو طلاق دے دی۔","",{"fn":"(1) اسد الغابة (۷۰۸۳) تجرید (۲۸۶/۲)"}],[11412,"§۱۱۴۵۰ ۔ عاصیہ\nحرف جیم میں جمیلہ کے سوانح میں ان کا ذکر گزر چکا ہے۔"],[11413,"§۱۱۴۵۱ ۔ العاليہ بنت ظبیان\n(1) بن عمرو بن عوف بن عبد اللہ بن ابوبکر بن کلاب کلابیہ۔ ان سے رسول اللہ صلی اللہ علیہ وسلم نے نکاح کیا، وہ آپ صلی اللہ علیہ وسلم کے پاس کچھ عرصہ رہیں پھر آپ نے انہیں طلاق دے دی۔ ابوعمر(2) کا یہی قول ہے، ابن مندہ نے جب ازواج مطہرات میں ان کا ذکر کیا تو فرمایا: آپ صلی اللہ علیہ وسلم نے عالیہ بنت ظبیان کو طلاق دے دی، ہمیں یہ بات پہنچی ہے کہ ازواج مطہرات نبی کریم صلی اللہ علیہ وسلم کے لیے دوسرے نکاح کی حرمت سے پہلے انہوں نے اپنے چچازاد سے نکاح کر لیا، اور اولاد ہوئی۔ میں کہتا ہوں: اسے عبدالرزاق نے اپنی تفسیر میں معمر سے بحوالہ زہری رحمہ اللہ نقل کیا ہے کہ عالیہ بنت ظبیان وہ خاتون ہیں جنہیں آپ صلی اللہ علیہ وسلم نے طلاق دی، انہوں نے نکاح کیا، انہیں ام المساکین کہا جاتا تھا، انہوں نے نبی کریم صلی اللہ علیہ وسلم کی ازواج پر دوسرے نکاح کی حرمت سے پہلے نکاح کیا۔ ابو نعیم نے اسے لیث کے طریق سے، عقیل سے بحوالہ زہری اسی طرح نقل کیا ہے، جس میں یہ قول نہیں: انہیں ام المساکین کہا جاتا تھا۔ معمر کے طریق سے بحوالہ یحیی بن ابو کثیر مروی ہے، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے بنو ربیعہ کی ایک خاتون جنہیں عالیہ بنت ظبیان کہا جاتا تھا، ان سے نکاح کیا، جب وہ آپ صلی اللہ علیہ وسلم کے پاس بھیجی گئیں تو آپ صلی اللہ علیہ وسلم نے انہیں طلاق دے دی۔","",{"fn":"(1) اسد الغابة (۷۰۸۴) الاستيعاب (۳۴۷۵) تجرید (۲۸۶/۲)\n(2) الاستيعاب (۱۸۸۱/۴)"}],[11414,"§۱۱۴۵۲ ۔ عائشہ بنت ابی بکر الصدیق\n(1) ان کے والد عبد اللہ بن عثمان رضی اللہ عنہ کے سوانح میں ان کا نسب گزر چکا ہے۔ ان کی والدہ رومان بنت عامر بن عویمر ہیں۔(2) بعثت کے چار یا پانچ برس قبل پیدا ہوئیں، صحیح میں ہے کہ نبی کریم صلی اللہ علیہ وسلم نے ان سے نکاح کیا وہ چھ برس کی تھیں، ایک قول ہے، سات برس کی تھیں، ان دونوں کو اس طرح جمع کیا جائے گا کہ انہوں نے چھٹا سال مکمل کر لیا تھا اور ساتویں برس میں تھیں، جب ان کی رخصتی ہوئی تو نو برس کی تھیں، ہجرت کا پہلا برس اور شوال کا مہینہ تھا، جیسا کہ ابن سعد نے واقدی رحمہ اللہ سے بحوالہ ابور جال، انہوں نے اپنے والد سے، انہوں نے اپنی والدہ سے انہوں نے ان سے روایت کیا ہے، فرماتی ہیں: آٹھواں ماہ شروع تھا، اس وقت آپ صلی اللہ علیہ وسلم نے مجھے دلہن بنایا۔ بعض کا قول ہے: ہجرت کے دوسرے برس، زبیر بن بکار فرماتے ہیں: ان سے سیدہ خدیجہ رضی اللہ عنہا کی وفات کے بعد ان سے نکاح کیا، بعض نے کہا: تین برس بعد، ابوعمر(3) فرماتے ہیں: جبیر بن مطعم کی طرف منسوب تھیں۔ میں کہتا ہوں: ابن سعد نے اسے ابن عباس رضی اللہ عنہما کی حدیث سے نقل کیا ہے، جس میں کلبی بھی ہیں، اسی طرح ابن نمیر سے بحوالہ اصلح، انہوں نے ابن ابو ملیکہ سے نقل کیا ہے، فرماتے ہیں: سیدنا ابو بکر رضی اللہ عنہ فرماتے ہیں، میں مطعم سے اس کے بیٹے جبیر کے لیے اس کی زبان کر چکا ہوں، مجھے اس بارے میں ان سے پوچھ لینے دیں، پھر ان سے کہا: کچھ عرصہ ٹھہری رہیں۔ صحیح میں ابو معاویہ کی روایت سے بحوالہ اعمش، انہوں نے ابراہیم سے، انہوں نے اسود سے، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کیا ہے، فرماتی ہیں: رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے نکاح کیا اور میں چھ برس کی تھی جب میری رخصتی ہوئی تو میں نو برس کی تھی، جب آپ صلی اللہ علیہ وسلم نے وفات پائی تو میں اٹھارہ برس کی تھی۔ ابن ابو عاصم(4) نے یحیی قطان کے طریق سے محمد بن عمرو سے انہوں نے یحیی بن عبد الرحمن بن حاطب سے، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کیا ہے، فرماتی ہیں: جب سیدہ خدیجہ رضی اللہ عنہا وفات پا گئیں تو خولہ بنت حکیم بن اوقص جو عثمان بن مطعون کی زوجہ تھیں، کہنے لگیں: آپ صلی اللہ علیہ وسلم اس وقت مکہ میں تھے، کیا آپ شادی نہیں کرنا چاہتے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: “کس سے؟” کہنے لگیں: اگر آپ چاہیں تو کنواری اور اگر چاہیں تو شادی شدہ، آپ صلی اللہ علیہ وسلم نے پوچھا: “کنواری کون ہے؟” انہوں نے کہا: اللہ کی مخلوق میں سے آپ کے محبوب ترین شخص کی بیٹی عائشہ بنت ابو بکر۔ آپ صلی اللہ علیہ وسلم نے فرمایا: “اور بیوہ کون؟” انہوں نے کہا: سودہ بنت زمعہ، جو آپ صلی اللہ علیہ وسلم پر ایمان لائیں اور آپ کی پیروی کی۔ آپ صلی اللہ علیہ وسلم نے فرمایا: “جاؤ، اور ان دونوں کے لیے نکاح کا پیغام دو۔” وہ سیدنا ابو بکر رضی اللہ عنہ کے گھر آئیں، وہاں ام رومان تھیں، انہوں نے کہا: اللہ تعالیٰ نے تمہیں خیر اور برکت عطا فرمائی۔ انہوں نے پوچھا: وہ کیا؟ کہنے لگیں: رسول اللہ صلی اللہ علیہ وسلم نے مجھے آپ کے پاس عائشہ رضی اللہ عنہا کے نکاح کا پیغام دے کر بھیجا ہے۔ انہوں نے کہا: میں یہی چاہتی ہوں، ابو بکر کو آنے دو۔ سیدنا ابو بکر رضی اللہ عنہ تشریف لائے، میں نے ان سے ذکر کیا، انہوں نے کہا: اس کا آپ صلی اللہ علیہ وسلم سے رشتہ ہو سکتا ہے؟ جبکہ وہ آپ صلی اللہ علیہ وسلم کی بھتیجی لگتی ہے؟ میں واپس گئی اور نبی کریم صلی اللہ علیہ وسلم سے اس کا ذکر کیا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: “ان سے کہو، تم میرے اسلامی بھائی ہو، اور تمہاری بیٹی میرے رشتہ میں آسکتی ہے۔” انہوں نے ان کا نکاح آپ صلی اللہ علیہ وسلم سے کر دیا، وہ اس وقت چھ برس کی تھیں، ابھی رخصتی نہیں ہوئی تھی، پھر سیدہ سودہ رضی اللہ عنہا کا قصہ بیان کیا۔ صحیح میں یہ بھی ہے کہ آپ صلی اللہ علیہ وسلم نے ان کے سوا اور کسی کنواری سے نکاح نہیں کیا۔ اس پر تمام راویوں کا اتفاق ہے، سیدہ عائشہ رضی اللہ عنہا کی کنیت ام عبد اللہ ہے، بعض کا قول ہے: ان کے ہاں نبی کریم صلی اللہ علیہ وسلم سے بچہ ہوا جو فوت ہو گیا تھا، بہر حال یہ بات ثابت نہیں۔ بعض کا قول ہے: انہوں نے اپنے بھانجے عبداللہ بن زبیر پر یہ کنیت رکھی، یہ دوسرا قول ان سے کئی طرق سے منقول ہے، اس میں سے یہ ہے: ابن سعد نے یزید بن ہارون سے انہوں نے حماد سے، انہوں نے ہشام بن عروہ سے انہوں نے عباد بن حمزہ سے، انہوں نے عائشہ سے روایت کیا ہے۔ شعبی رحمہ اللہ فرماتے ہیں: حضرت مسروق رحمہ اللہ جب سیدہ عائشہ رضی اللہ عنہا سے روایت کرتے تو فرماتے: مجھ سے صدیق کی بیٹی صدیقہ نے جو اللہ کے حبیب صلی اللہ علیہ وسلم کی محبوبہ ہیں حدیث بیان کی۔ ابوالضحیٰ نے بحوالہ مسروق فرمایا: میں نے اکابر صحابہ رضی اللہ عنہم کو ان سے فرائض کے بارے میں سوال کرتے ہوئے دیکھا، عطاء بن ابی رباح فرماتے ہیں: سیدہ عائشہ رضی اللہ عنہا تمام لوگوں میں فقیہ، عالمہ تھیں اور عام لوگوں میں اچھی رائے کی مالک تھیں۔ ہشام بن عروہ بحوالہ اپنے والد فرماتے ہیں: “فقہ، طب، شعر و شاعری میں سیدہ عائشہ رضی اللہ عنہا سے زیادہ (خواتین میں سے) کسی کو دستگاہ حاصل نہ تھی۔” ابو بردہ بن ابو موسیٰ بحوالہ اپنے والد فرماتے ہیں: جب ہمیں کسی معاملے میں کوئی مشکل پیش آتی تو ہم سیدہ عائشہ رضی اللہ عنہا سے سوال کرتے، انہیں اس کا علم ہوتا۔ زہری رحمہ اللہ فرماتے ہیں: اگر سیدہ عائشہ رضی اللہ عنہا کا علم جمع کیا جائے اور تمام امہات المؤمنین اور صحابیات رضی اللہ عنہن کا علم ان کے مقابلے میں جمع کیا جائے تو سیدہ عائشہ رضی اللہ عنہا کا علم زیادہ ہوگا۔ زبیر بن بکار نے ابوزناد سے مسنداً روایت کیا ہے، فرماتے ہیں: میں نے عروہ سے زیادہ شعر روایت کرنے والا کوئی نہیں دیکھا۔ انہیں کہا گیا: آپ کو شعر کی روایت میں اتنی قدرت کیسے ہوئی؟ انہوں نے کہا: سیدہ عائشہ رضی اللہ عنہا کی روایت میں میری روایت ایسے ہی ہے انہیں جب بھی کوئی بات پیش آتی تو اس کے متعلق شعر کہہ دیتیں۔ صحیح میں ابو موسیٰ اشعری سے مرفوعاً روایت ہے: “سیدہ عائشہ رضی اللہ عنہا کی خواتین پر ایسی فضیلت ہے جیسی ثرید کی باقی کھانوں پر”۔(5) صحیح میں حماد کے طریق سے، ہشام بن عروہ سے بحوالہ اپنے والد مروی ہے۔ سیدہ عائشہ رضی اللہ عنہا کی باری کے دن لوگ اپنے ہدیے بھیجنے کی کوشش کرتے تھے، فرماتی ہیں: باقی تمام ازواج سیدہ ام سلمہ رضی اللہ عنہا کے ہاں جمع ہوئیں ... پھر حدیث ذکر کی، اس میں ہے: آپ صلی اللہ علیہ وسلم نے تیسری مرتبہ فرمایا: “مجھے عائشہ کے بارے میں ایذاء نہ دو، اللہ کی قسم! تم میں سے اس کے بستر کے سوا مجھ پر وحی نازل نہیں ہوئی۔”(6) ترمذی نے ثوری کے طریق سے، ابو اسحاق سے بحوالہ عمرو بن غالب نقل کیا ہے کہ کسی نے سیدنا عمار بن یاسر رضی اللہ عنہ کے پاس سیدہ عائشہ رضی اللہ عنہا کی شان میں نازیبا الفاظ کہے تو فرمایا: بکواس بند کرو! کیا تم رسول اللہ صلی اللہ علیہ وسلم کی محبوبہ کو ایذاء دیتے ہو؟ اسے ابن سعد نے دوسرے طریق سے ابو اسحاق سے بحوالہ حمید بن عریب اسی طرح نقل کیا ہے، فرماتے ہیں: “بکواس اور بیہودہ بات” اور یہ اضافہ نقل کیا ہے: وہ آپ صلی اللہ علیہ وسلم کی جنت میں زوجہ ہیں۔ مسلم میں بطین سے مرسلا روایت ہے، فرماتے ہیں، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “عائشہ رضی اللہ عنہا جنت میں میری زوجہ ہے”۔ ابومحمد مولی غفار بین کے طریق سے ہیں کہ سیدہ عائشہ رضی اللہ عنہا نے فرمایا: یا رسول اللہ صلی اللہ علیہ وسلم! جنت میں آپ کی بیوی کون سی ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: “تم ان میں سے ہو”۔ ابو اسحاق کے طریق سے بحوالہ سفیان بن سعد روایت ہے، فرماتے ہیں: سیدنا عمر رضی اللہ عنہ نے نبی کریم صلی اللہ علیہ وسلم کی ازواج میں سے سیدہ عائشہ رضی اللہ عنہا کے وظیفے میں دو ہزار درہم کا اضافہ کیا، کیونکہ وہ رسول اللہ صلی اللہ علیہ وسلم کی محبوبہ ہیں۔ صحیح بخاری و مسلم میں ابن عون کے طریق سے بحوالہ قاسم بن محمد روایت ہے، سیدہ عائشہ رضی اللہ عنہا بیمار ہوئیں، سیدنا عباس رضی اللہ عنہ آئے اور کہا: اے ام المومنین! بے حد سچائی کی بناء پر آپ مجھ سے آگے بڑھ گئیں۔ (حدیث)۔ ابن سعد رحمہ اللہ فرماتے ہیں: ہمیں ہشام نے اور وہ ابن عبدالملک طیالسی ہیں، خبر دی کہ ہم سے ابوعوانہ نے عبدالملک بن عمیر سے انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کیا، فرماتی ہیں: مجھے آپ صلی اللہ علیہ وسلم نے اپنی مسواک دی جو کسی اور زوجہ کو نہیں دی، جب رسول اللہ صلی اللہ علیہ وسلم سے میرا نکاح ہوا تو میں سات سال کی تھی، اور آپ صلی اللہ علیہ وسلم کے پاس فرشتہ ہاتھ میں میری تصویر لے کر آیا، تا کہ آپ اسے دیکھ لیں۔ میری رخصتی ہوئی تو میں نو برس کی تھی، میں نے جبرائیل کو دیکھا ہے، میں آپ صلی اللہ علیہ وسلم کی ازواج میں آپ صلی اللہ علیہ وسلم کو سب سے زیادہ محبوب تھی۔ میں نے آپ صلی اللہ علیہ وسلم کی تیمارداری کی ہے جب آپ صلی اللہ علیہ وسلم کی وفات ہوئی تو آپ صلی اللہ علیہ وسلم کے پاس میرے اور فرشتوں کے علاوہ کوئی موجود نہ تھا۔ دوسرے طریق سے مروی ہے اس میں عیسی بن میمون ہیں جو بہت کمزور راوی ہیں، سیدہ عائشہ رضی اللہ عنہا فرماتی ہیں: مجھے دس چیزوں سے فضیلت دی گئی ... پھر انہوں نے ذکر کیا کہ حضرت جبرائیل علیہ السلام ان کی تصویر لے کر آئے۔ فرماتی ہیں: آپ صلی اللہ علیہ وسلم نے میرے سوا کسی کنواری عورت سے نکاح نہیں کیا اور میرے سوا کسی عورت کے ماں باپ دونوں نے ہجرت نہیں کی، اللہ تعالیٰ نے آسمان سے میری براءت نازل فرمائی، جب آپ پر وحی نازل ہوتی تو آپ صلی اللہ علیہ وسلم میرے ساتھ ہوتے۔ میں اور آپ صلی اللہ علیہ وسلم ایک برتن میں غسل کرتے تھے، وہ نماز پڑھتے اور میں آپ صلی اللہ علیہ وسلم کے سامنے سوئی ہوتی۔ میرے حجرے اور میری باری میں آپ صلی اللہ علیہ وسلم نے میری ٹھوڑی اور سینے کے درمیان سر رکھے ہوئے وفات پائی، اور آپ صلی اللہ علیہ وسلم میرے حجرے میں دفن ہوئے۔ ابن سعد نے ام درہ کے طریق سے نقل کیا ہے، فرماتی ہیں: سیدہ عائشہ رضی اللہ عنہا کے پاس ایک لاکھ درہم آئے، انہوں نے سارے تقسیم کر دیئے، وہ اس وقت روزہ سے تھیں، میں نے ان سے عرض کی، آپ اپنے افطار کے لیے ایک درہم کا گوشت خرید سکتی تھیں؟ کہنے لگیں: اگر تم مجھے یاد دلاتی تو ایسا کر لیتی، سیدہ عائشہ رضی اللہ عنہا نے نبی کریم صلی اللہ علیہ وسلم سے بہت سی احادیث مبارکہ روایت کیں، اسی طرح اپنے والد، سیدنا عمر، سیدہ فاطمہ، سیدنا سعد بن ابو وقاص اسید بن حضیر، جذامہ بنت وہب، حمزہ بنت عمر رضی اللہ عنہم سے احادیث روایت کیں۔ سیدہ عائشہ رضی اللہ عنہا سے ان صحابہ رضی اللہ عنہم نے روایت کیا، سیدنا عمر اور ان کے بیٹے عبداللہ ابو ہریرہ، ابو موسیٰ، زید بن خالد، ابن عباس، ربیعہ بن عمرو جرشی، سائب بن یزید، صفیہ بنت شیبہ، عبداللہ بن عامر بن ربیعہ، عبداللہ بن حارث بن نوفل وغیرہ۔ ان کے گھر والوں میں سے ان لوگوں نے روایت کیا۔ ان کی بہن ام کلثوم، ان کے رضاعی بھائی عوف بن حارث، ان کے بھتیجے قاسم اور عبداللہ بن محمد بن ابوبکر، ان کے دوسرے بھائی کی بیٹی حفصہ اور اسماء بنت عبد الرحمن بن ابوبکر اور ان کا پوتا عبداللہ بن ابو عتیق، محمد بن عبد الرحمن، ان کے دونوں بھانجوں عبداللہ اور عروہ جو زبیر بن عوام کے بیٹے ہیں، جو اسماء بنت ابوبکر سے ہیں، اسماء کے دونوں پوتے عباد اور حبیب جو سیدنا عبداللہ بن زبیر کے بیٹے ہیں، سیدنا عبداللہ کے پوتے عباد بن حمزہ بن عبد اللہ بن زبیر، ان کی بھانجی عائشہ بنت طلحہ جو ام کلثوم بنت ابوبکر سے ہیں، ان کے موالی ابوعمر، ذکوان، ابو یونس، ابن فروخ، اکابر تابعین میں سے ان سے سعید بن مسیب، عمرو بن میمون، علقمہ بن قیس، مسروق، عبداللہ بن حکیم، اسود بن یزید، ابوسلمہ بن عبدالرحمن، ابووائل اور دوسرے بہت سے لوگوں نے روایت کی۔ اکثر کے نزدیک سترہ رمضان کو منگل کے دن ۵۸ھ میں وفات پاگئیں۔(7) بعض کا قول ہے: ۵۷ھ میں۔ یہ علی بن مدینی کا ابن عیینہ سے بحوالہ ہشام بن عروہ قول ہے، بقیع میں دفن کی گئیں۔","",{"fn":"(1) اسد الغابة (۷۰۸۵) تجرید (۲۸۶/۲)\n(2) المعجم الكبير (۱۶/۲۳)\n(3) الاستيعاب (۱۸۸۱/۴)\n(4) الأحاد والمثاني (۳۸۹/۵، ۳۹۰)\n(5) بخاری (۳۷۷۰) (۵۴۱۹) (۵۴۲۸) مسلم (۶۲۴۹)\n(6) بخاری (۳۷۷۵)\n(7) اسد الغابة (۳۴۴/۵)"}],[11415,"§۱۱۴۵۳ ۔ عائشہ بنت جریر\n(1) بن عمرو بن رزاح انصاریہ، بنو سلمہ سے ہیں، ابن حبیب نے بیعت کرنے والی خواتین میں ان کا ذکر کیا ہے، فرماتے ہیں: ابومنذر یزید بن عامر بن حدیدہ کی زوجہ تھیں۔","",{"fn":"(1) اسد الغابة (۷۰۸۶) تجرید (۲۸۶/۲)"}],[11416,"§۱۱۴۵۴ ۔ عائشہ بنت سعد\n(1) بن ابو وقاص زہریہ، ان کے والد کے سوانح میں ان کا نسب گزر چکا ہے۔ صحیحین میں سعد بن ابو وقاص سے مروی ہے کہ انہوں نے نبی کریم صلی اللہ علیہ وسلم سے فرمایا، جب آپ صلی اللہ علیہ وسلم تشریف لائے، فتح کے سال یا حجتہ الوداع میں وہ مکہ میں بیمار تھے، میری ایک بیٹی کے علاوہ کوئی وارث نہیں۔ نووی رحمہ اللہ نے مبہمات میں فرمایا: ان کا نام عائشہ ہے، تجرید میں اس کا تعاقب کیا گیا ہے کہ عائشہ بنت سعد تابعیہ ہیں، وہ اتنا عرصہ زندہ رہیں کہ حضرت مالک رحمہ اللہ کی ان سے ملاقات ہوئی، یہ تعاقب ناپسندیدہ ہے۔ کیونکہ جن کا سیدنا سعد نے ذکر کیا ہے، بڑی ہیں، وہ جن سے مالک کی ملاقات ہوئی صغری ہیں۔ امام مالک رحمہ اللہ اور اہل علم میں سے کسی نے حضرت عائشہ بنت سعد کبری کے طبقہ کا زمانہ نہیں پایا، اور رہی صغریٰ تو وہ نبی کریم صلی اللہ علیہ وسلم کے بہت عرصے بعد پیدا ہوئیں، انہوں نے ان کا عنوان قائم نہیں کیا، کیونکہ انہوں نے بعض امہات المومنین کا زمانہ پایا۔","",{"fn":"(1) تجرید (۲۸۶/۲)"}],[11417,"§۱۱۴۵۵ ۔ عائشہ بنت ابی سفیان\n(1) بن حارث بن زید انصاریہ، بنوعبد الاشہل سے ہیں، ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابة (۷۰۸۸) تجرید (۲۸۶/۲)"}],[11418,"§۱۱۴۵۶ ۔ عائشہ بنت شیبہ\nبن ربیعہ بن عبد شمس۔ ان کے والد بدر میں قتل ہوئے، ان کا ذکر ہے، ابوزناد فقیہ مدنی کی مولاۃ ہیں۔"],[11419,"§۱۱۴۵۷ ۔ عائشہ بنت عبد الرحمن\n(1) بن عتیک نظریہ، ان کے شوہر رفاعہ کے سوانح میں ان کا ذکر گزر چکا ہے۔ یہ ابوموسیٰ کا قول ہے۔","",{"fn":"(1) اسد الغابة (۷۰۸۹) تجرید (۲۸۶/۲)"}],[11420,"§۱۱۴۵۸ ۔ عائشہ بنت عمیر\n(1) بن حارث بن ثعلبہ انصاریہ، بنو حرام سے ہیں۔ ابن حبیب نے بیعت کرنے والی خواتین میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابة (۷۰۹۱)"}],[11421,"§۱۱۴۵۹ ۔ عائشہ بنت قدامہ\n(1) بن مظعون قرشیہ جمحیہ۔ ان کے چچا عثمان بن مظعون کے سوانح میں ان کا نسب گزر چکا ہے۔ ابوعمر(2) کا قول ہے: بیعت کرنے والوں میں سے ہیں، اہل مدینہ میں ان کا شمار ہے۔ میں کہتا ہوں: مکیہ ہیں اور مذکورہ بیعت مکہ میں ہوئی۔ امام احمد(3) رحمہ اللہ نے ان کی حدیث عبدالرحمن بن عثمان بن ابراہیم بن محمد بن طالب کے طریق سے روایت کی ہے، وہ فرماتے ہیں: مجھ سے میرے والد نے بحوالہ اپنی والدہ عائشہ بنت قدامہ روایت کیا، فرماتی ہیں: میں اپنی والدہ رابطہ بنت سفیان کے ساتھ تھی اور نبی کریم صلی اللہ علیہ وسلم عورتوں سے بیعت لے رہے تھے۔ فرمایا: “کیا تم اس بات پر بیعت کرتی ہو کہ اللہ کے ساتھ کسی کو شریک نہ ٹھہراؤ گی۔ (الحدیث) اس میں ہے: “تم بھلائی کے کاموں میں میری نافرمانی نہ کرو گی۔” انہوں نے سر جھکا لیا۔ فرماتے ہیں، انہوں نے کہا: “جہاں تک ہم سے ہو سکا۔ وہ یہ الفاظ کہہ رہی تھیں اور میں بھی ان کے ساتھ کہہ رہی تھی، میری والدہ نے مجھے تلقین کی، اس لیے جیسا وہ کہہ رہی تھیں میں بھی وہی کہنے لگی۔ ہم نے عالی سند سے ابن مندہ کی کتاب معرفہ میں دوسرے طریق سے اسے روایت کیا ہے۔ بحوالہ عبدالرحمن بن عثمان، اس میں ہے: اپنی والدہ رابطہ بنت سفیان جو خزاعہ کی خاتون ہیں۔ ابو نعیم نے دوسرے طریق سے اس سند کے ساتھ دو احادیث بحوالہ عائشہ بنت قدامہ نقل کی ہیں۔ وہ ان دونوں میں فرماتی ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا، اور وہ ابن سعد کے اس قول پر رد ہے کہ انہوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت نہیں کی، ان کی روایت میں ہے: ان کی والدہ فاطمہ بنت سفیان ہیں، شائد یہ اس نسخے سے ہو، صحیح یہ ہے، رابطہ بنت سفیان بن حارث بن امیہ بن فضل بن منقذ خزاعیہ، فرمایا: سیدہ عائشہ رضی اللہ عنہا کا نکاح ابراہیم بن محمد بن حاطب سے ہوا، ان سے اولاد ہوئی۔","",{"fn":"(1) اسد الغابة (۷۰۹۲) الاستيعاب (۳۴۷۸) تجرید (۲۸۶/۲)\n(2) الاستيعاب (۱۸۸۶/۴)\n(3) مسند احمد (۳۶۵/۶)"}],[11422,"§۱۱۴۶۰ ۔ عائشہ بنت معاویہ\n(1) بن مغیرہ بن ابو عاص بن امیہ، عبدالملک بن مروان کی والدہ ہیں۔ ان کے والد اُحد میں حالت کفر میں قتل ہوئے، ان کی والدہ فاطمہ بنت عامر جمحی ہیں، ابن اسحاق کا قول ہے: جب نبی کریم صلی اللہ علیہ وسلم اور آپ صلی اللہ علیہ وسلم کے اصحاب واقعہ اُحد کے بعد حمراء الاسد کی طرف روانہ ہوئے اس اندیشے سے کہ ابو سفیان اور اس کے حواری لوٹ نہ آئیں، انہیں ابوعزہ جمحی اور معاویہ بن مغیرہ جن کا ذکر ہے، ملے۔ آپ صلی اللہ علیہ وسلم نے عاصم بن ثابت کو ابو عزہ کے قتل کا حکم دیا اور سیدنا عثمان بن عفان رضی اللہ عنہ نے معاویہ کو اس شرط پر امان دی کہ وہ تین دن کے بعد نظر نہ آئے۔ نبی کریم صلی اللہ علیہ وسلم نے اس کے بعد سیدنا زید بن حارثہ اور عمار بن یاسر کو بھیجا، اور انہیں فرمایا: تم دونوں اسے فلاں مقام پر مقتول پاؤ گے۔ میں کہتا ہوں: ان سیدہ عائشہ رضی اللہ عنہا نے نبی کریم صلی اللہ علیہ وسلم کی زندگی میں سات برس کا زمانہ پایا۔ پہلے گزر چکا ہے کہ مکہ میں حجتہ الوداع کے موقع پر قریش کے تمام لوگ اسلام لا چکے تھے اور حاضر تھے۔","",{"fn":"(1) تجرید (۲۸۷/۲)"}],[11423,"§۱۱۴۶۱ ۔ عبادہ بنت ابی نائلہ\n(1) بن سلامہ بن وقش انصاریہ۔ ان کے والد کے سوانح میں ان کا نسب گزر چکا ہے۔ ابن حبیب نے بیعت کرنے والوں میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابة (۷۰۹۳) تجرید (۲۸۷/۲)"}],[11424,"§۱۱۴۶۲ ۔ عتبہ بنت زرارہ\n(1) بن عدس انصاریہ، ابن حبیب نے بیعت کرنے والوں میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابة (۷۰۹۴) تجرید (۲۸۷/۲)"}],[11425,"§۱۱۴۶۳ ۔ عجلہ بنت عجلان اللیثیہ\nبنو لیث بن سعد بن بکر بن عبد مناة بن کنانہ سے ہیں۔ رکانہ بن عبد یزید اور ان کے بھائیوں کی والدہ ہیں، یہ وہی ہیں جنہیں ابو رکانہ نے طلاق دی اور نبی کریم صلی اللہ علیہ وسلم نے انہیں ان پر لوٹا دیا تھا، عبد یزید کے سوانح میں ان کا ذکر گزر چکا ہے۔"],[11426,"§۱۱۴۶۴ ۔ العجماء الانصاریہ\n(1) ابوامامہ بن سہل بن حنیف کی خالہ ہیں، ابوامامہ نے اپنی خالہ عجماء سے روایت کیا، فرماتی ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: “بوڑھا اور بڑھیا جب زنا کریں تو انہیں یقینا رجم کیا جائے، اس لیے کہ انہوں نے لذت اٹھائی۔” طبرانی(2) رحمہ اللہ اور ابن مندہ نے اسے نقل کیا ہے۔","",{"fn":"(1) اسد الغابة (۷۰۹۵) تجرید (۲۸۷/۲)\n(2) المعجم الكبير (۸۶۷/۲۴)"}],[11427,"§۱۱۴۶۵ ۔ عدیہ بنت سعد\nبن خلیفہ بن اشرف انصاریہ بنو حارث بن خزرج بن ساعدہ سے ہیں۔ ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔"],[11428,"§۱۱۴۶۶ ۔ عزہ بنت الحارث الہلالیہ\n(1) میمونہ کی بہن ہیں۔ ابو عمر(2) نے مختصر ان کا ذکر کیا ہے۔ اور فرمایا: میرے خیال میں کسی نے صحابہ رضی اللہ عنہم میں ان کا ذکر نہیں کیا۔ میں کہتا ہوں: ابن سعد نے غرائب میں صحابیہ خواتین میں ان کی ماں شریک بہنوں کے ساتھ ان کا ذکر کیا ہے، اور کہا ہے وہ سیدہ میمونہ ام المومنین کی بہن ہیں۔ ان کا نکاح عبد اللہ بن مالک بن ہرم سے ہوا جس سے زیادہ، عبدالرحمن، برزہ پیدا ہوئے۔ برزہ سے اسہم جو یزید کے والد ہیں پیدا ہوئے۔ بعض کا قول ہے: یزید بن اسہم کی والدہ ہیں، فرماتے ہیں، بعض کا قول ہے: برزہ، عزہ کی ماں شریک بہن ہیں۔ فرماتے ہیں، بعض نے کہا: عزہ بنو کلاب کے ایک شخص کے نکاح میں تھیں، ان سے اولاد ہوئی۔","",{"fn":"(1) اسد الغابة (۷۰۹۹) الاستيعاب (۳۴۷۹) تجرید (۲۸۷/۲)\n(2) الاستيعاب (۱۸۸۶/۴)"}],[11429,"§۱۱۴۶۷ ۔ عزہ بنت خابل\n(1) ابو عمرہ(2) نے ذکر کیا ہے کہ عزہ بنت کامل، پہلا قول صحیح ہے۔ ابن ابو عاصم اور طبرانی نے اوسط میں موسیٰ بن یعقوب کے طریق سے، عطاء بن مسعود کعبی سے بحوالہ ان کی پھوپھی عزہ بنت خابل نقل کیا ہے کہ وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئیں، اور ان سے اس بات پر بیعت کی کہ اللہ کے ساتھ کسی کو شریک نہ ٹھہرائیں گی، نہ چوری کریں گی، نہ زنا کریں گی، نہ یہ اذیت دیں گی، نہ کسی بچی کو زندہ درگور کریں گی نہ چھپائیں گی۔ عزہ فرماتی ہیں: مجھے معلوم ہے داد تو اولاد کا قتل کرتا ہے، رہا خفی، تو وہ مجھے معلوم نہیں، میں نے رسول اللہ صلی اللہ علیہ وسلم سے اس کے بارے میں سوال نہیں کیا، میرے دل میں آیا کہ اس سے مراد بچے کو ضائع کرنا ہے۔ اللہ کی قسم! میں نے اپنا کوئی بچہ ضائع نہیں کیا۔ ابو عمر فرماتے ہیں: ان سے ایک حدیث مروی ہے، جس کی سند درست نہیں۔","",{"fn":"(1) اسد الغابة (۷۱۰۰) الاستيعاب (۳۴۸۱) تجرید (۲۸۷/۲)\n(2) الاستيعاب (۱۸۸۶/۴)"}],[11430,"§۱۱۴۶۸ ۔ عزہ بنت ابی سفیان\n(1) بن حرب امویہ، ام حبیبہ جو نبی کریم صلی اللہ علیہ وسلم کی زوجہ ہیں، ان کی بہن ہیں۔ یہ ثابت ہے کہ یہ وہی ہیں جنہیں ام المومنین نے نبی کریم صلی اللہ علیہ وسلم پر نکاح کے لیے پیش کیا، آپ صلی اللہ علیہ وسلم نے فرمایا: “وہ میرے لیے حلال نہیں”۔ وہ کہنے لگیں: ہمیں معلوم ہوا ہے کہ آپ ابوسلمہ کی بیٹی سے نکاح کریں گے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: “وہ اگر میری پرورش میں نہ ہوتی تب بھی حلال نہ تھی، کیونکہ وہ میرے رضاعی بھائی کی بیٹی ہے، مجھ پر اپنی بیٹیوں اور بہنوں کو نکاح کے لیے پیش نہ کرو۔” لیٹ کی روایت میں بحوالہ یزید بن ابو حبیب، انہوں نے زہری سے انہوں نے زینب بنت ابوسلمہ سے، انہوں نے ام حبیبہ(2) سے ان کا نام عزہ ذکر کیا ہے، جو مسلم اور نسائی میں ہے۔ حرف دال میں ان کا نام درہ گزر چکا ہے، ہو سکتا ہے کہ ان دونوں ناموں میں سے ایک ان کا لقب ہو، محفوظ روایت یہ ہے کہ ابو سلمہ کی بیٹی کا نام دُرّہ ہے۔ صحیح میں بھی ان کا نام مذکور ہے۔","",{"fn":"(1) اسد الغابة (۷۱۰۱) الاستيعاب (۳۴۸۰)\n(2) مسلم (۳۵۷۱)"}],[11431,"§۱۱۴۶۹ ۔ عزہ بنت ابی لہب\nبن عبدالمطلب ہاشمیہ۔ دار قطنی رحمہ اللہ نے کتاب الاخوۃ میں ان کا ذکر کیا ہے۔ اور فرمایا: ان سے حدیث مروی نہیں۔ ابن سعد فرماتے ہیں: ان سے اوفی بن حکیم بن امیہ بن حارثہ بن اوقص سلمی نے نکاح کیا جس سے عبیدہ، سعید اور ابراہیم پیدا ہوئے جو اوفی کے بیٹے ہیں۔"],[11432,"§۱۱۴۷۰ ۔ عزہ الاشجعیہ\n(1) ابو حازم کی مولاۃ ہیں، جنہوں نے انہیں آزاد کیا۔ ابو عمر(2) کا قول ہے۔ اشعث بن سوار کے پاس بحوالہ منصور ان کی حدیث ہے، انہوں نے ابو حازم اشجعی سے روایت کیا انہوں نے اپنی مولاۃ عزہ سے روایت کیا، فرماتی ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: “تمہارے لیے دو سرخ چیزوں میں ہلاکت ہے: سونا اور زعفران۔”(3)","",{"fn":"(1) اسد الغابة (۷۰۹۸) الاستيعاب (۳۴۸۲) تجرید (۲۸۷/۲)\n(2) الاستيعاب (۱۸۸۶/۴)\n(3) جامع المسانيد والسنن (۶۱۱/۱۵)"}],[11433,"§۱۱۴۷۱ ۔ عزیزہ بنت ابی تجراہ\nعبدریہ، برہ کی بہن ہیں۔ بلاذری نے ان کا ذکر کیا ہے، اور ابن سعد اور ولید بن صالح دونوں سے بحوالہ واقدی نقل کیا ہے۔ انہوں نے عمیرہ بنت عبد اللہ بن کعب سے، انہوں نے عزیزہ بنت ابو تجراۃ سے روایت کیا ہے۔ فرماتی ہیں: قریش چاشت کی نماز سے واقف نہیں تھے، اور مسلمان پانچ نمازوں کے فرض ہونے سے پہلے چاشت اور عصر کی نماز پڑھتے تھے۔ نبی کریم صلی اللہ علیہ وسلم اور آپ کے اصحاب جب دن کے آخری حصے میں نماز پڑھنا ہوتی تو گھاٹیوں میں چلے جاتے اور تنہا نماز ادا کرتے۔"],[11434,"§۱۱۴۷۲ ۔ عصماء بنت الحارث الہلالیہ\nام خالد بن ولید ہیں، انہیں لبابہ صغری کہا جاتا ہے، ابن کلبی نے یہ ذکر کیا ہے، حرف لام میں اس کا ذکر آئے گا۔"],[11435,"§۱۱۴۷۳ ۔ عصمہ بنت حبان\n(1) بن صحر بن خنساء انصاریہ، بنو حرام سے ہیں۔ ابن حبیب نے بیعت کرنے والوں میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابة (۷۱۰۲) تجرید (۲۸۷/۲)"}],[11436,"§۱۱۴۷۴ ۔ عصیمہ\n(1) تصغیر کے ساتھ ہے، بنت افلح، ابن سعد نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) تجرید (۲۸۷/۲)"}],[11437,"§۱۱۴۷۵ ۔ عفراء بنت السکن\n(1) بن رافع بن معاویہ بن عبید، بنو خزرج سے ہیں، اسعد بن زرارہ کی والدہ ہیں۔ ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابة (۷۱۰۳) تجرید (۲۸۷/۲)"}],[11438,"§۱۱۴۷۶ ۔ عفراء بنت عبید\n(1) بن ثعلبہ بن سواد بن غنم، بعض کا قول ہے: ثعلبہ بن عبید بن ثعلبہ بن غنم بن مالک بن نجار۔ ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔ معاذ اور معوذ اور عوف جو بنو حارث کے بیٹے ہیں ان کی والدہ ہیں۔ بعض کا قول ہے: ان میں سے ہر ایک عفراء کا بیٹا ہے۔ ابن سعد(2) رحمہ اللہ کا قول ہے: ان کی والدہ رعاثہ بنت عدی بن معاذ ہیں۔ ان سے حارث بن رفاعہ بن حارث بن سواد نے نکاح کیا، جس سے اولاد ہوئی۔ ابن کلبی فرماتے ہیں: معاذ اور معوذ شہید ہوئے تو ان کی والدہ نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں اور کہنے لگیں: یا رسول اللہ! کیا عوف بن حارث کے بیٹوں میں سے یہ شریر تو نہیں ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: “نہیں”۔ ابن اثیر(3) کا قول ہے: ابن کلبی کو اس قول سے اتفاق نہیں کہ معاذ بدر کے دن شہید ہوئے۔ میں کہتا ہوں: ان عفراء کو ایسی خصوصیت حاصل ہے جو کسی اور کو حاصل نہیں۔ انہوں نے حارث کے بعد بکیر بن یالیل لیثی سے نکاح کیا، ان سے چار بیٹے پیدا ہوئے: ایاس، عاقل، خالد، عامر، سب بدر میں شہید ہوئے۔ ان کے ماں شریک بھائی جو حارث کے بیٹے ہیں، شہید ہوئے، اس سے معلوم ہوا کہ یہ وہ صحابیہ خاتون ہیں جن کے سات بیٹے ہیں اور سب نبی کریم صلی اللہ علیہ وسلم کے ساتھ جہاد کرتے ہوئے شہید ہو گئے۔","",{"fn":"(1) اسد الغابة (۷۱۰۴) تجرید (۲۸۷/۲)\n(2) الطبقات الكبرى (۳۲۵/۸)\n(3) اسد الغابة (۳۴۶/۵)"}],[11439,"§۱۱۴۷۷ ۔ عقرب بنت السکن\n(1) بن رافع۔ ابن سعد(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے، مجھے معلوم نہیں، یہ عفراء ہیں جن کے نام میں لفظی غلطی ہو گئی یا ان کی بہن ہیں۔","",{"fn":"(1) تجرید (۲۸۸/۲)\n(2) الطبقات الكبرى (۲۷۰/۸)"}],[11440,"§۱۱۴۷۸ ۔ عقرب بنت سلامہ\n(1) بن وقش، ابن سعد(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔ فرماتے ہیں: ان کی والدہ سہیمہ بنت عبداللہ واقفیہ ہیں، ان کا نکاح رافع بن یزید اشہلی سے ہوا، جس سے اسید پیدا ہوئے۔","",{"fn":"(1) اسد الغابة (۷۱۰۵) تجرید (۲۸۸/۲)\n(2) الطبقات الكبرى (۲۳۵/۸)"}],[11441,"§۱۱۴۷۹ ۔ عقرب بنت معاذ\n(1) بن نعمان بن امرئ القیس بن زید بن عبد الاشہل، ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔ فرماتے ہیں: قیس بن عظیم کی زوجہ ہیں، یزید بن قیس اور ان کے بھائی ثابت بن قیس کی والدہ ہیں۔ ابن سعد(2) کا قول ہے: سعد بن معاذ کی سگی بہن ہیں، اسلام لائیں اور بیعت کی، ان کا نکاح یزید بن گرز بن زعوراء بن عبد الاشہل سے ہوا، جن سے رافع اور حواء پیدا ہوئے، ان کے بعد قیس بن خطیم سے نکاح ہوا، جس سے ثابت اور یزید پیدا ہوئے، اسی سے ان کی کنیت ہے، جسر کے دن شہید ہوئے۔","",{"fn":"(1) اسد الغابة (۷۱۰۶) تجرید (۲۸۸/۲)\n(2) الطبقات الكبرى (۱۳۱/۸)"}],[11442,"§۱۱۴۸۰ ۔ عقیلہ بنت عتیک\nبن حارث عتوریہ، ابوعمر کا قول ہے: ہجرت کرنے والی اور بیعت کرنے والی خاتون ہیں۔ مدینے کی رہنے والی ہیں۔ ان کی حدیث موسیٰ بن عقبہ کے ہاں ہے۔ میں کہتا ہوں: طبرانی نے اسے بکار بن عبداللہ بن عبیدہ عبدی کے طریق سے بحوالہ ان کے چچا موسیٰ بن عبیدہ روایت کیا ہے۔ وہ فرماتے ہیں: مجھ سے زید بن عبدالرحمن بن ابوسلامہ نے بحوالہ اپنی والدہ حجتہ بنت قریط انہوں نے ان دونوں کی والدہ عقیلہ بنت عتیک بن حارث سے نقل کیا ہے، فرماتی ہیں: میں اور میری والدہ بریرہ بنت حارث عتوریہ مہاجر خواتین کے ساتھ آئیں، انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے بیعت کی، آپ صلی اللہ علیہ وسلم نے مقام ابطح میں ایک خیمہ لگایا ہوا تھا۔ آپ صلی اللہ علیہ وسلم نے ہم سے یہ شرط رکھی کہ ہم اللہ کے ساتھ کسی کو شریک نہ ٹھہرائیں گی، نہ چوری کریں گی ... (الحدیث) اس میں ہے: ہم نے اپنے ہاتھ بیعت کرنے کے لیے بڑھائے، آپ صلی اللہ علیہ وسلم نے فرمایا: “میں عورتوں سے ہاتھ نہیں ملاتا۔” آپ صلی اللہ علیہ وسلم نے ہمارے لیے بخشش کی دعا کی، یہ ہماری بیعت تھی۔ طبرانی رحمہ اللہ نے اسی طرح زید بن حباب کے طریق سے بحوالہ موسیٰ بن عبیدہ روایت کیا ہے، اور ان سے مروی روایت میں فرمایا: زید بن عبداللہ، حدیث میں ان کی جو یہ بات ہے کہ آپ صلی اللہ علیہ وسلم ... یہ بات دلالت کرتی ہے کہ وہ مکہ میں تھے۔ ابو موسیٰ ذیل میں فرماتے ہیں: بخاری اور طبرانی رحمہ اللہ نے اسے عقیلہ ذکر کیا ہے، اور ابن مندہ نے غفیلہ ذکر کیا ہے۔ میں کہتا ہوں: ابونعیم نے درست کہا، اسی طرح خطیب نے مؤتلف میں فرمایا، اور ان کی حدیث زید بن حباب کے طریق سے نقل کی ہے، اور اپنی روایت میں فرمایا: میں اور میری والدہ فروہ دونوں اکٹھی ہوئیں (یہ نام ف اور واؤ سے پہلے را ساکن کے ساتھ ہے) یہ وہم ہے۔"],[11443,"§۱۱۴۸۱ ۔ عکناء\n(1) نون یاث کے ساتھ، بنت ابوصفرہ اسدیہ، مہلب کی بہن ہیں۔ ابن مندہ کا قول ہے: ہمیں محمد بن محمد بن یعقوب نے بتایا، وہ فرماتے ہیں: ہمیں ابن صاعد نے بتایا وہ فرماتے ہیں: ہم سے محمد بن یحی ازدی نے روایت کی، انہوں نے فرمایا: ہم سے ہشام بن سفیان نے، وہ فرماتے ہیں ہم سے عبید اللہ بن عبداللہ نے، بحوالہ ابوشعثاء روایت کی، فرمایا: عکناء یا عکثاء بنت ابوصفرہ، مہلب کی بہن فرماتی ہیں: رسول اللہ صلی اللہ علیہ وسلم نے دس تاریخ کو عاشوراء کا روزہ رکھنے کا حکم دیا، میں نے ان سے ابوشعثاء کے بارے میں دریافت کیا، انہوں نے فرمایا: “وہ مجہول شیخ ہیں اور جابر بن زید نہیں”۔(2) میں کہتا ہوں: ابواحمد حاکم نے کنیتوں میں ان ابو الشعثاء کا ذکر نہیں کیا، ابن حبان نے ثقات میں ہشام بن سفیان کا ذکر کیا، اور چوتھے طبقے میں فرماتے ہیں: ہشام بن سفیان محروزی وہ عبید اللہ بن عبد اللہ علکی سے بحوالہ ابو بریدہ روایت کرتے ہیں: ان کی ابوالشعثاء سے روایت کا ذکر نہیں کیا، اور تابعین کی کنیتوں میں ابوشعثاء کے ذکر پر اعتماد نہیں کیا۔","",{"fn":"(1) اسد الغابة (۷۱۰۸) تجرید (۲۸۸/۲)\n(2) جامع المسانيد والسنن (۶۱۳/۱۵)"}],[11444,"§۱۱۴۸۲ ۔ علیہ\n(1) بنت شریح حضرمی، سائب بن زید کی ماں شریک بہن ہیں۔ مخرمہ بن شریح کی بہن ہیں جن کا ذکر نبی کریم صلی اللہ علیہ وسلم کے سامنے ہوا تو آپ صلی اللہ علیہ وسلم نے فرمایا: “وہ ایسا شخص ہے جو قرآن کو تکیہ نہیں بناتا۔”(2)","",{"fn":"(1) اسد الغابة (۷۱۱۰) تجرید (۲۸۸/۲)\n(2) نسائی (۱۷۸۲) احمد (۴۴۹/۳) طبرانی (۶۶۵۴/۷)"}],[11445,"§۱۱۴۸۳ ۔ عمارہ بنت حباشہ\n(1) بن جبیر، ابن سعد نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) تجرید (۲۸۸/۲)"}],[11446,"§۱۱۴۸۴ ۔ عمارہ بنت حمزہ\n(1) بن عبدالمطلب، سلمی بنت عمیس کے سوانح میں ان کا ذکر گزر چکا ہے۔","",{"fn":"(1) اسد الغابة (۷۱۱۱) تجرید (۲۸۸/۲)"}],[11447,"§۱۱۴۸۵ ۔ عمارہ بنت ابی ایوب\n(1) خالد بن زید انصاریہ۔ ابن حبیب نے نبی کریم صلی اللہ علیہ وسلم سے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔ ابن سعد نے بھی ان کا ذکر کیا اور فرمایا: ان سے صفوان بن اوس بن جابر بن قرط نے جو بنو معاویہ بن مالک بن نجار سے ہیں، نکاح کیا، ان سے خالد بن صفوان پیدا ہوئے۔","",{"fn":"(1) تجرید (۲۸۸/۲)"}],[11448,"§۱۱۴۸۶ ۔ عمرہ بنت البرصاء\nبنت حارث ہیں، جن کا ذکر آ رہا ہے۔"],[11449,"§۱۱۴۸۷ ۔ عمرہ بنت الحارث\n(1) بن ابوضرار خزاعیہ، مصطلقیہ۔ ام المؤمنین سیدہ جویریہ رضی اللہ عنہا کی بہن ہیں۔ محمد بن عمرو بن ابوضرار سے بحوالہ ان کی پھوپھی عمرہ انہوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کی ہے: “دنیا میٹھی اور سرسبز ہے، جس نے اس سے حلال طریقے سے کوئی شے حاصل کی، اسے اس میں برکت دی جاتی ہے۔ بہت سے لوگ اللہ اور اس کے رسول صلی اللہ علیہ وسلم کے مال میں ملوث ہوتے ہیں جن کے لیے قیامت کے روز جہنم ہے۔” ابن ابو عاصم(2) اور عبداللہ بن احمد نے اسے زیادات زہد میں اور ابن مندہ نے خالد بن سلمہ کی روایت سے بحوالہ محمد بن عمرو بن حارث نقل کیا ہے۔","",{"fn":"(1) اسد الغابة (۷۱۱۵) الاستيعاب (۳۴۸۶) تجرید (۲۸۹/۲)\n(2) الآحاد والمثاني (۸۵/۶)"}],[11450,"§۱۱۴۸۸ ۔ عمرہ بنت الحارث\nبن ابی عوف، قرصافہ کی بہن ہیں۔ مرزبانی نے ان کی بہن اور والدہ برصاء کے ساتھ ان کا ذکر کیا ہے۔ بعض کا قول ہے: ان کا نام امامہ ہے۔"],[11451,"§۱۱۴۸۹ ۔ عمرہ بنت حارثہ\nبن نعمان انصاریہ، بنو مالک بن نجار سے ہیں۔ ابن سعد فرماتے ہیں: ان سے قیس بن عمرو بن سہل بن ثعلبہ نے نکاح کیا جو بنو عمرو بن عوف سے ہیں، اسلام لائیں اور بیعت کی۔"],[11452,"§۱۱۴۹۰ ۔ عمرہ بنت حرام\n(1) بعض کا قول ہے: بنت حزم، انصاریہ۔ سعد بن ربیع کی زوجہ ہیں۔ حدیث جابر میں ان کا ذکر ہے جسے ابن ابو عاصم(2) اور طبرانی(3) وغیرہ نے یحی بن ایوب کے طریق سے بحوالہ محمد بن ثابت بنانی، انہوں نے محمد بن منکدر سے، انہوں نے جابر سے، انہوں نے عمرہ بنت حزم سے روایت کیا ہے۔ آپ صلی اللہ علیہ وسلم کے لیے بکری ذبح کی گئی، آپ صلی اللہ علیہ وسلم نے اس سے کھایا اور وضو کیا پھر ظہر کی نماز پڑھی، پھر آپ صلی اللہ علیہ وسلم کے سامنے یہ گوشت پیش کیا گیا، آپ صلی اللہ علیہ وسلم نے تناول فرمایا اور عصر کی نماز ادا کی، پھر دوبارہ وضو نہیں کیا۔ طبرانی رحمہ اللہ نے بنت حرام اور دوسرے راویوں نے بنت حزم لکھا ہے۔ ابو عمر(4) نے اسی کا یقین کیا ہے اور اسے مختصر ذکر کیا ہے۔","",{"fn":"(1) اسد الغابة (۷۱۱۶) الاستيعاب (۳۴۸۷) تجرید (۲۸۹/۲)\n(2) الآحاد والمثاني (۲۶۳/۶)\n(3) المعجم الكبير (۸۴۸/۲۴)\n(4) الاستيعاب (۱۸۸۷/۴)"}],[11453,"§۱۱۴۹۱ ۔ عمرہ بنت حزم الانصاریہ\nجابر نے ان سے آگ پر پکی ہوئی چیز کھانے کے بعد وضو نہ کرنے کے بارے میں حدیث ذکر کی ہے، ابن مندہ کا قول ہے: اسے عبداللہ بن محمد بن عقیل نے بحوالہ جابر روایت کیا ہے اور ان کا نام نہیں لیا۔ ابن سعد نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے، فرماتے ہیں: عمرہ بنت حزام بن زید بن لوذان بن عمرو بن عبد بن عوف بن غنم بن مالک بن نجار، فرماتے ہیں: عمرو بن حزم کی بہن اور ان کے دونوں بھائیوں عمارہ اور معمر کی سگی بہن ہیں، ان کی والدہ خالدہ بنت ابوانس ہیں۔"],[11454,"§۱۱۴۹۲ ۔ عمرہ بنت الربیع\n(1) بن نعمان بن سیاف انصاریہ، بنو مالک بن نجار سے ہیں۔ ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے، فرماتے ہیں: ان کا نام عمیرہ ہے۔","",{"fn":"(1) اسد الغابة (۷۱۱۷) تجرید (۲۸۹/۲)"}],[11455,"§۱۱۴۹۳ ۔ عمرہ بنت رواحہ الانصاریہ\n(1) ان کے بھائی عبداللہ بن رواحہ کے سوانح میں ان کا نسب گزر چکا ہے۔ بشیر بن سعد کی زوجہ ہیں جو نعمان کے والد ہیں۔ یہ وہی ہیں جنہوں نے بشیر سے سوال کیا کہ ان کے بیٹے کو اس کے دوسرے بھائیوں سے علیحدہ خاص عطیہ دے۔ نبی کریم صلی اللہ علیہ وسلم نے اسے رد کر دیا، صحیحین(2) میں حدیث ہے۔ یہ وہی ہیں جن کا قیس بن خطیم نے اپنے قصیدے کی تشبیب میں ذکر کیا ہے۔ انہوں نے کہا: “عمرہ ان سردار عورتوں میں سے ہے جس کی آستینیں خوشبو سے مہکتی رہتی ہیں۔”(3) بعض کا قول ہے: قیس بن خطیم نے ان سے نکاح کیا، جب حسان نے عمرہ کے بارے میں جو قیس کی بہن ہیں شعر کہے تو قیس نے ان کے بارے میں شعر کہے، بعض کا قول ہے قیس کی بہن کا نام لیلی ہے۔ وہ صحیح ہے۔ بعض نے کہا: جس کے بارے میں سیدنا حسان نے شعر کہے وہ عمرہ بنت صامت بن خالد بن عطیہ ہے جسے انہوں نے طلاق دے دی تھی پھر انہیں دل سے نہ بھلا سکے۔ زبیر بن بکار نے یہ اپنے چچا مصعب سے نقل کیا ہے، مسند طیالسی(4) نے بحوالہ شعبہ، انہوں نے محمد بن نعمان سے، انہوں نے طلحہ یامی سے، انہوں نے عبد القیس کی زوجہ سے، انہوں نے عبداللہ بن رواحہ کی بہن سے نقل کیا۔ فرماتی ہیں: “ہر بالغہ عورت پر نکلنا واجب قرار دیا گیا، یعنی نماز عید وغیرہ کے لیے۔”","",{"fn":"(1) اسد الغابة (۷۱۱۸) تجرید (۲۸۹/۲)\n(2) بخاری (۲۵۸۷، ۲۶۵۰) مسلم (۴۱۶۱)\n(3) دیوان قیس بن خطیم (۲۴، ۲۵) (۱۹۸، ۱۹۹)\n(4) مسند طيالسي (۱۶۲۲)"}],[11456,"§۱۱۴۹۴ ۔ عمرہ بنت سعد\nبن عمرو بن زید مناة بن عدی بن عمرو بن مالک بن نجار، بعض نے کہا: بنت سعد بن قیس، ابوموسیٰ کا قول ہے: سعد بن عبادہ کی والدہ ہیں، بعض نے کہا: عمرہ بنت مسعود ان کا ذکر آگے آ رہا ہے۔"],[11457,"§۱۱۴۹۵ ۔ عمرہ بنت سعد\nبن مالک بن خالد ساعدی سہل بن سعد کی بہن ہیں، عمیرہ میں ان کا ذکر آئے گا۔"],[11458,"§۱۱۴۹۶ ۔ عمرہ بنت السعدی\n(1) بن وقدان بن عبد شمس عامریہ۔ ان کے بھائی عبد اللہ بن سعدی کے سوانح میں ان کا نسب گزر چکا ہے۔ ابن اسحاق(2) نے حبشہ کی سرزمین کی طرف ہجرت کرنے والوں میں ان کا ذکر کیا ہے۔ فرماتے ہیں: مالک بن قیس بن ربیعہ اور ان کے ساتھ ان کی زوجہ عمرہ بنت سعدی ہیں، بعض نے کہا: ان کا نام عمیرہ ہے۔","",{"fn":"(1) اسد الغابة (۷۱۲۰) تجرید (۲۸۹/۲)\n(2) السيرة النبوية (۲۶۰/۱) (۹۰۵/۴)"}],[11459,"§۱۱۴۹۷ ۔ عمرہ بنت عویم\n(1) مستغفری رحمہ اللہ نے بخاری رحمہ اللہ کے حوالے سے ان کا ذکر کیا ہے اور ابو موسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابة (۷۱۲۱) تجرید (۲۸۹/۲)"}],[11460,"§۱۱۴۹۸ ۔ عمرہ بنت قیس\n(1) بن عمرو انصاریہ۔ ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔ ابو شیخ بن ثابت کی والدہ ہیں جو حسان کے بھائی ہیں، یہ ابن حبیب کا قول ہے۔ ابن سعد(2) نے اس کی مخالفت کی ہے، فرماتے ہیں: ان کے والد کا نام مسعود ہے جیسا کہ آگے آ رہا ہے۔","",{"fn":"(1) اسد الغابة (۷۱۲۲) تجرید (۲۸۹/۲)\n(2) الطبقات الكبرى (۲۹۹/۸)"}],[11461,"§۱۱۴۹۹ ۔ عمرہ بنت مرثد\n(1) اسماء کی بہن ہیں، ابن حبیب(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابة (۷۱۲۳) تجرید (۲۸۹/۲)\n(2) المحبر (۴۱۳)"}],[11462,"§۱۱۵۰۰ ۔ عمرہ بنت مسعود\n(1) بن اوس بن مالک بن سواد بن ظفر انصاریہ۔ ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے، فرماتے ہیں: عبد اللہ بن محمد بن سلمہ کی والدہ ہیں۔","",{"fn":"(1) اسد الغابة (۷۱۲۴) الاستيعاب (۳۴۸۹) تجرید (۲۸۹/۲)"}],[11463,"§۱۱۵۰۱ ۔ عمرہ بنت مسعود\n(1) بن حارث بن رفاعہ انصاریہ، بنو نجار سے ہیں، ابن حبیب(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابة (۷۱۲۵) تجرید (۲۸۹/۲)\n(2) المحبر (۴۳۱)"}],[11464,"§۱۱۵۰۲ ۔ عمرہ بنت مسعود\n(1) بن زرارہ بن عدی انصاریہ، بنو مالک بن نجار سے ہیں، ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔ ابن سعد فرماتے ہیں: اسعد بن زرارہ کی بھتیجی ہیں، ان کی والدہ مخزومیہ ہیں۔ ان سے علقمہ بن عمرو بن یغوث بن مالک بن مبذول نے نکاح کیا، عمرہ اسلام لائیں اور بیعت کی۔","",{"fn":"(1) اسد الغابة (۷۱۲۶) تجرید (۲۸۹/۲)"}],[11465,"§۱۱۵۰۳ ۔ عمرہ بنت مسعود بن قیس\n(1) بن عمرو بن زید مناة بن عدی بن عمرو بن مالک بن نجار سعد بن عبادہ کی والدہ ہیں۔ نبی کریم صلی اللہ علیہ وسلم کی حیات مبارکہ میں ۵ھ میں وفات پائی۔ ابن سعد رحمہ اللہ کا قول ہے: انہوں نے وفات پائی اور نبی کریم صلی اللہ علیہ وسلم غزوہ دومۃ الجندل میں تھے، یہ ربیع الاول کا واقعہ ہے، جب نبی کریم صلی اللہ علیہ وسلم مدینہ تشریف لائے تو ان کی قبر پر آئے ان کی نماز جنازہ پڑھی۔ میں کہتا ہوں: یہ ثابت ہے کہ انہوں نے وفات پائی تو نبی کریم صلی اللہ علیہ وسلم سے ان کے بیٹے نے ان کی طرف سے صدقہ کرنے کے بارے میں پوچھا۔","",{"fn":"(1) اسد الغابة (۷۱۲۶) تجرید (۲۸۹/۲)"}],[11466,"§۱۱۵۰۴ ۔ عمرہ بنت مسعود الصغری\n(1) سعد بن عبادہ کی خالہ ہیں۔ اوس بن زید بن اصرم بن زید بن ثعلبہ بن غنم کی زوجہ تھیں، ان سے ابومحمد پیدا ہوئے، ان کا نام مسعود بن اوس تھا، ان سے اس کے بعد سہل بن ثعلبہ بن حارث بن زید نے نکاح کیا، جس سے عمر، رغیبہ پیدا ہوئے، اسلام لائیں اور بیعت کی۔","",{"fn":"(1) تجرید (۲۸۹/۲)"}],[11467,"§۱۱۵۰۵ ۔ عمرہ بنت مسعود\n(1) بن قیس انصاریہ۔ ان دونوں کی بہن ہیں جو پہلے گزر چکی ہیں۔ ابن سعد کا قول ہے، یہ پانچ بہنیں تھیں، ان میں سے ہر ایک کا نام عمرہ تھا، اسلام لائیں اور بیعت کی، یہ تیسری ہیں، ان کی والدہ عمیرہ بنت عمرو بن حرام بن زید مناہ تھا۔ ثابت بن منذر بن حرام نے جو حمان اور ان کے بھائیوں کے والد ہیں، ان سے نکاح کیا، جس سے ابو شیخ بن ثابت پیدا ہوئے، جن کا نام ابی تھا، وہ بدر میں شریک تھے۔ اسلام لائے اور بیعت کی۔","",{"fn":"(1) تجرید (۲۸۹/۲)"}],[11468,"§۱۱۵۰۶ ۔ عمرہ بنت مسعود\n(1) بن قیس رابعہ، اپنے سے پہلے والی کی سگی بہن ہیں۔ زید بن مالک بن عبدود بن کعب بن عبد الاشہل نے ان سے نکاح کیا۔ ان سے سعد اور ثابت پیدا ہوئے۔","",{"fn":"(1) تجرید (۲۸۹/۲)"}],[11469,"§۱۱۵۰۷ ۔ عمرہ بنت مسعود\n(1) بن قیس خامسہ ہیں، اپنے سے پہلے والی دو عمرہ کی سگی بہنیں ہیں، قیس بن عمرو جو بنو نجار سے ہیں ان کی والدہ ہیں۔","",{"fn":"(1) تجرید (۲۸۹/۲)"}],[11470,"§۱۱۵۰۸ ۔ عمرہ بنت معاویہ الکندیہ\n(1) ابونعیم نے ان خواتین میں ان کا ذکر کیا ہے جن سے نبی کریم صلی اللہ علیہ وسلم نے نکاح کیا اور رخصتی نہیں ہوئی، محمد بن اسحاق کے طریق سے بحوالہ حکیم بن حکیم، انہوں نے محمد بن علی بن حسین سے، انہوں نے اپنے والد سے نقل کیا ہے، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے کندہ سے، عمرہ بنت معاویہ سے نکاح کیا۔ مجالد کے طریق سے بحوالہ شعبی رحمہ اللہ یہ نقل کیا ہے۔ نبی کریم صلی اللہ علیہ وسلم نے کندہ کی ایک خاتون سے نکاح کیا، وہ نبی کریم صلی اللہ علیہ وسلم کی وفات کے بعد لائی گئیں۔","",{"fn":"(1) اسد الغابة (۷۱۲۷) تجرید (۲۹۰/۲)"}],[11471,"§۱۱۵۰۹ ۔ عمرہ بنت ہرال\n(1) بن عمرو بن اوس انصاریہ، بنو عمرو بن عوف بن خزرج سے ہیں۔ ابن حبیب(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابة (۷۱۲۸) تجرید (۲۹۰/۲)\n(2) المحبر (۴۲۴)"}],[11472,"§۱۱۵۱۰ ۔ عمرہ بنت یزید الکلابیہ\n(1) ابن اسحاق(2) نے یونس بن بکیر کی روایت سے ان کا ذکر ان خواتین میں کیا ہے جن سے نبی کریم صلی اللہ علیہ وسلم نے نکاح کیا، فرماتے ہیں: عمرہ بنت یزید سے جو بنوابوبکر بن کلاب کی ایک خاتون تھیں، نبی کریم صلی اللہ علیہ وسلم نے نکاح کیا، یہ بنو وحید کی شاخ ہے، فضل بن عباس بن عبد المطلب نے ان سے نکاح کیا پھر طلاق دے دی۔ پھر رسول اللہ صلی اللہ علیہ وسلم نے رخصتی سے قبل انہیں طلاق دے دی تھی۔ ان کے نسب کے بارے میں کہا گیا: عمرہ بنت یزید بن عبید بن اوس بن کلاب۔","",{"fn":"(1) اسد الغابة (۷۱۲۹) الاستيعاب (۳۴۹۰) تجرید (۲۹۰/۲)\n(2) اسد الغابة (۷۱۲۹) تجرید (۲۹۰/۲)"}],[11473,"§۱۱۵۱۱ ۔ عمرہ بنت یزید بن الجون\n(1) بعض کا قول ہے: رسول اللہ صلی اللہ علیہ وسلم نے ان سے نکاح کیا، آپ صلی اللہ علیہ وسلم کو یہ بات پہنچی کہ انہیں برص کا مرض ہے، تو آپ صلی اللہ علیہ وسلم نے انہیں طلاق دے دی، ان کی رخصتی نہیں ہوئی۔ بعض کا قول ہے: انہوں نے آپ صلی اللہ علیہ وسلم سے پناہ مانگی۔ آپ صلی اللہ علیہ وسلم نے فرمایا: “تمہیں پناہ دینے والے کی پناہ ملی”۔ پھر انہیں طلاق دے دی، اور اسامہ بن زید کو حکم دیا کہ انہیں تین کپڑے دے دیں، اسے ہشام بن عروہ نے بحوالہ ان کے والد سیدہ عائشہ رضی اللہ عنہا سے روایت کیا ہے۔","",{"fn":"(1) اسد الغابة (۷۱۲۹) تجرید (۲۹۰/۲)"}],[11474,"§۱۱۵۱۲ ۔ عمرہ بنت یزید بن السکن\n(1) بن رافع بن امرئ القیس اشہلیہ۔ ابن حبیب(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابة (۷۱۳۰) تجرید (۲۹۰/۲)\n(2) المحبر (۴۱۶)"}],[11475,"§۱۱۵۱۳ ۔ عمرہ بنت یسار\n(1) بن ازمہر۔ ابو موسیٰ نے ذیل میں ان کا ذکر بحوالہ مستغفری کیا ہے اور فرمایا: انہیں شرف صحابیت حاصل ہے۔","",{"fn":"(1) اسد الغابة (۷۱۳۱) الاستيعاب (۳۴۹۱) تجرید (۲۹۰/۲)"}],[11476,"§۱۱۵۱۴ ۔ عمرہ بنت یعار\n(1) بعض کا قول ہے: یہ وہی ہیں جنہوں نے سالم مولی ابو حذیفہ کو آزاد کیا، مشہور ہے کہ ان کا نام ثبیتہ ہے۔","",{"fn":"(1) اسد الغابة (۷۱۳۲) تجرید (۲۹۰/۲)"}],[11477,"§۱۱۵۱۵ ۔ عمرہ الاشہلیہ\n(1) ابن مندہ نے ان کا ذکر کیا ہے اور یوسف بن نافع کے طریق سے، بحوالہ عبیدہ رائی، انہوں نے عمرہ اشہلیہ سے نقل کیا ہے، فرماتی ہیں: ہمارے پاس رسول اللہ صلی اللہ علیہ وسلم تشریف لائے اور ہماری مسجد میں ظہر اور عصر کی نماز پڑھی۔ آپ صلی اللہ علیہ وسلم ایک روزہ سے تھے، جب سورج غروب ہوا، موذن نے اذان دی، آپ صلی اللہ علیہ وسلم کے پاس افطاری کے لیے بازو اور کندھے کا بھنا ہوا گوشت لایا گیا، آپ صلی اللہ علیہ وسلم اسے دانتوں سے کاٹ کر کھانے لگے، پھر مؤذن نے اذان دی، انہوں نے ایک کپڑے سے اپنے ہاتھ صاف کیے، کھڑے ہوئے اور نماز ادا کی، جبکہ پانی سے اعضاء نہیں دھوئے۔ آگ پر پکی ہوئی چیز کھانے کے بعد وضو نہ کرنے کے بارے میں عمرہ بنت حزم کی حدیث گزر چکی ہے۔ شاید وہ یہی ہیں۔ دونوں حدیثوں کے سیاق میں تعدد ہے (یعنی وہ الگ ہے اور یہ الگ)۔","",{"fn":"(1) اسد الغابة (۷۱۱۲) تجرید (۲۸۸/۲)"}],[11478,"§۱۱۵۱۶ ۔ عمیرہ\n(1) بنت ثابت بن نعمان ظفریہ، ابن سعد(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) تجرید (۲۹۰/۲)\n(2) الطبقات الكبرى (۲۴۹/۸)"}],[11479,"§۱۱۵۱۷ ۔ عمیرہ بنت جبیر\n(1) بن صخر بن امیہ بن خنساء بن عبید بن عدی بن غنم بن کعب بن سلمہ سلمیہ۔ ابن سعد نے ان کا ذکر کیا ہے۔ اور فرمایا: ان سے کعب بن مالک نے نکاح کیا، جس سے عبداللہ، فضالہ، وہب، معبد، خولہ، سعاد پیدا ہوئے۔ عمیرہ نے بیعت کی اور دونوں قبلوں کی جانب نماز پڑھی، ان کے بارے میں مروی ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے حدیث سنی۔","",{"fn":"(1) تجرید (۲۹۰/۲)"}],[11480,"§۱۱۵۱۸ ۔ عمیرہ بنت الحارث بن عبد رزاح ظفریہ\n(1)","",{"fn":"(1) تجرید (۲۹۰/۲)"}],[11481,"§۱۱۵۱۹ ۔ عمیرہ بنت ابی الحکم\n(1) رافع بن سنان، ان سے بکر بن بکار نے بحوالہ عبدالحمید بن جعفر روایت کیا، مجھ سے میرے والد اور ہماری قوم کے کئی لوگوں نے روایت کیا کہ ابوالحکم اسلام لائے اور ان کی زوجہ اسلام نہیں لائی، وہ نبی کریم صلی اللہ علیہ وسلم کے پاس آئی اور کہنے لگی: ابوالحکم نے میری بیٹی لے لی ہے اور اسے اپنے پاس روکا ہوا ہے، آپ صلی اللہ علیہ وسلم نے ابوالحکم کو حکم دیا وہ ایک کونے میں بیٹھ گئے، اور عورت کو حکم دیا وہ دوسرے کونے میں بیٹھ گئی، ان دونوں کے درمیان اس بچی کو رکھا، پھر فرمایا: “تم دونوں اسے بلاؤ۔” ان دونوں نے اسے بلایا، وہ بچی اپنی والدہ کی طرف مائل ہوئی۔ آپ صلی اللہ علیہ وسلم نے فرمایا: اے اللہ! اسے ہدایت دے۔ وہ اپنے والد کی طرف چلی گئی۔ انہوں نے اسے لے لیا، ان کا نام عمیرہ ہے۔(2) ابو نعیم اور ابو موسیٰ نے اپنے طریق سے اسے نقل کیا ہے، اور دار قطنی رحمہ اللہ نے دوسرے طریق سے اسے بحوالہ عبدالحمید بن جعفر، انہوں نے اپنے والد، انہوں نے اپنے دادا سے نقل کیا ہے۔ نسائی، ابن ماجہ دوسرے طریق سے بحوالہ عثمان البتی اسے نقل کیا ہے، فرمایا: بحوالہ عبدالحمید بن سلمہ، انہوں نے اپنے والد سے، انہوں نے اپنے دادا سے بعض نے اسے مرسل روایت کیا ہے۔ ابو موسیٰ فرماتے ہیں: اس طریق کے علاوہ منقول ہے، اور لڑکی کا نام نہیں لیا۔","",{"fn":"(1) اسد الغابة (۷۱۳۳) تجرید (۲۹۰/۲)\n(2) ابوداؤد (۲۲۴۴) نسائی (۳۴۹۵) ابن ماجہ (۲۳۵۲) مسند احمد (۴۴۶/۵)"}],[11482,"§۱۱۵۲۰ ۔ عمیرہ بنت خماشہ\n(1) یا خباشہ انصاریہ، بنو خطمہ سے ہیں۔ ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابة (۷۱۳۴) تجرید (۲۰۹/۲)"}],[11483,"§۱۱۵۲۱ ۔ عمیرہ بنت ابی خیثمہ\n(1) عبد اللہ بن سماعہ کے سوانح میں ان کا ذکر ہے، امیمہ بنت ابو خیثمہ کی بہن ہیں، حرف ہمزہ میں جن کا ذکر گزر چکا ہے۔ ابن سعد کا قول ہے: اسلام لائیں اور بیعت کی، ان سے یزید بن اسید بن ساعدہ نے نکاح کیا وہ ان کے چچا زاد ہیں، اس کے بعد یزید بن زید بن بوع بن زید ظفری نے ان سے نکاح کیا۔","",{"fn":"(1) تجرید (۲۹۰/۲)"}],[11484,"§۱۱۵۲۲ ۔ عمیرہ بنت الربیع\nبن راساف، عمرہ میں ان کا ذکر گزر چکا ہے۔"],[11485,"§۱۱۵۲۳ ۔ عمیرہ بنت سعد\n(1) بن عامر بن عدی بن جشم انصاریہ۔ ابن سعد نے بیعت کرنے والی خواتین میں ان کا ذکر کیا ہے، اور فرمایا: ان سے کباشہ بن اوس بن قیلی بن عمرو بن زید بن جشم نے نکاح کیا۔","",{"fn":"(1) تجرید (۲۹۰/۲)"}],[11486,"§۱۱۵۲۵ ۔ عمیرہ بنت السعدی\nعمرہ میں ان کا ذکر گزر چکا ہے۔"],[11487,"§۱۱۵۲۶ ۔ عمیرہ بنت سہل\n(1) بن رافع، دو صاع صدقہ کرنے والے ہیں، جنہیں منافقین نے طعنہ دیا تھا۔ ابن مندہ فرماتے ہیں: انہوں نے نبی کریم صلی اللہ علیہ وسلم کا زمانہ پایا ہے۔ ابو عمر(2) کا قول ہے: سیدنا سہل اپنی بیٹی عمیرہ اور ایک صاع کھجور لے کر آئے اور عرض کیا: یا رسول اللہ! مجھے ایک حاجت ہے، آپ صلی اللہ علیہ وسلم نے پوچھا: “وہ کیا؟” عرض کیا: آپ اللہ سے میرے لیے اور میری بیٹی کے لیے دعا کریں اور اس کے سر پر ہاتھ پھیریں، اس کے علاوہ میری کوئی اولاد نہیں۔ عمیرہ فرماتی ہیں: آپ صلی اللہ علیہ وسلم نے اپنی ہتھیلی میرے سر پر رکھی، اللہ کی قسم! آپ صلی اللہ علیہ وسلم کے ہاتھ کی ٹھنڈک مجھے جگر تک پہنچی ہوئی(3) محسوس ہوتی ہے۔ میں کہتا ہوں: اسے ابن مندہ نے عیسی بن یونس کے طریق سے، سعید بن عثمان بلوی سے بحوالہ ان کی دادی روایت کیا ہے، عمیرہ بنت سہل نے ان سے حدیث بیان کی کہ ان کے والد دو صاع کھجور صدقہ، اور اپنی بیٹی عمیرہ کو لے کر نکلے، یہاں تک کہ نبی کریم صلی اللہ علیہ وسلم کے پاس پہنچے، وہ دو صاع انڈیل دیئے... پھر باقی حدیث انہی الفاظ کے ساتھ ذکر کی ہے۔","",{"fn":"(1) اسد الغابة (۷۱۳۶) تجرید (۲۹۱/۲)\n(2) الاستيعاب (۱۸۸۸/۴)\n(3) طبرانی (۸۴۹/۲۴) الحديث (۵۶۵۰/۱) مجمع الزوائد (۳۳/۷) جامع المسانيد والسنن (۶۱۹/۱۵)"}],[11488,"§۱۱۵۲۷ ۔ عمیرہ بنت سہیل\n(1) بن ثعلبہ بن حارث بن زید بن ثعلبہ بن غنم بن مالک بن نجار انصاریہ۔ ابن سعد نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے اور فرمایا: امیمہ بنت عمرو بن حارث بن قیس بن وقش ساعدیہ ان کی والدہ ہیں، ان سے ابوامامہ اسعد بن زرارہ نے نکاح کیا، جس سے ان کی بیٹیاں، فریعہ، کبشہ اور حبیبہ پیدا ہوئیں، ان سب نے بیعت کی۔","",{"fn":"(1) تجرید (۲۹۱/۲)"}],[11489,"§۱۱۵۲۸ ۔ عمیرہ بنت ظہیر\n(1) بن رافع بن عدی انصاریہ، بنو بکشم سے ہیں، ان کے والد کے سوانح میں ان کا نسب گزر چکا ہے، ابن سعد(2) اور ابن حبیب نے بیعت کرنے والوں میں ان کا ذکر کیا ہے۔ ابن سعد کا قول ہے: ان کی والدہ فاطمہ بنت بشر بن عدی ہیں جو مربع بن قیلی کی زوجہ ہیں۔","",{"fn":"(1) اسد الغابة (۷۱۳۷)، تجرید (۲۹۱/۲)\n(2) الطبقات (۲۳۹/۵)"}],[11490,"§۱۱۵۲۹ ۔ عمیرہ بنت عبد سعد\n(1) بن عامر بن عدی: ابن سعد اور ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابة (۷۱۳۸)، تجرید (۲۹۱/۲)"}],[11491,"§۱۱۵۳۰ ۔ عمیرہ بنت عبید\n(1) بن معروف یا مطروف بن حارث بن زید بن عبید انصاریہ، بنو عمرو بن عوف سے ہیں، ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابة (۷۱۳۹)، تجرید (۲۹۱/۲)"}],[11492,"§۱۱۵۳۱ ۔ عمیرہ بنت عقبہ\n(1) بن انتیجہ انصاریہ، بنو تجھی سے ہیں، ابن حبیب(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابة (۷۱۴۰)، تجرید (۲۹۱/۲)\n(2) المحبر (۴۱۸)"}],[11493,"§۱۱۵۳۲ ۔ عمیرہ بنت عمیر\n(1) بن ساعدہ بن عائش انصاریہ، ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) تجرید (۲۹۱/۲)"}],[11494,"§۱۱۵۳۳ ۔ عمیرہ بنت فرظہ\n(1) بن خنساء بن سنان، بنو حرام سے ہیں، ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابة (۷۱۴۱)، تجرید (۲۹۱/۲)"}],[11495,"§۱۱۵۳۴ ۔ عمیرہ بنت قیس\n(1) بن عمرو بن عبید بن مالک بن عدی بن حارث بن سلیط بن قیس انصاریہ: ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے، ابن سعد(2) کا قول ہے: محمد بن عمر نے ذکر کیا کہ اسلام لائیں اور بیعت کی، میں نے قابل اعتماد نسخے میں میم کے زبر کے ساتھ لکھا ہوا پایا۔","",{"fn":"(1) اسد الغابة (۷۱۴۲)، تجرید (۲۹۱/۲)\n(2) الطبقات (۳۰۹/۸)"}],[11496,"§۱۱۵۳۵ ۔ عمیرہ بنت قیس\n(1) بن ابو کعب انصاریہ، بنو سواد سے ہیں، ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے، سہل بن قیس کی بہن ہیں جو اُحد کے دن شہید ہوئے۔","",{"fn":"(1) اسد الغابة (۷۱۴۳)، تجرید (۲۹۱/۲)"}],[11497,"§۱۱۵۳۶ ۔ عمیرہ بنت کلثوم\n(1) بن عدم انصاریہ: ان کے والد کے سوانح میں ان کا نسب گزر چکا ہے، ابن سعد(2) اور ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابة (۷۱۴۴)، تجرید (۲۹۱/۲)\n(2) الطبقات (۲۵۵/۸)"}],[11498,"§۱۱۵۳۷ ۔ عمیرہ بنت محمد\nبن سلمہ انصاریہ ان کے والد کے سوانح میں ان کا ذکر گزر چکا ہے۔ قرطبی رحمہ اللہ نے تفسیر میں بیان کیا ان کے بارے میں یہ آیت نازل ہوئی۔ “مرد عورتوں پر حاکم ہیں... بلند اور بڑا ہے۔”(1) میں نے اسے ثعلبی رحمہ اللہ کی تفسیر میں ابن کلبی کے طریق سے پایا، فرماتے ہیں: سعد بن ربیع نے اپنی زوجہ عمیرہ کو تھپڑ مارا، وہ نبی کریم صلی اللہ علیہ وسلم کے پاس شکایت لے کر گئیں، آپ صلی اللہ علیہ وسلم نے فرمایا: قصاص ہے، تو یہ آیت نازل ہوئی۔ میں نے دوسرے دو اقوال کا ذکر کیا ہے جن کے بارے میں آیت نازل ہوئی اور کلبی نہایت کمزور راوی ہے۔","",{"fn":"(1) سورة النساء الآية ۳۴"}],[11499,"§۱۱۵۳۸ ۔ عمیرہ بنت مرثد\n(1) بن جبیر بن مالک انصاریہ، اسماء کی بہن ہیں: ابن سعد کا قول ہے: اسلام لائیں اور بیعت کی، سلامہ بنت مسعود بن کعب ان کی والدہ ہیں، سوید بن نعمان سے ان کا نکاح ہوا۔","",{"fn":"(1) تجرید (۲۹۱/۲)"}],[11500,"§۱۱۵۳۹ ۔ عمیرہ بنت مسعود الانصاریہ\n(1) ابونعیم اور ابوموسیٰ نے اپنے طریق سے اس کا ذکر کیا ہے۔ پھر ابوعروبہ حرانی کے طریق سے، وہ فرماتے ہیں: ہم سے ہلال بن بشر نے بیان کیا۔ وہ فرماتے ہیں: ہم سے اسحاق بن ادریس نے بیان کیا، وہ فرماتے ہیں ہم سے ابراہیم بن جعفر بن محمود بن محمد بن سلمہ نے بیان کیا کہ ان کی دادی عمیرہ بنت مسعود نے ان سے بیان کیا کہ وہ اور ان کی پانچ بہنیں رسول اللہ صلی اللہ علیہ وسلم کے پاس آئیں۔ انہوں نے آپ صلی اللہ علیہ وسلم سے بیعت کی، دیکھا کہ آپ صلی اللہ علیہ وسلم گوشت کھا رہے ہیں آپ صلی اللہ علیہ وسلم نے ان کے لیے گوشت چبایا اور پھر انہیں دیا جسے انہوں نے آپس میں تقسیم کر لیا، اور ہر ایک نے وہ بوٹی چبائی، مرتے دم تک ان کے منہ سے بد بو پیدا نہیں ہوئی اور نہ انہیں منہ کی کوئی بیماری پیدا ہوئی۔(2)","",{"fn":"(1) اسد الغابة (۷۱۴۵)، تجرید (۲۹۱/۲)\n(2) المعجم الكبير (۸۵۲/۲۴)، مجمع الزوائد (۲۸۳/۸)، جامع المسانيد والسنن (۶۲۱/۱۵)"}],[11501,"§۱۱۵۴۰ ۔ عمیرہ بنت معاذ الانصاریہ\nروح بن ثابت کی زوجہ ہیں جو نبی کریم صلی اللہ علیہ وسلم کے کاتب ہیں، ان کا ذکر گزر چکا ہے۔"],[11502,"§۱۱۵۴۱ ۔ عمیرہ بنت معوذ\nبن عفراء، ربیع کی بہن ہیں، ابن سعد نے بیعت کرنے والی خواتین میں ان کا ذکر کیا ہے، ان کا نسب ان کے والد کا نام ربیع کے سوانح میں گزر چکا ہے، ابن سعد فرماتے ہیں: ان سے ابو حسن بن عبد عمرو مازنی نے نکاح کیا، جس سے عمارہ، عمر اور شتر یہ پیدا ہوئے۔"],[11503,"§۱۱۵۴۲ ۔ عمیرہ بنت یزید\n(1) بن سکن ابن رافع بن امری القیس بن زید بن عبدالاشہل اشہلیہ، ابن سعد(2) نے ان کا ذکر کیا ہے اور فرمایا: اسلام لائیں اور بیعت کی، ان کی والدہ ام سعد بنت حرام بن مسعود ہیں۔ ان سے منظور بن لبید بن عقبہ نے نکاح کیا، جس سے حارث اور عشیرہ پیدا ہوئے۔","",{"fn":"(1) اسد الغابة (۷۱۳۰)، (۳۴۹۰)، تجرید (۲۹۰/۲)\n(2) الطبقات الكبرى (۲۳۳/۸)"}],[11504,"§۱۱۵۴۳ ۔ عنبہ (بے نسبت)\n(1) ابو نعیم نے ان کا ذکر کیا ہے اور ابوبکر مقری کے حوالے سے محمد بن قارن سے، انہوں نے ابوزرعہ سے، انہوں نے غسان بن فضل سے روایت کیا ہے، وہ فرماتے ہیں: ہم سے صبیح بن سعید نجاشی ۱۸۰ھ میں روایت کیا ہے۔ ان کا گمان ہے کہ وہ ۱۵۷ھ تک کا سن رکھتے ہیں میں نے اپنی والدہ سے فرماتے ہوئے سنا: ان کا نام عنبہ تھا، بدل کر رسول اللہ صلی اللہ علیہ وسلم نے عنقودہ(2) رکھ دیا۔ خطیب نے اسے مؤتلف میں دوسری سند سے بحوالہ محمد بن قارن نقل کیا ہے، صبیح مذکورہ جو راوی ہے یحیی بن معین نے اسے جھوٹا کہا ہے۔","",{"fn":"(1) اسد الغابة (۷۱۴۶)، تجرید (۲۹۱/۲)\n(2) جامع المسانيد السنن (۶۲۱/۱۵)"}],[11505,"§۱۱۵۴۴ ۔ عنقودہ\n(1) پہلے والے میں گزر چکی ہیں۔","",{"fn":"(1) اسد الغابة (۷۱۴۶)، تجرید (۲۹۱/۲)"}],[11506,"§۱۱۵۴۵ ۔ عُنقودہ\n(1) دوسری ہیں، سیدہ عائشہ رضی اللہ عنہا کی لونڈی ہیں۔ ابوموسی نے ذیل میں مستغفری کے حوالے سے ان کا ذکر کیا ہے، فرمایا: ان کی حدیث کی اسناد میں تردد ہے۔ یزید بن قیس بن جراح کے طریق سے بحوالہ صبیح، انہوں نے علی بن حمید سے، انہوں نے اپنے والد حمید بن حوشب سے، انہوں نے حسن سے، انہوں نے علی سے روایت کی، فرماتے ہیں: جب رسول اللہ صلی اللہ علیہ وسلم نے سیدنا معاذ رضی اللہ عنہ کو یمن کی طرف بھیجنے کا ارادہ کیا تو فرمایا: یمن کے لیے کون تیار ہے؟ سیدنا ابوبکر رضی اللہ عنہ نے عرض کیا: میں، آپ صلی اللہ علیہ وسلم خاموش ہو گئے، آپ صلی اللہ علیہ وسلم نے پھر فرمایا: یمن کے لیے کون تیار ہے؟ سیدنا معاذ رضی اللہ عنہ نے عرض کیا: میں، آپ صلی اللہ علیہ وسلم نے فرمایا: تم اس کے لیے ہو اور وہ تمہارے لیے ہے، انہوں نے سامان تیار کیا اور آپ علیہ السلام نے انہیں الوداع کرتے ہوئے فرمایا: اے معاذ! میں تمہیں اللہ تعالیٰ سے ڈرنے، حسن عمل، کلام کی نرمی، سچی بات کرنے، اور امانت کی ادائیگی کی وصیت کرتا ہوں، اے معاذ! آسانی پیدا کرو، مشکل پیدا نہ کرنا۔ پھر نبی کریم صلی اللہ علیہ وسلم کی وفات اور سیدنا معاذ رضی اللہ عنہ کے یمن سے لوٹنے مدینہ داخل ہونے اور نبی کریم صلی اللہ علیہ وسلم کے گھر رات کے وقت آنے کے بارے میں طویل حدیث ذکر کی، اور یہ کہ انہوں نے دروازہ کھٹکھٹایا تو سیدہ عائشہ رضی اللہ عنہا نے فرمایا: یہ کون ہے جو رات کو ہمارے دروازے پر دستک دے رہا ہے؟ انہوں نے فرمایا: میں معاذ ہوں، سیدہ عائشہ رضی اللہ عنہا نے کہا: اے عنقودہ! دروازہ کھولو(2)...... پھر انہوں نے نبی کریم صلی اللہ علیہ وسلم کی وفات کے بارے میں طویل حدیث ذکر کی۔ ابوموسیٰ فرماتے ہیں: حدیث ابن عمر سے طوالات میں املا کراتی ہے۔ لیکن سیدہ عائشہ رضی اللہ عنہا کی لونڈی کا نام عُنفیرہ لیا ہے، تجرید(3) میں فرماتے ہیں: یہ حدیث منکر ہے، اور پہلی اولی ہیں۔ میں کہتا ہوں: اس میں کوئی شک نہیں کہ یہ گھڑی ہوئی ہے، اس میں رکیک الفاظ ہیں جو سیدنا معاذ رضی اللہ عنہ اور عمار، عائشہ فاطمہ، حسین رضی اللہ عنہم کی طرف منسوب ہیں۔ اس میں ہے کہ سیدنا معاذ رضی اللہ عنہ نے سیدہ عائشہ رضی اللہ عنہا سے پوچھا: آپ نے نبی کریم صلی اللہ علیہ وسلم کو بیماری اور وفات میں کیسا پایا، وہ کہنے لگیں: اے معاذ! میں آپ صلی اللہ علیہ وسلم کی وفات کے وقت موجود نہ تھی، یہ فاطمہ ہیں ان سے پوچھ لو، اس میں ہے: سیدنا معاذ رضی اللہ عنہ نے رات کے وقت غیبی آواز سنی” اے معاذ! تمہیں کیسے میٹھی نیند آتی ہے، اور محبوب نبی حضور محمد صلی اللہ علیہ وسلم مٹی کی تہوں کے درمیان ہیں۔ (یعنی لحد میں) سیدنا معاذ رضی اللہ عنہ نے اپنا ہاتھ اپنے سر پر رکھا، اور صنعاء کی گلیوں میں پھرنے لگے، وہ کہہ رہے تھے، اے اہل یمن! مجھے چھوڑو! مجھے تمہارے پڑوس کی ضرورت نہیں، وہ برے دن ہیں جو تمہارے پڑوس میں گزرے، مجھ سے میرے حبیب محمد صلی اللہ علیہ وسلم جدا ہو گئے ہیں، پھر صبح کے وقت سواری پر بیٹھے اور قسم کھائی کہ سوائے نماز کے اوقات کے اس سے نہ اتریں گے یہاں تک کہ مدینہ جا پہنچیں۔","",{"fn":"(1) اسد الغابة (۷۱۴۷)، تجرید (۲۹۱/۲)\n(2) اتحاف السادة المتقين (۲۶۱/۶)\n(3) اسد الغابة (۷۱۴۸)، تجرید (۲۹۲/۲)"}],[11507,"§۱۱۵۴۶ ۔ العوراء بنت ابی جھل\nیہ وہی ہیں جنہیں سیدنا علی رضی اللہ عنہ نے نکاح کا پیغام دیا، حکیم ترمذی فرماتے ہیں: جزء ثانی میں ابو رزق ہمدانی کی حدیث میں ان کا ذکر پہلے گزر چکا ہے کہ ان کا نام جوہریہ ہے، ہو سکتا ہے عوراء ان کا لقب ہو۔"],[11508,"§۱۱۵۴۷ ۔ غویش\nنبی کریم صلی اللہ علیہ وسلم نے ام المؤمنین سیدہ عائشہ رضی اللہ عنہا کو اس نام سے مخاطب کیا تھا۔ طبرانی نے عشرہ میں اسے مسلم بن یسار کے طریق سے نقل کیا ہے، فرماتے ہیں: مجھے یہ بات پہنچی ہے کہ نبی کریم صلی اللہ علیہ وسلم سیدہ عائشہ رضی اللہ عنہا کے پاس تشریف لائے اور فرمایا: “اے غویش! کیا وجہ ہے کہ تمہارا چہرہ بہت روشن ہے۔”۔۔۔۔۔ الحديث"],[11509,"§۱۱۵۴۸ ۔ غُوَیمرہ بنت غُوَیم\n(1) بن ساعدہ انصاریہ: ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) التجرید (۱۹۲)"}],[11510,"§۱۱۵۴۹ ۔ غَیساء بنت الحارث الانصاریہ\n(1) انس بن فضالہ کی زوجہ ہیں: ابن سعد(2) نے ان کا ذکر کیا ہے۔ تجرید میں بھی غویمرہ کے بعد ان کا ذکر ہے۔","",{"fn":"(1) تجرید (۲۹۲/۲)\n(2) الطبقات الکبریٰ (۲۵۰/۸)"}],[11511,"§۱۱۵۵۰ ۔ عائشہ بنت سعد\nاور عائشہ بنت شیبہ اور عائشہ بنت معاویہ، عبیدہ بنت صعصعہ بن ناجیہ تمیمیہ، فرزدق کی پھوپھی ہیں، ام حمزہ ہیں، زبرقان بن بدر کی زوجہ ہیں، کتاب ابو الفرج میں حطیہ کے سوانح میں ان کا ذکر ہے، یہ وہی ہیں کہ زبرقان نے حطیہ کو ان کے فروکش ہونے کو کہا تھا یہاں تک کہ وہ سفر سے واپس آ جائیں۔ لیکن انہوں نے کوتاہی کی جو حطیہ کی طرف سے زبرقان کی ہجو کا سبب بنا۔"],[11512,"§۱۱۵۵۱ ۔ عمرہ بنت درید\nبن صمہ: فرماتی ہیں: انہوں نے اپنے والد کا مرثیہ کہا: ربیعہ بن رفیع جو ابن دغنیہ کے نام سے مشہور ہے اس نے انہیں قتل کیا۔ اللہ تعالیٰ میری طرف سے بنی سلیم کو ان کے کیے کا بدلہ دے کہ یہ اپنے والدین کے نافرمان بیٹے ہیں۔ اور ملاقات کے وقت جب ہم ان سے قصاص لیں تو ان کے بہترین لوگوں کا خون پلائے۔(1)","",{"fn":"(1) الأغانی (۳۳۲/۱۰)"}],[11513,"§۱۱۵۵۲ ۔ عائشہ بنت عجرہ\n(1) اسد الغابہ میں یہ نام عائشہ بنت عجر دکھا ہے۔ ہم وہیں سے نقل کرتے ہیں۔ یحییٰ بن معین کا قول ہے کہ صاحب قیاس و فقہ ابوحنیفہ نے عائشہ سے سنا فرماتی ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: زمین میں اللہ تعالیٰ کا سب سے بکثرت لشکر ٹڈیاں ہیں (جو فصلیں کھاتی ہیں جن کی لمبائی تقریباً تین انچ سے پانچ انچ تک ہوتی ہے، جسے “ٹڈی دل” بھی کہا جاتا ہے، اس سے مراد گھروں میں پائی جانے والی زہریلی ٹڈیاں نہیں ہیں) نہ میں انہیں کھاتا ہوں اور نہ حرام قرار دیتا ہوں۔ ان کی روایت بواسطہ ابوحنیفہ عثمان بن راشد بواسطہ عائشہ بنت عجر بحوالہ ابن عباس رضی اللہ عنہما نقل کی گئی ہے۔ اکثر علماء نے تابعات میں ان کا ذکر کیا ہے۔ ابوموسیٰ نے ان کا تذکرہ کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۰۹۰)"}],[11514,"§۱۱۵۵۳ ۔ غاثنہ\n(1) ابن مندہ کا قول ہے: ابن وہب نے بحوالہ عثمان بن عطاء خراسانی انہوں نے اپنے والد سے نقل کیا ہے کہ وہ نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں اور کہنے لگیں: میری والدہ وفات پا گئی ہیں اور انہوں نے کعبے کی طرف پیدل جانے کی نذر مانی تھی، آپ صلی اللہ علیہ وسلم نے فرمایا: “ان کی طرف سے نذر پوری کرو۔”(2)","",{"fn":"(1) اسد الغابۃ (۷۱۴۹) الاستيعاب (۳۴۹۳) تجرید (۲۹۲/۲)\n(2) اسد الغابۃ (۳۵۶/۵)"}],[11515,"§۱۱۵۵۴ ۔ غزیلہ\nبعض کا قول ہے: غزیہ، ام شریک ہیں اور اپنی کنیت سے معروف ہیں، کنیتوں میں ان کے حالات آئیں گے، ابن سعد رحمہ اللہ نے بحوالہ واقدی رحمہ اللہ، سلیمان بن یسار سے مرسلاً نقل کیا ہے، فرماتے ہیں: جب نبی کریم صلی اللہ علیہ وسلم نے کندیہ سے نکاح کیا، عامریہ خواتین کے ہاں نکاح کا پیغام بھیجا، ام شریک غزیہ بنت جابر نے اپنے آپ کو آپ صلی اللہ علیہ وسلم کو ہبہ کر دیا، آپ صلی اللہ علیہ وسلم کی ازواج کہنے لگیں: اگر آپ صلی اللہ علیہ وسلم نے خاندان سے باہر شادی کی تو آپ صلی اللہ علیہ وسلم کو ہماری حاجت نہیں ہو گی۔۔۔۔۔ الحديث"],[11516,"§۱۱۵۵۵ ۔ غفیرہ\n(1) بنت رباح، سیدنا بلال رضی اللہ عنہ (جو مؤذن ہیں) اور ان کے بھائی خالد کی بہن ہیں۔ مستغفری نے ان کا ذکر کیا ہے اور فرمایا: وہ دو بھائی اور ایک بہن ہے، یہ بخاری کا قول ہے، طحاوی میں اسناد کے درمیان ہے: بحوالہ عمیر مولیٰ غفیرہ بنت رباح جو سیدنا بلال رضی اللہ عنہ کی بہن ہیں۔","",{"fn":"(1) اسد الغابۃ (۷۱۵۱)، تجرید (۲۹۲)"}],[11517,"§۱۱۵۵۶ ۔ غفیرہ\nعنقودہ میں گزر چکی ہیں۔"],[11518,"§۱۱۵۵۷ ۔ غفیلہ\nاسی طرح ہیں، لیکن راء کے بدلے لام کے ساتھ، عین مہملہ میں ان کا ذکر گزر چکا ہے۔"],[11519,"§۱۱۵۵۸ ۔ الغمیصاء بنت ملحان الانصاریہ\n(1) بعض کا قول ہے: ام سلیم، سیدنا انس رضی اللہ عنہ کی والدہ ہیں۔ وہ اپنی کنیت سے مشہور ہیں: امام احمد(2) نے اپنی مسند میں فرمایا: ہم سے یحییٰ قطان نے، وہ فرماتے ہیں: ہم سے حمید نے بحوالہ انس رضی اللہ عنہ انہوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کیا، فرمایا: میں جنت میں داخل ہوا تو میں نے چلنے کی آواز سنی، میں نے کہا: یہ کون ہے، تو فرشتے نے کہا: “غمیصاء بنت ملحان”۔ میں کہتا ہوں: حرف راء میں دوسری سند سے بحوالہ انس یہ گزر چکا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۱۵۴)، تجرید (۲۹۲/۲)\n(2) مسند احمد (۱۲۵/۳)"}],[11520,"§۱۱۵۵۹ ۔ الغمیصاء\n(1) یا رمیصاء، عمرو بن حزم کی زوجہ ہیں: ابو نعیم نے حماد بن سلمہ کے طریق سے بحوالہ ہشام بن عروہ، انہوں نے اپنے والد سے، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے نقل کیا ہے: کہ عمرو بن حزم نے غمیصاء کو طلاق دی، ان سے ایک شخص نے نکاح کیا اور مس کرنے سے پہلے طلاق دے دی، وہ نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں اور پوچھا کہ کیا وہ پہلے شوہر کی طرف لوٹ سکتی ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: یہاں تک کہ دوسرا ان کا........(2) الحدیث۔ ابو موسیٰ فرماتے ہیں: یہ ام سلیم کے علاوہ کوئی اور ہیں: ابن عباس رضی اللہ عنہما نے ابوموسیٰ سے حدیث روایت کی، فرمایا: غمیصاء یا رمیصاء ہیں، اور ان کے شوہر کا نام نہیں لیا۔(3) ابن مندہ نے ام سلیم کے سوانح میں حدیث نقل کی ہے، ابن اثیر فرماتے ہیں: ابوموسیٰ کا قول درست ہے۔ میں کہتا ہوں: حرف راء میں سیدنا ابن عباس رضی اللہ عنہما کی حدیث گزر چکی ہے۔","",{"fn":"(1) اسد الغابۃ (۷۱۵۵)، تجرید (۲۹۲/۲)\n(2) مسند احمد (۳۷/۶) المعجم الکبیر (۸۶۹/۲۴)\n(3) مسند احمد (۲۱۴/۱) مسند ابویعلیٰ (۶۷۱۸) مجمع الزوائد (۳۴۰/۴)"}],[11521,"§۱۱۵۶۰ ۔ غنیہ بنت ابی اہاب\nیہ ام یحییٰ ہیں، جن سے عقبہ بن حارث نوفلی نے نکاح کیا، ان سے ایک حبشی باندی نے کہا، میں نے تم دونوں کو دودھ پلایا ہے، جیسا کہ کنیتوں میں آئے گا۔"],[11522,"§۱۱۵۶۱ ۔ فاختہ بنت الاسود\n(1) بن مطلب بن اسد بن عبدالعزیٰ قریشیہ اسدیہ: صفوان بن امیہ بن خلف کی زوجہ تھیں، اپنے باپ کے بعد ان سے نکاح کیا، اسلام نے ان دونوں کے درمیان جدائی کرا دی۔ مستغفری نے محمد بن ثور کے طریق سے بحوالہ ابن جریج نقل کیا ہے، فرمایا: اسلام نے چار عورتوں اور ان کے خاوند کے بیٹوں کے درمیان جدائی کرائی، پھر ان کا ذکر کیا۔(2)","",{"fn":"(1) اسد الغابۃ (۷۱۵۶)، تجرید (۲۹۲/۲)\n(2) طبری فی تفسیرہ (۱۳۳/۸)، تفسیر ابن کثیر (۲۱۴/۱۲)"}],[11523,"§۱۱۵۶۲ ۔ فاختہ بنت خارجہ\nبن زید بن ابو زہیر انصاریہ، ابوبکر صدیق کی زوجہ ہیں: دار قطنی نے کتاب الاخوہ میں ان کا نام لیا ہے۔ یہ ابوبکر رضی اللہ عنہ کے اس قول سے مراد ہیں جو انہوں نے اپنی وفات کے وقت سیدہ عائشہ رضی اللہ عنہا سے فرمایا: بطن والی خارجہ کی بیٹی ہے۔ بعض کا قول ہے: کہ ان کا نام حبیبہ ہے۔"],[11524,"§۱۱۵۶۳ ۔ فاختہ بنت ابی احیحہ\n(1) سعد بن العاص بن امیہ، ابوالعاص بن ربیع کی زوجہ ہیں۔ نبی کریم صلی اللہ علیہ وسلم کی صاحبزادی سیدہ زینب رضی اللہ عنہا کے بعد ان سے نکاح کیا، جس سے ان کی بیٹی مریم پیدا ہوئیں، زبیر نے ان کا ذکر کیا ہے۔","",{"fn":"(1) تجرید (۲۹۲/۲)"}],[11525,"§۱۱۵۶۴ ۔ فاختہ بنت ابی طالب\nبن عبد المطلب بن ہاشم ہاشمیہ، ام ہانی ہیں، سیدنا علی رضی اللہ عنہ کی بہن ہیں اور اپنی کنیت سے معروف ہیں، بعض کا قول ہے، ان کا نام ہند ہے، پہلا نام مشہور ہے۔"],[11526,"§۱۱۵۶۵ ۔ فاختہ بنت قرظہ\nبن عبد عمرو بن نوفل بن عبد مناف قرشیہ، نوفلیہ، معاویہ بن ابو سفیان کی زوجہ ہیں، ان کے والد کا صحابہ میں تذکرہ نہیں، وہ جاہلیت میں فوت ہوئے، ہونا تو یہ چاہیے تھا کہ ان کا تذکرہ عہد نبوی صلی اللہ علیہ وسلم میں ہوتا اور ان کے قریبی بچوں کو شرف صحابیت حاصل ہوتا۔ زبیر بن بکار نے نسبت میں ذکر کیا ہے کہ امیر معاویہ رضی اللہ عنہ نے کنود بن قرظہ مذکور سے نکاح کیا تھا پھر ان کی بہن فاختہ سے نکاح کیا۔ امیر معاویہ کے سوانح میں ان کے والد قرظہ کے کئی واقعات مذکور ہیں ان میں سے ایک یہ کہ انہوں نے ان کے ساتھ غزوہ قبرس میں شرکت کی، یہ صحیح میں سیدہ ام حرام کی حدیث میں ہے جو سیدنا انس رضی اللہ عنہ کی خالہ ہیں، مجھے معلوم نہیں یہ دونوں بہنوں میں سے کون سی ہیں۔"],[11527,"§۱۱۵۶۶ ۔ فاختہ بنت عمرو الزہریہ\n(1) نبی کریم صلی اللہ علیہ وسلم کی خالہ ہیں: طبرانی رحمہ اللہ نے عبدالرحمن بن عثمان وقاصی کے طریق سے بحوالہ ابن المنکدر، انہوں نے سیدنا جابر رضی اللہ عنہ سے روایت کیا ہے: فرماتے ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: میں نے اپنی خالہ فاختہ بنت عمرو کو ایک خدمت گار لڑکا ہبہ کرتے ہوئے کہا کہ اسے قصاب، سنار اور سینگی لگانے والا نہ بنانا۔(2) وقاصی ضعیف راوی ہے۔","",{"fn":"(1) اسد الغابۃ (۷۱۵۸)، تجرید (۲۹۲/۲)\n(2) المعجم الکبیر (۱۰۷۳/۲۴) مجمع الزوائد (۹۳/۴)"}],[11528,"§۱۱۵۶۷ ۔ فاختہ بنت غزوان\nعقبہ کی بہن ہیں: جن کے سوانح میں ان کا نسب گزر چکا ہے، ہجرت کرنے والی صحابیات میں سے ہیں۔"],[11529,"§۱۱۵۶۸ ۔ فاختہ بنت الولید\n(1) بن مغیرہ مخزومیہ، خالد بن ولید کی بہن ہیں، ان کے سوانح(2) میں ان کا نسب گزر چکا ہے، صفوان بن امیہ کی زوجہ ہیں، فتح کے دن اسلام لائیں اور بیعت کی، ابو عمر(3) کا قول ہے: اپنے شوہر کے اسلام لانے سے ایک ماہ پہلے اسلام لائیں، یہ داؤد بن حصین کا قول ہے، ابن مندہ فرماتے ہیں: ان کا ذکر ہے لیکن حدیث مروی نہیں۔ ابو نعیم نے ابراہیم بن سعد کے طریق سے بحوالہ ابن اسحاق انہوں نے عبدالعزیز بن عبدالرحمن امامی سے، انہوں نے زہری سے نقل کیا ہے، فرماتے ہیں: سیدہ فاختہ بنت ولید صفوان بن امیہ کی زوجہ تھیں، اور ام حکیم بنت حارث عکرمہ کی زوجہ تھیں، فتح کے دن(4) دونوں اسلام لائیں۔","",{"fn":"(1) اسد الغابۃ (۷۵/۹)، الاستيعاب (۳۴۹۵)، تجرید (۲۹۳/۲)\n(2) مجمع الزوائد (۹۳/۴)\n(3) الاستيعاب (۱۸۸۹/۴)\n(4) اسد الغابۃ (۳۵۹/۵)"}],[11530,"§۱۱۵۶۹ ۔ فارعہ بنت ابی امامہ\n(1) سعد بن زرارہ انصاریہ، ان کے والد کے سوانح میں ان کا نسب گزر چکا ہے، بعض کا قول ہے: ان کا نام فریعہ ہے، ان کی بیٹی زینب بنت نبط کے سوانح میں ان کا ذکر گزر چکا ہے، جو انس بن مالک کی زوجہ ہیں۔ ابو عمر(2) فرماتے ہیں: ابو امامہ نے اپنی بیٹیوں فارعہ، حبیبہ اور کبشہ کو نبی کریم صلی اللہ علیہ وسلم کے پاس جانے کی وصیت کی، رسول اللہ صلی اللہ علیہ وسلم نے فارعہ کی شادی نبیط بن جابر سے جو بنو مالک بن نجار سے ہیں، کر دی۔ ابن مندہ نے ابراہیم بن محمد بن ابو یحییٰ سے بحوالہ محمد بن عمارہ بن عمرو بن حزم نقل کیا ہے، کہ انہوں نے زینب بنت نبیط سے جو سیدنا انس رضی اللہ عنہ کی زوجہ ہیں سنا، وہ اپنی والدہ فریعہ بنت ابو امامہ سے روایت کرتی ہیں، فرماتی ہیں: نبی کریم صلی اللہ علیہ وسلم کے پاس سونے کے زیور، رعاث آئے، آپ صلی اللہ علیہ وسلم نے میری دو بہنوں حبیبہ اور کبشہ کو اس میں سے پہنائے، اور اس سے زکوۃ نہیں لی گئی، ابن سعد(3) فرماتے ہیں: ان کی والدہ عمیرہ بنت سھل ہیں، سیدہ فریعہ سیدنا اسعد بن زرارہ کی بیٹیوں میں بڑی تھیں جب بڑی ہوئیں، نبیط بن جابر نے انہیں نکاح کا پیغام دیا، جب ان کی رخصتی ہوئی تو رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا: “کہو ہم تمہارے پاس آئے تم یتیم پر سلامتی بھیجو، ہم تمہارے اوپر سلامتی بھیجتے ہیں۔” سیدنا نبیط کا ان سے بیٹا عبدالملک پیدا ہوا۔ رسول اللہ صلی اللہ علیہ وسلم نے اس کا نام رکھا اور برکت کی دعا دی، سیدہ فریعہ بیعت کرنے والی صحابیات میں سے ہیں، ابن اثیر(4) نے معافی بن عمران کے طریق سے نقل کیا ہے، کہ انہوں نے اپنی تاریخ میں بحوالہ ابو عقیل جو نھیہ والے ہیں، انہوں نے نہیہ سے بحوالہ سیدہ عائشہ رضی اللہ عنہا روایت کیا ہے، فرماتی ہیں: ہم نے انصار میں سے ایک یتیمہ لڑکی کی رخصتی کی، جب ہم واپس آئے تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “تم نے کیا؟” ہم نے کہا: ہم نے سپرد کیا اور لوٹ آئے، آپ صلی اللہ علیہ وسلم نے فرمایا: “انصار کو ترنم پسند ہے، اے عائشہ، تم نے یہ کیوں نہیں کیا: ہم تمہارے پاس آئے، ہم تمہارے پاس آئے، ہم پر اور تم پر سلامتی ہو۔”(5) میں کہتا ہوں: یہ فریعہ فارعہ بنت اسعد بن زرارہ ہیں۔","",{"fn":"(1) اسد الغابۃ (۷۱۶۰)، الاستيعاب (۳۴۹۶) تجرید (۲۹۳/۲)\n(2) الاستيعاب (۱۸۸۹/۴)\n(3) الطبقات (۳۲۲/۸)\n(4) اسد الغابۃ (۳۵۹/۵)\n(5) ابن ماجہ (۱۹۰۰)، مسند احمد (۷۷/۴) (۷۸) مجمع الزوائد (۲۸۹/۴) زبیدی (۴۹۳/۶)"}],[11531,"§۱۱۵۷۰ ۔ فارعہ بنت ثابت\nبن منذر بن حرام انصاریہ، بنو نجار سے ہیں سیدنا حسان بن ثابت رضی اللہ عنہ جو شاعر رسول اللہ صلی اللہ علیہ وسلم ہیں، ان کی بہن ہیں، ابو حسن مدائنی نے ذکر کیا ہے کہ طویس نے عبد اللہ بن جعفر کے سامنے ایک شعر گنگنا کر کہا:............ یہ شعر کس کا ہے؟ کہنے لگے: فارعہ جو حسان کی بہن ہیں، اور عبدالرحمن بن حارث بن ہشام کے بارے میں ہے۔ میں کہتا ہوں: ان کے والد جاہلیت میں وفات پا گئے تھے اور عبدالرحمن بن حارث نبی کریم صلی اللہ علیہ وسلم کے زمانے میں کمسن تھے جیسا کہ ان کے سوانح میں گزر چکا ہے۔ لہذا ان کے متعلق تو شعر نہیں کہے جا سکتے ہاں جب وہ بالغ ہو گئے ہوں، اس لئے فارعہ اس قسم میں شامل ہے۔"],[11532,"§۱۱۵۷۱ ۔ فارعہ بنت زرارہ\n(1) بن عدی بن حرام انصاریہ، بنو مالک بن نجار سے ہیں، ابو موسیٰ نے یہ ذیل میں کہا، اسی طرح ابن اثیر(2) کا قول ہے۔ ذیل میں جو خط صریفینی میں ہے میں نے انہیں نہیں دیکھا، ممکن ہے جو ان سے پہلے ہیں وہ ان کے دادا کی طرف منسوب ہوں پھر مجھے معلوم ہوا کہ وہ ان کی پھوپھی ہیں۔ ابن سعد(3) کا قول ہے: الفارعہ، وہ فریعہ بنت زرارہ بن عدس بن عبید بن ثعلبہ بن غنم بن مالک بن نجار ہیں، ابو امامہ جو اسعد بن زرارہ ہیں ان کی سگی بہن ہیں، ان سے قیس بن عھد بن قیس بن ثعلبہ نے نکاح کیا، اسلام لائیں اور بیعت کی۔","",{"fn":"(1) اسد الغابۃ (۷۱۶۱)، الاستيعاب (۷۱۶۹)\n(2) اسد الغابۃ (۳۵۹/۵)\n(3) الطبقات (۳۲۱/۸)"}],[11533,"§۱۱۵۷۲ ۔ فارعہ بنت ابی سفیان\n(1) بن حرب بن امیہ امویہ: مستغفری نے ان کا ذکر کیا ہے، اور انس بن بکیر کے طریق سے بحوالہ ابن اسحاق نقل کیا ہے۔ فرماتے ہیں: سب سے پہلے حبشہ کی طرف ہجرت کرنے والے عبداللہ بن جحش ہیں جو بنو عبد شمس کے حلیف ہیں، انہوں نے اپنے گھر والوں اور بہن کے ساتھ ہجرت کی، ان کے پاس فارعہ بنت ابو سفیان بن حرب تھیں۔(2)","",{"fn":"(1) اسد الغابۃ (۷۱۶۲)، الاستيعاب (۷۱۷۰)، تجرید (۲۹۳/۲)\n(2) المعجم الکبیر (۲۱/۹)، السیرۃ النبویۃ (۸۶/۲)"}],[11534,"§۱۱۵۷۳ ۔ الفارعہ بنت ابی الصلت\n(1) امیہ بن ابو الصلت کی بہن ہیں، جو مشہور شاعر ہے، ابو عمر کا قول ہے، فتح طائف(2) کے بعد نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں وہ بڑی عقلمند پاکدامن اور حسین و جمیل خاتون تھیں، ان کے آنے سے آپ علیہ السلام خوش ہوتے تھے ایک دن ان سے فرمایا: کیا تمہیں اپنے بھائی کے کوئی اشعار یاد ہیں؟ چنانچہ انہوں نے ان کے بارے میں اور جو کچھ ان کے متعلق دیکھا، اور ان کے پیٹ چاک ہونے کا قصہ آپ علیہ السلام سے بیان کیا کہ وہ سو رہا تھا کہ اس کا دل نکال کر دوبارہ اس کے سینہ میں رکھ دیا گیا اور اس کے وہ اشعار سنائے جن کا مطلع یہ ہے۔ “میری پریشانیاں رات کے وقت گردش کرتی ہیں میں اپنی آنکھوں کو روکتا ہوں لیکن ان کے آنسو پہلے بہہ پڑتے ہیں۔ دل کو چاہے جتنی جینے کی آرزو ہو تھوڑا بہت جی بھی لے موت اس کے پیچھے لگی ہوئی ہے۔” یہ تقریباً تیرہ(۱۳) اشعار ہیں جن میں وہ کہتے ہیں: “جو شخص اپنی موت سے گریزاں ہے وہ کسی نہ کسی دھوکے سے اسے جا ملے گا۔ جو جوانی میں نہ مرا بڑھاپے میں جا مرے گا۔ موت ایسا پیالہ ہے جسے ہر شخص چکھنے والا ہے۔” اس نے معاینہ کے وقت یہ اشعار کہے تھے: “ہر زندگی خواہ اس کا دن لمبا ہو جائے ایک نہ ایک دن ختم ہونے والی ہے۔ کاش! جو کچھ میں نے دیکھا اس سے پہلے میں پہاڑوں کی چوٹیوں پر بکریاں چرا رہا ہوتا۔” رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا: تمہارے بھائی کی مثال اس شخص کی سی ہے “اس شخص کا حال بیان کرو جسے ہم نے اپنی آیات کا علم دیا پھر وہ ان سے نکل گیا۔”(3) ابو عمر(4) فرماتے ہیں: میں نے اسے مختصر بیان کیا ہے اس کے چند نکات پر اکتفا کیا ہے پھر بسند وہیمہ بن موسیٰ بواسطہ سلمہ بن فضل، ابن اسحاق، ابن شہاب بحوالہ سعید بن المسیب روایت کی ہے کہ فارعہ آئیں۔ پھر مکمل روایت ذکر کی۔ میں کہتا ہوں: یہ قصہ ابو نعیم نے بطریق ثعلب بحوالہ ابن الاعرابی نقل کیا ہے کہ ابن اسحاق نے اسی سند سے اسی مفہوم کی روایت بیان کی ہے۔ ابن ابو عاصم(5) اور ابن مندہ نے اسے ابراہیم بن محمد بن یحییٰ سجری کے طریق سے بحوالہ اپنے والد، انہوں نے ابن اسحاق سے انہوں نے زہری سے، انہوں نے عبید اللہ بن عبداللہ سے، انہوں نے ابن اسحاق سے اسے نقل کیا ہے: کہ فارعہ بنت ابی الصلت ثقفی نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں تو آپ صلی اللہ علیہ وسلم نے ان سے ان کے والد اور بھائی کے بارے میں دریافت فرمایا: کہنے لگیں: میرا بھائی سفر سے ہمارے پاس آیا، پھر چار پائی پر سو گیا، دو پرندے آئے ان میں سے ایک اس کے سینے پر گرا، تو اس کا سینے سے سرین تک جسم چاک ہو گیا پھر اس کی موت کا طویل قصہ ذکر کیا۔ میں کہتا ہوں: دونوں سندوں میں جو ابن اسحاق رحمہ اللہ تک پہنچتی ہے ضعیف ہے اور کتاب مکہ میں فاکہی نے طویل قصہ کلبی کے طریق سے بحوالہ ابو صالح، انہوں نے ابن عباس سے نقل کیا ہے۔ ثعلبی نے اسے اپنی تفسیر میں نقل کیا ہے اس میں ہے: انہوں نے نبی کریم صلی اللہ علیہ وسلم کے سامنے ان کے کئی قصائد پڑھے جس میں ان کے ایمان اور قیامت کی وضاحت ہوتی ہے، ایک قصیدہ میں ہے: “تمام لوگوں کو حساب کے لئے ٹھہرایا جائے گا، ان میں سے بدبخت کو عذاب دیا جائے گا اور نیک بخت ہوں گے۔” ایک قصیدہ میں ہے: “اے ہمارے رب! تیرے لئے تمام تعریف نعمتیں اور فضل ہے۔ بزرگی میں تجھ سے بڑھ کر اور کوئی نہیں، آسمان کے عرش کا مالک ہے، نگہبان ہے، اس کی عزت کے لئے چہرے جھکتے اور سجدہ کرتے ہیں۔” ایک قصیدہ میں ہے: “جس دن ہم رحمن کے دربار میں حاضر ہوں گے، وہ رحیم ذات ہے، اس کے وعدہ کا وقت آنے والا ہے۔ اگر جرائم کی وجہ سے میرا مواخذہ ہوا تو مجھے سخت عذاب کا سامنا کرنا پڑے گا۔ اے میرے رب! اگر تو مجھ سے درگزر کرے تو میرا گمان بھی عافیت والا ہے، اور اگر تو مجھے عذاب دینا چاہے تو کسی بری کو تو نے عذاب نہیں دیا۔” آپ صلی اللہ علیہ وسلم نے ان سے فرمایا: اس کے شعروں سے تو ایمان کا پتہ چلتا ہے لیکن اس کا دل کافر تھا، اس کے بارے میں یہ آیت نازل ہوئی: ان کے سامنے اس شخص کا حال بیان کرو جسے ہم نے اپنی آیات کا علم عطا کیا تھا لیکن وہ ان کی پابندی سے نکل بھاگا۔۔۔۔۔ الآیۃ","",{"fn":"(1) اسد الغابۃ (۷۱۶۳)، الاستيعاب (۳۴۹۷)، تجرید (۲۹۳/۲)\n(2) الاستيعاب (۱۸۸۹/۴)\n(3) سورۃ الاعراف ۱۷۵\n(4) استيعاب (۱۸۹۰/۴)\n(5) الاحاد والمثانی (۲۴۷/۶)"}],[11535,"§۱۱۵۷۴ ۔ فارعہ بنت عبد الرحمن الخثعمیہ\n(1) صحابہ میں ان کا تذکرہ ہے، ان سے سرمی بن عبد الرحمن نے روایت کی، استیعاب میں اسی طرح مذکور ہے۔","",{"fn":"(1) اسد الغابۃ (۷۱۶۴)، الاستيعاب (۳۴۹۸)، تجرید (۲۹۳/۲)"}],[11536,"§۱۱۵۷۵ ۔ فارعہ بنت عتبہ\nبن عبد شمس عبشمیہ، ہند کی بہن اور معاویہ کی خالہ ہیں، حبیب بن عمرو بن حمہ دوسی کی زوجہ تھیں، بلاذری نے ان کا ذکر کیا ہے۔"],[11537,"§۱۱۵۷۶ ۔ فارعہ بنت مالک\nسنان خدریہ: فریعہ کے سوانح میں ان کا ذکر آئے گا۔"],[11538,"§۱۱۵۷۷ ۔ فارعہ الجنیہ\nحمزہ بن یوسف جرجانی نے تاریخ جرجان میں ان کا ذکر کیا ہے، فرماتے ہیں: ہمیں ابو احمد بن عدی نے بتایا، وہ فرماتے ہیں کہ ہمیں عبد المؤمن بن احمد نے، وہ فرماتے ہیں: ہمیں جعفر بن حکم نے، وہ فرماتے ہیں: ہمیں نصیعہ بن عبد اللہ بن لہیعہ نے بحوالہ اپنے والد بیان کیا، انہوں نے ابو زبیر سے، انہوں نے سیدنا جابر رضی اللہ عنہ سے نقل کیا ہے: کہ ایک جنیہ خاتون نبی کریم صلی اللہ علیہ وسلم کے پاس اپنی قوم کی عورتوں کے ساتھ آتی تھی، ایک مرتبہ انہیں تاخیر ہو گئی تو تھوڑی دیر بعد وہ آ گئیں، آپ صلی اللہ علیہ وسلم نے فرمایا: تمہیں کس وجہ سے تاخیر ہوئی؟ کہنے لگیں: ہند کی سرزمین میں ہماری فوتگی ہو گئی میں اس کی تعزیت کرنے گئی تھی، میں نے اپنے راستے میں ابلیس کو ایک چٹان پر نماز پڑھتے ہوئے دیکھا میں نے کہا: تمہیں حضرت آدم علیہ السلام کو گمراہ کرنے پر کس چیز نے آمادہ کیا؟ ابلیس نے کہا: جاؤ اپنا کام کرو، میں نے کہا: نماز اور تم! اس نے کہا: ہاں اے فارعہ: ایک بندے کی بیٹی، میں اپنے رب سے امید رکھتا ہوں کہ جب وہ اپنی قسم پوری کرے گا تو مجھے بخش دے گا، اس سند میں نامعلوم راوی ہیں، ابن جوزی نے موضوعات میں اسے نقل کیا ہے۔"],[11539,"§۱۱۵۷۸ ۔ فاضلہ\n(1) عبد اللہ بن انیس کی زوجہ ہیں، ان کے نام میں اختلاف ہے، ان کا ذکر گزر چکا ہے، ابن مندہ نے بھی ان کا ذکر کیا ہے۔ ابو عمر(2) فرماتے ہیں: فاضلہ انصاریہ، عبداللہ بن انیس جہنی کی زوجہ ہیں، اہل مدینہ کے ہاں ان کی حدیث ہے۔ فرماتی ہیں: نبی کریم صلی اللہ علیہ وسلم نے ہمیں خطبہ دیا اور صدقہ کرنے کی ترغیب دی۔(3) میں کہتا ہوں: حسن بن سفیان نے اپنی مسند میں اسے نقل کیا ہے، موسیٰ بن عبیدہ ربذی کے طریق سے جو ضعیف راوی ہیں، بحوالہ ان کے بھائی محمد بن عبیدہ، انہوں نے اپنے بھائی عبداللہ بن عبیدہ سے، انہوں نے یحییٰ بن عبد اللہ بن کعب بن مالک سے، انہوں نے اپنی والدہ سے اور وہ عبد اللہ بن انیس جہنی کی بیٹی ہیں۔ انہوں نے اپنی والدہ سے جو فاضلہ انصاریہ ہیں، فرماتی ہیں: رسول اللہ صلی اللہ علیہ وسلم نے ہمیں خطبہ دیا، اور صدقہ کی ترغیب دی، میں نے آپ صلی اللہ علیہ وسلم کے پاس اپنے زیور بھیجے، اور کہا: وہ اللہ عزوجل کی راہ میں صدقہ ہیں، آپ صلی اللہ علیہ وسلم نے اسے واپس کر دیا اور فرمایا: ”میں عورت کا صدقہ اس کے شوہر کی اجازت سے قبول کرتا ہوں“ میں نے اسے اپنے شوہر کے ساتھ بھیجا، انہوں نے کہا: یا رسول اللہ صلی اللہ علیہ وسلم کیا یہ زیور اس کا ہے، اور والد کی وراثت سے حاصل ہوا ہے، آپ صلی اللہ علیہ وسلم نے اسے قبول کر لیا۔","",{"fn":"(1) اسد الغابۃ (۷۱۶۷)، الاستيعاب (۳۴۹۹)، تجرید (۲۹۳/۲)\n(2) الاستيعاب (۱۸۹۰/۴)\n(3) جامع المسانید والسنن (۷/۱۶)"}],[11540,"§۱۱۵۷۹ ۔ فاطمہ الزھراء\n(1) امام المتقین رسول اللہ صلی اللہ علیہ وسلم کی صاحبزادی، جن کا اسم گرامی محمد بن عبداللہ بن عبدالمطلب بن ہاشم ہاشمی صلی اللہ علیہ وسلم ہے۔ ابن فتحون رحمہ اللہ نے کسی سے ب ساکن اس کے بعد نون نقل کیا ہے، جو غلط ہے، لقب زہراء تھا، آپ رضی اللہ عنہا اپنے والد سے، آپ سے آپ کے دونوں بیٹے، خاوند، سیدہ عائشہ، ام سلمہ، سلمیٰ، ام رافع اور سیدنا انس رضی اللہ عنہم روایت کرتے ہیں، فاطمہ بنت حسین آپ رضی اللہ عنہا سے مرسل روایت کرتی ہیں، عبدالرزاق بحوالہ ابن جریج لکھتے ہیں: مجھ سے کئی لوگوں نے بیان کیا کہ سیدہ فاطمہ رضی اللہ عنہا نبی کریم صلی اللہ علیہ وسلم کی سب سے چھوٹی اور آپ کو سب سے پیاری بیٹی تھیں۔ ابو عمر(2) لکھتے ہیں: کہ کم عمر ہونے میں اختلاف ہے۔ یقینی بات یہ ہے کہ سب سے بڑی سیدہ زینب رضی اللہ عنہا تھیں، ان سے چھوٹی رقیہ رضی اللہ عنہا، ان سے چھوٹی ام کلثوم رضی اللہ عنہا پھر سیدہ فاطمہ رضی اللہ عنہا تھیں، جس کی تھوڑی بہت تفصیل سیدہ رقیہ رضی اللہ عنہا کے حالات میں گزر چکی ہے، آپ رضی اللہ عنہا کے سن ولادت میں اختلاف ہے۔ چنانچہ واقدی، ابو جعفر باقر کے طریق سے روایت کرتے ہیں، فرمایا: کہ سیدنا عباس رضی اللہ عنہ کا قول ہے کہ جن ایام میں کعبہ کی تعمیر ہو رہی تھی، اسی سال سیدہ فاطمہ رضی اللہ عنہا پیدا ہوئیں، اور نبی علیہ الصلوۃ والسلام کی عمر پینتیس(۳۵) سال تھی، اسی پر مدائنی نے اعتماد کیا ہے۔ ابو عمر(3) عبید اللہ بن محمد بن سلیمان بن جعفر سے روایت کرتے ہیں: کہ سیدہ فاطمہ رضی اللہ عنہا نبی صلی اللہ علیہ وسلم کی ولادت کے اکتالیسویں برس پیدا ہوئیں، بعثت سے کچھ ہی عرصہ پہلے تقریباً سال یا سال سے زیادہ عرصہ میں پیدا ہوئیں، سیدہ عائشہ رضی اللہ عنہا سے پانچ برس بڑی ہیں، سیدہ عائشہ رضی اللہ عنہا کی رخصتی کے چار ماہ بعد محرم ۲ ھ میں سیدنا علی رضی اللہ عنہ سے شادی ہوئی۔ بعض نے کچھ اور مدت بھی بیان کی ہے نبی صلی اللہ علیہ وسلم کی نسل انہی سے چلی۔ ابن اسحاق رحمہ اللہ مغازی کبریٰ میں لکھتے ہیں: کہ مجھ سے ابن ابی نجیح نے بحوالہ سیدنا علی رضی اللہ عنہ بیان کیا: کہ انہوں نے سیدہ فاطمہ رضی اللہ عنہا کے لیے رشتہ بھیجا، نبی صلی اللہ علیہ وسلم (از روئے ظرافت) فرمانے لگے: “کچھ پاس بھی ہے؟” میں نے کہا: کچھ بھی نہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: “اس زرہ کا کیا ہوا جو تمہیں ملی تھی۔”(4) یعنی بدر کی غنیمت سے۔ ابن سعد(5) لکھتے ہیں: کہ خالد بن مخلد نے بحوالہ سلیمان جو ابن بلال ہیں، ہمیں بتایا کہ مجھے جعفر بن محمد نے بحوالہ اپنے والد بتایا کہ سیدنا علی رضی اللہ عنہ نے لوہے کی ایک زرہ سیدہ فاطمہ رضی اللہ عنہا کو مہر میں دی تھی۔ حازم بحوالہ حماد بن زید وہ ایوب سے بحوالہ عکرمہ روایت کرتے ہیں: کہ نبی کریم صلی اللہ علیہ وسلم نے جب سیدہ فاطمہ رضی اللہ عنہا کی شادی سیدنا علی رضی اللہ عنہ سے کرنا چاہی تو ان سے فرمایا: “اسے اپنی حطمی زرہ دینا” یہ روایت مرسل، صحیح الاسناد ہے۔ یزید بن ہارون بواسطہ جریر بن حازم، ایوب سے اس سے زیادہ مکمل روایت کرتے ہیں۔ امام احمد نے اپنی مسند میں ابن ابی نجیح کے طریق سے، وہ بحوالہ اپنے والد اس شخص سے روایت کرتے ہیں جس نے سیدنا علی رضی اللہ عنہ کو یہ فرماتے سنا تھا: میں نے نبی صلی اللہ علیہ وسلم کے گھر آپ صلی اللہ علیہ وسلم کی بیٹی کے لیے رشتہ بھیجنا چاہا اور یہ بھی عرض کر دیا کہ واللہ، میرے پاس کچھ نہیں ہے، پھر میں نے آپ صلی اللہ علیہ وسلم کی صلہ رحمی اور مہربانی کو مدنظر رکھتے ہوئے رشتہ بھیج دیا، آپ صلی اللہ علیہ وسلم نے فرمایا: “تمہارے پاس کچھ ہے” میں نے عرض کیا: کچھ نہیں، آپ صلی اللہ علیہ وسلم فرمانے لگے: “وہ حطمیہ زرہ جو میں نے تمہیں فلاں دن دی تھی وہ کہاں ہے؟” میں نے کہا: وہ تو میرے پاس ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: “وہی اسے دے دینا”۔ ابوداؤد کی کتاب میں اس روایت کا شاہد حدیث انس سے موجود ہے، ابن سعد بحوالہ واقدی بطریق ابو جعفر روایت کرتے ہیں کہ نبی صلی اللہ علیہ وسلم ابوایوب کے گھر ٹھہرے، جب سیدنا علی رضی اللہ عنہ کی سیدہ فاطمہ رضی اللہ عنہا سے شادی ہوئی تو آپ صلی اللہ علیہ وسلم نے ان سے فرمایا: “کوئی گھر تلاش کر لو” ایک گھر کا پچھلا حصہ ملا جہاں رخصتی ہوئی۔ آپ صلی اللہ علیہ وسلم سیدہ فاطمہ رضی اللہ عنہا کے ہاں تشریف لائے، سیدہ فاطمہ رضی اللہ عنہا آپ صلی اللہ علیہ وسلم سے عرض کرنے لگیں، حارثہ بن نعمان سے کہہ دیجئے! آپ صلی اللہ علیہ وسلم نے فرمایا: “میری وجہ سے وہ دوسرے مکان میں منتقل ہو گئے، مزید کہتے ہوئے شرم آتی ہے” ادھر سیدنا نعمان رضی اللہ عنہ کو پتہ چلا، حاضر ہو کر عرض کرنے لگے: یا رسول اللہ صلی اللہ علیہ وسلم! آپ مجھ سے کچھ لیں، یہ مجھے اس سے زیادہ محبوب ہے کہ آپ صلی اللہ علیہ وسلم مجھ سے کچھ نہ لیں، آپ صلی اللہ علیہ وسلم نے فرمایا: تم نے سچ کہا۔ اللہ تعالیٰ تمہیں برکت دے۔ چنانچہ سیدنا حارثہ رضی اللہ عنہ وہاں سے اپنے دوسرے مکان میں منتقل ہو گئے اور سیدنا علی رضی اللہ عنہ سیدہ فاطمہ رضی اللہ عنہا سمیت وہاں رہائش پذیر ہو گئے۔ عمر بن علی کے طریق سے مروی ہے کہ سیدنا علی کی شادی سیدہ فاطمہ سے ان کی مدینہ آمد کے موقع پر رجب میں ہوئی اور بدر سے واپسی پر رخصتی ہوئی۔ سیدہ فاطمہ رضی اللہ عنہا اس وقت اٹھارہ برس کی تھیں۔ صحیح بخاری میں سیدنا علی رضی اللہ عنہ سے ان دو اونٹنیوں کا قصہ منقول ہے جنہیں سیدنا حمزہ نے ذبح کر دیا سیدنا علی رخصتی کا ارادہ رکھتے تھے۔ اس سے اس شخص کے قول کی تردید ہو جاتی ہے جس کا گمان ہے کہ ان کی شادی احد کے بعد ہوئی تھی اس واسطے کہ سیدنا حمزہ تو احد میں ہی شہید ہوئے تھے۔ یزید بن زریع، بواسطہ روح بن قاسم، عمرو بن دینار سے روایت کرتے ہیں کہ سیدہ عائشہ رضی اللہ عنہا نے فرمایا: میں نے فاطمہ کے والد کے سوا ان سے زیادہ کسی کو افضل نہیں پایا۔ یہ روایت طبرانی نے ابراہیم بن ہاشم کے حالات میں معجم اوسط میں نقل کی ہے۔ جس کی سند عمر تک شیخین کی شرط کے مطابق صحیح ہے۔ عکرمہ بحوالہ ابن عباس رضی اللہ عنہما روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے چار خط بھیجے، اور فرمایا: “اہل جنت کی سب سے افضل خواتین خدیجہ، فاطمہ، مریم اور آسیہ رضی اللہ عنہن ہیں۔ ابو یزید مدائنی بحوالہ ابو ہریرہ رضی اللہ عنہ مرفوعاً فرماتے ہیں: دنیا کی سب سے بہتر خواتین چار ہیں: مریم، آسیہ، خدیجہ اور فاطمہ رضی اللہ عنہن۔” حضرت شعبی بحوالہ جابر فرماتے ہیں: ہمارے لیے دنیا کی چار عورتوں کی سیرت کافی ہے۔۔۔ پھر ان کا ذکر فرمایا: عبدالرحمن بن ابو نعیم بحوالہ ابو سعید خدری مرفوعاً فرماتے ہیں: “اہل جنت کی خواتین کی سردار سیدہ فاطمہ رضی اللہ عنہا ہیں۔ ہاں جو فضیلت حضرت مریم کو حاصل ہے۔ صحیحین میں بحوالہ مسور بن مخرمہ منقول ہے: میں نے رسول اللہ صلی اللہ علیہ وسلم سے منبر پر فرماتے ہوئے سنا: “فاطمہ میرے جسم کا ٹکڑا ہے، جس نے اسے تکلیف دی اس نے مجھے ایذا دی اور جس بات سے اسے دھوکہ ہوتا اس سے مجھے دھوکہ ہوتا ہے۔”(6) علی بن حسین بن علی سے بحوالہ ان کے والد، وہ سیدنا علی رضی اللہ عنہ سے روایت کرتے ہیں: فرماتے ہیں: نبی کریم صلی اللہ علیہ وسلم نے سیدہ فاطمہ رضی اللہ عنہا سے فرمایا: اللہ تعالیٰ تمہاری رضا کے ساتھ راضی ہے۔ دولابی نے “الذریۃ الظاہرۃ” میں جید سند سے بحوالہ عبداللہ بن بریدہ، انہوں نے اپنے والد سے نقل کیا ہے، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے سیدہ فاطمہ رضی اللہ عنہا کی رخصتی کی رات فرمایا: کسی سے بات نہ کرنا یہاں تک کہ مجھ سے ملاقات کرو آپ صلی اللہ علیہ وسلم نے پانی منگوایا، اس سے وضو کیا، پھر ان دونوں پر ڈال دیا اور فرمایا: “اے اللہ ان میں برکت دے، اور ان پر برکت ڈال، اور ان کی نسل میں برکت دے۔”(7) سیدہ ام سلمہ رضی اللہ عنہا فرماتی ہیں: کہ میرے گھر میں یہ آیت نازل ہوئی “بے شک اللہ تعالیٰ ارادہ فرماتے ہیں کہ اے اہل بیت تم سے ناپاکی دور کریں۔”(8) ۔ الآیۃ فرماتی ہیں: رسول اللہ صلی اللہ علیہ وسلم نے سیدہ فاطمہ رضی اللہ عنہا، سیدنا علی رضی اللہ عنہ، سیدنا حسن، سیدنا حسین رضی اللہ عنہم کی طرف پیغام بھیجا، پھر فرمایا: “یہ میرے اہل بیت ہیں۔”(9) ۔ الحدیث ترمذی رحمہ اللہ نے اور حاکم رحمہ اللہ نے مستدرک میں اسے نقل کیا ہے اور فرمایا: مسلم کی شرط کے مطابق صحیح ہے۔ مسروق رحمہ اللہ نے بحوالہ سیدہ عائشہ رضی اللہ عنہا فرمایا: سیدہ فاطمہ رضی اللہ عنہا چلتی ہوئی آئیں اور ان کا چلنا نبی کریم صلی اللہ علیہ وسلم کے چلنے کی طرح تھا، آپ صلی اللہ علیہ وسلم نے فرمایا: “میری بیٹی کو خوش آمدید” پھر اسے اپنی دائیں طرف بٹھایا اور چپکے سے انہیں کوئی بات کہی تو وہ رونے لگیں، پھر چپکے سے انہیں ایک اور بات کہی تو وہ ہنس پڑیں۔ میں نے کہا: میں نے آپ کو آج سے پہلے غم کے ساتھ ہنستے نہیں دیکھا! میں نے اس سے اس بارے میں سوال کیا تو کہنے لگیں: میں رسول اللہ صلی اللہ علیہ وسلم کے راز کو ظاہر نہیں کروں گی، جب آپ صلی اللہ علیہ وسلم کی وفات ہو گئی تو میں نے ان سے پوچھا، انہوں نے بتایا کہ آپ صلی اللہ علیہ وسلم نے فرمایا: “حضرت جبرائیل علیہ السلام ہر سال قرآن پاک کا ایک مرتبہ میرے ساتھ دور کرتے تھے، اس سال دو مرتبہ دور کیا ہے، میرا خیال ہے میری وفات کا وقت قریب آ گیا ہے، اور تم میرے اہل بیت میں سب سے پہلے مجھے آ ملو گی اور میں تمہارا اچھا پیشرو ہوں گا” تو میں رونے لگی، پھر آپ صلی اللہ علیہ وسلم نے فرمایا: “کیا تم اس پر راضی نہیں ہو کہ تمام جہان کی عورتوں کی سردار ہو” تو میں ہنسنے لگی۔ دونوں نے اسے نقل کیا ہے۔ سیدہ ام سلمہ رضی اللہ عنہا فرماتی ہیں کہ سیدہ فاطمہ رضی اللہ عنہا نبی کریم صلی اللہ علیہ وسلم سے آ کر پوچھنے لگیں: کہ مجھے بتائیں کہ آپ کا کیا حال ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: “اسی سال میری روح قبض ہو گی” جس پر وہ رونے لگیں، آپ صلی اللہ علیہ وسلم نے فرمایا: “تم سوائے مریم علیہا السلام کے جنت کی عورتوں کی سردار بن جاؤ” جس پر وہ خوش ہو کر ہنسنے لگیں، ابو یعلیٰ نے یہ روایت نقل کی ہے۔(10) ابن ابی عاصم عبداللہ بن عمرو بن سالم المفلوج سے بحوالہ اہل بیت کی سند سیدنا علی رضی اللہ عنہ سے نقل کرتے ہیں: کہ نبی کریم صلی اللہ علیہ وسلم نے سیدہ فاطمہ رضی اللہ عنہا سے فرمایا: “کہ اللہ تعالیٰ تمہاری ناراضگی سے ناراض اور تمہاری رضا مندی سے راضی ہوتا ہے۔”(11) امام ترمذی(12) نے حدیث زید بن ارقم کی حدیث سے نقل کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “علی، فاطمہ حسن اور حسین رضی اللہ عنہم سے جو شخص بھی لڑے گا، تو مقابلے میں مجھے پائے گا اور جو ان سے صلح کرے گا، میری اس سے صلح ہے۔” ابو عمر(13) سیدہ فاطمہ رضی اللہ عنہا کی وفات کے قصے میں نقل کرتے ہیں کہ سیدہ فاطمہ رضی اللہ عنہا نے سیدنا علی رضی اللہ عنہ کو یہ وصیت کر رکھی تھی کہ وہ اور سیدہ اسماء بنت عمیس رضی اللہ عنہا انہیں غسل دیں، ابن فتحون نے اس روایت کو بعید قرار دیا ہے، کیونکہ اس وقت سیدہ اسماء بنت عمیس رضی اللہ عنہا صدیق اکبر رضی اللہ عنہ کی اہلیہ تھیں، فرماتے ہیں: یہ کیسے ہو سکتا ہے کہ سیدہ فاطمہ رضی اللہ عنہا کے غسل کا حال سیدنا علی رضی اللہ عنہ کی موجودگی میں کیسے منکشف ہو سکتا ہے؟ یہ محل استبعاد ہے۔ مسند احمد میں ہے کہ انہوں نے اپنی موت سے تھوڑی دیر پہلے غسل کر لیا تھا اور یہ حکم دیا تھا کہ ان کا بدن نہ کھولا جائے اور اس غسل کو کافی سمجھا جائے یہ بھی بعید ہے۔ صحیح میں سیدہ عائشہ رضی اللہ عنہا کی حدیث سے ثابت ہے کہ سیدہ فاطمہ رضی اللہ عنہا نے نبی کریم صلی اللہ علیہ وسلم کے بعد چھ ماہ کا عرصہ حیات گزارا تھا۔ واقدی فرماتے ہیں یہی روایت ثابت ہے۔ حمیدی بواسطہ سفیان عمرو بن دینار سے روایت کرتے ہیں: کہ وہ نبی کریم صلی اللہ علیہ وسلم کے بعد تین ماہ حیات رہیں۔(14) جبکہ ان کے علاوہ مؤرخین کا قول چار ماہ کا ہے۔ ایک قول دو ماہ کا بھی ہے۔ دولابی کی کتاب “الذریۃ الظاہرۃ” میں لکھا ہے: سیدہ فاطمہ رضی اللہ عنہا نبی کریم صلی اللہ علیہ وسلم کے بعد پچانوے(۹۵) دن زندہ رہیں۔ اور عبداللہ بن حارث کا قول ہے کہ آٹھ ماہ حیات رہیں۔ ابن سعد اور امام احمد بن حنبل حدیث ام رافع سے روایت کرتے ہیں کہ سیدہ فاطمہ رضی اللہ عنہا بیمار ہو گئیں، جس دن آپ رضی اللہ عنہا کی وفات ہوئی اس دن فرمایا: اماں مجھے غسل کرائیں پھر انہوں نے اچھے طریقے سے غسل کر لیا اور نئے کپڑے پہن کے فرمانے لگیں: میری چار پائی صحن کے درمیان میں رکھ دو، اس پر قبلہ رخ ہو کر لیٹ گئیں اور فرمانے لگیں: اماں، میری روح قبض ہونے لگی ہے، میں غسل کر چکی ہوں تو ہرگز کوئی شخص میرا کپڑا نہ ہٹائے، چنانچہ پھر وہ فوت ہو گئیں، سیدنا علی رضی اللہ عنہ آئے میں نے انہیں صورتحال بتائی انہوں نے ان کا جنازہ اٹھایا اور اسی غسل پر اکتفاء کرتے ہوئے انہیں دفن کر دیا۔(15) ابن سعد، محمد بن موسیٰ کے طریق سے روایت کرتے ہیں: سیدنا علی رضی اللہ عنہ نے سیدہ فاطمہ رضی اللہ عنہا کو غسل دیا تھا، اور عبید اللہ بن ابی بکر کے طریق سے بحوالہ عمرہ نقل کیا ہے کہ سیدنا عباس رضی اللہ عنہ نے سیدہ فاطمہ رضی اللہ عنہا کا جنازہ پڑھایا، اور ان کی قبر میں سیدنا عباس، علی اور فضل بن عباس رضی اللہ عنہم اترے تھے۔ واقدی بطریق شعبی روایت کرتے ہیں کہ سیدہ فاطمہ رضی اللہ عنہا کا جنازہ سیدنا ابو بکر رضی اللہ عنہ نے پڑھایا تھا، اس سند میں ضعف اور انقطاع ہے۔ بعض متروک راوی حضرت مالک سے بحوالہ جعفر بن محمد وہ اپنے والد سے اس مفہوم کی روایت نقل کرتے ہیں، جسے دارقطنی اور ابن عدی نے فضول قرار دیا ہے۔ ابن سعد(16) بواسطہ عفان، حماد بن سلمہ، عطاء بن سائب وہ اپنے والد سے بحوالہ سیدنا علی رضی اللہ عنہ نقل کرتے ہیں، جب رسول اللہ صلی اللہ علیہ وسلم نے سیدہ فاطمہ رضی اللہ عنہا کی ان سے شادی کر دی، تو ان کے ساتھ بطور سامان جہیز ایک موٹی چادر، کھجور کی چھال کا ایک تکیہ، دو چکیاں اور دو مشکیزے بھیجے، فرماتے ہیں: ایک دن سیدنا علی رضی اللہ عنہ نے سیدہ فاطمہ رضی اللہ عنہا سے فرمایا: مشقت کرتے کرتے میرا دل تنگ پڑ گیا ہے۔ اور اللہ تعالیٰ ابھی کچھ قیدیوں کو لے آیا ہے، اپنے والد کے پاس جاؤ اور ان سے خادمہ کا سوال کرو، وہ کہنے لگیں: اللہ کی قسم! چکی پیستے پیستے میرے ہاتھوں میں بھی چھالے پڑ گئے ہیں، چنانچہ وہ نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں، آپ صلی اللہ علیہ وسلم نے فرمایا: “سناؤ، بیٹی کیسے آنا ہوا؟” عرض کرنے لگیں: ابا حضور! سلام کرنے آئی تھی، اور حیا کی وجہ سے بن مانگے واپس چلی گئیں، پھر دونوں آئے اور سیدنا علی رضی اللہ عنہ نے اپنی حالت زار بیان کی، آپ صلی اللہ علیہ وسلم نے فرمایا: اللہ کی قسم! یہ کیسے ہو سکتا ہے کہ میں تمہیں دوں اور اصحاب صفہ جن کے پیٹ بھوک سے دوہرے ہو رہے ہیں، انہیں نہ دوں۔ میرے پاس ان پر خرچ کرنے کے لیے کچھ نہیں ہے۔ یہ غلام بیچ کے میں انہیں خرچ دوں گا۔” چنانچہ یہ دونوں واپس لوٹ آئے، بعد میں آپ صلی اللہ علیہ وسلم دلجوئی کے لیے تشریف لے گئے، اتنے میں یہ لوگ بستروں میں دراز ہو چکے تھے، اور اس موٹی چادر کا طول کم تھا، ان کے چہرے ڈھکے ہوئے تھے اور پاؤں کھلے تھے، اور اگر وہ پاؤں ڈھکتے تو چہرہ کھل جاتا، آپ صلی اللہ علیہ وسلم کی آہٹ پا کر اٹھنے لگے، آپ صلی اللہ علیہ وسلم نے فرمایا: لیٹے رہو، دیکھو، میں تمہیں اس سے بہتر چیز نہ بتاؤں، جس کا تم نے سوال کیا تھا، وہ عرض کرنے لگے، کیوں نہیں، فرمایا: “چند کلمات ہیں جو مجھے جبرائیل نے سکھائے ہیں، ہر نماز کے بعد تم دونوں دس بار سبحان اللہ، دس بار الحمد للہ اور دس بار اللہ اکبر کہہ لیا کرو، اور جب سونے کا ارادہ کرو تو تینتیس(۳۳) بار سبحان اللہ، تینتیس(۳۳) بار الحمد للہ، چونتیس(۳۴) بار اللہ اکبر پڑھ لیا کرو” سیدنا علی رضی اللہ عنہ فرماتے ہیں: اللہ کی قسم! جب سے آپ صلی اللہ علیہ وسلم نے یہ کلمات مجھے سکھائے میں نے انہیں چھوڑا نہیں، آپ رضی اللہ عنہ سے ابن الکواء نے پوچھا: کیا صفین کی رات بھی نہیں؟ آپ رضی اللہ عنہ نے فرمایا: اے اہل طروق اللہ تمہیں ہلاک کرے! صفین کی رات بھی نہیں۔ فرمایا: ہمیں یزید بن ہارون نے خبر دی، وہ فرماتے ہیں، ہمیں جریر بن حازم نے بتایا، وہ فرماتے ہیں: کہ ہم سے عمرو بن سعید نے حدیث بیان کی، فرماتے ہیں: کہ سیدنا علی رضی اللہ عنہ کے رویے میں سیدہ فاطمہ رضی اللہ عنہا کے خلاف کچھ سختی تھی۔ سیدہ فاطمہ رضی اللہ عنہا کہنے لگیں: میں رسول اللہ صلی اللہ علیہ وسلم سے ضرور تمہاری شکایت کروں گی۔ چنانچہ وہ چل پڑیں سیدنا علی رضی اللہ عنہ بھی انہی کے پیچھے ہو لیے۔ آ کر آپ صلی اللہ علیہ وسلم سے گفتگو کی (سن کر) آپ صلی اللہ علیہ وسلم نے فرمایا: بیٹی! خوب کان لگا کر سنو اور سمجھو جو عورت اپنے خاوند کی مرضی پوری نہیں کرتی جبکہ اس کا خاوند خاموش ہو تو اس کی کوئی ولایت و اختیار نہیں” (یعنی اس کی شکایت سنے جانے کی گنجائش نہیں)۔ سیدنا علی رضی اللہ عنہ فرماتے ہیں پھر میں نے کوئی ایسی بات نہیں کی جو انہیں ناپسند ہوتی۔ ہمیں عبید اللہ بن موسیٰ نے بتایا وہ فرماتے ہیں: ہم سے عبد العزیز بن سیار نے بحوالہ حبیب بن ابی ثابت روایت کی، فرماتے ہیں: سیدنا علی اور فاطمہ رضی اللہ عنہما کے درمیان کوئی بات ہوئی، رسول اللہ صلی اللہ علیہ وسلم ان کے پاس آئے، آپ ان سے گفتگو فرماتے رہے یہاں تک کہ ان میں صلح کروا دی، پھر آپ صلی اللہ علیہ وسلم باہر تشریف لائے۔ راوی کہتے ہیں: آپ صلی اللہ علیہ وسلم سے کسی نے کہا: آپ جب اندر تشریف لے گئے تھے تو آپ کی حالت یکساں تھی کوئی تبدیلی ہمیں محسوس نہیں ہوئی لیکن جب باہر تشریف لائے تو آپ کا چہرہ ہشاش بشاش تھا، آپ صلی اللہ علیہ وسلم نے فرمایا: میں کیوں نہ خوش ہوتا جبکہ میں نے اپنے پسندیدہ دو افراد میں صلح کرا دی ہے۔ واقدی نے اپنی سند سے بحوالہ ابو جعفر نقل کیا ہے، فرماتے ہیں، سیدنا عباس رضی اللہ عنہ سیدنا علی اور فاطمہ رضی اللہ عنہما کے پاس گئے تو وہ کہہ رہی تھیں: میں عمر میں آپ سے بڑی ہوں، تو سیدنا عباس رضی اللہ عنہ نے فرمایا: سیدہ فاطمہ رضی اللہ عنہا اس وقت پیدا ہوئیں جب قریش کعبہ کی تعمیر کر رہے تھے اور سیدنا علی رضی اللہ عنہ ان سے دو برس قبل پیدا ہوئے۔ واقدی فرماتے ہیں: سیدہ فاطمہ رضی اللہ عنہا نے رمضان کے تین دن گزرنے پر منگل کی رات ۱۱ھ میں وفات پائی۔ عمرہ کے طریق سے ہے: سیدنا عباس رضی اللہ عنہ نے سیدہ فاطمہ رضی اللہ عنہا کی نماز جنازہ پڑھی، وہ سیدنا علی اور سیدنا فضل ان کی قبر میں اترے، علی بن حسین کے طریق سے ہے: کہ سیدنا علی رضی اللہ عنہ نے ان کی نماز جنازہ پڑھی اور رات(17) کو لوگوں کی چلت پھرت رک جانے کے بعد انہیں دفن کیا، انہوں نے بحوالہ ابن عباس رضی اللہ عنہما نقل کیا ہے کہ انہوں نے ان سے پوچھا تو انہوں نے بتایا۔ واقدی فرماتے ہیں: میں نے عبد الرحمن بن ابو موالی سے کہا: لوگ کہتے ہیں: کہ سیدہ فاطمہ رضی اللہ عنہا کی قبر بقیع میں ہے، انہوں نے فرمایا: وہ دار عقیل کے ایک گوشے میں دفن کی گئیں اور ان کی قبر اور راستے کے درمیان سات ہاتھ کا فاصلہ ہے۔","",{"fn":"(1) اسد الغابۃ (۷۱۷۵)، تجرید (۲۹۴/۲)\n(2) الاستيعاب (۱۸۹۳/۴)\n(3) الاستيعاب (۱۸۹۳/۴)\n(4) مسند ابویعلیٰ (۵۰۳/۱) مجمع الزوائد (۲۸۳/۴)\n(5) طبقات الکبریٰ (۱۱/۸)\n(6) ترمذی (۳۸۶۷)\n(7) المعجم الکبیر (۱۱۵۳/۲)، مجمع الزوائد (۲۰۹/۹)\n(8) سورۃ الاحزاب الآیۃ (۳۳)\n(9) مسلم (۶۱۶۰)، ترمذی (۳۷۲۴)\n(10) مسند ابویعلیٰ (۶۷۴۳/۱۲)\n(11) الاحاد والمثانی (۳۶۳/۵)\n(12) کتاب المناقب باب ماجاء فضل بنت محمد صلی اللہ علیہ وسلم (۳۸۷۰)\n(13) الاستيعاب (۱۸۹۹/۴)\n(14) المعجم الکبیر (۹۸۹/۲۲) مجمع الزوائد (۱۱/۹) الاحاد والمثانی (۳۵۵/۵) جامع المسانید (۳۶/۱۶)\n(15) المعجم الکبیر (۹۶۲/۲۲)، مجمع الزوائد (۲۱۱/۱)\n(16) الطبقات الکبریٰ (۱۶۱/۸)\n(17) طبرانی المعجم الکبیر (۹۹۶/۲۲)، مجمع الزوائد (۲۱۱/۹) الاحاد والمثانی (۳۵۶/۵)"}],[11541,"§۱۱۵۸۰ ۔ فاطمہ بنت اسد\n(1) بن ہاشم بن عبد مناف ہاشمیہ، سیدنا علی اور ان کے بہن بھائیوں کی والدہ ہیں، بعض کا قول ہے: ہجرت سے قبل وفات پا گئیں، صحیح یہ ہے کہ انہوں نے ہجرت کی اور مدینہ میں وفات پائی۔ شعبی نے اس پر اعتماد کیا ہے، فرماتے ہیں: اسلام لائیں اور ہجرت کی اور مدینہ میں وفات پائی۔ ابن ابی عاصم نے عبداللہ بن محمد بن عمر بن علی بن ابو طالب سے بحوالہ ان کے والد نقل کیا ہے، کہ نبی کریم صلی اللہ علیہ وسلم نے سیدہ فاطمہ بنت اسد کے کفن کے لیے اپنی قمیص عطا فرمائی(2) اور فرمایا: “ابو طالب کے بعد مجھ سے اچھا سلوک کرنے والا ان کے علاوہ کوئی ثابت نہیں ہوا۔” امام اعمش(3) بحوالہ عمرو بن مرہ، وہ ابو البختری سے وہ سیدنا علی رضی اللہ عنہ سے روایت کرتے ہیں، میں نے اپنی والدہ سے عرض کیا: پانی لانے اور دیگر ضروریات میں جانے کے سلسلے میں فاطمہ کی جگہ آپ لے لیں اور وہ چکی پیسنے اور آٹا گوندھنے میں آپ کا ہاتھ بٹا دے گی۔(4) زبیر بن بکار فرماتے ہیں: وہ پہلی ہاشمیہ ہیں جنہوں نے خلیفہ کو جنم دیا، ان کے بعد سیدہ فاطمۃ الزھراء ہیں، فاطمہ بنت حمزہ کے سوانح میں ان کا ذکر آئے گا۔ جو دلالت کرتا ہے کہ انہوں نے مدینہ میں وفات پائی۔(5) ابن سعد فرماتے ہیں: وہ نیک خاتون تھیں نبی کریم صلی اللہ علیہ وسلم ان سے ملاقات کے لیے تشریف لاتے تھے اور دوپہر کو ان کے گھر آرام فرماتے تھے۔","",{"fn":"(1) اسد الغابۃ (۷۱۶۸)، الاستيعاب (۳۵۹۹)، تجرید (۲۹۳/۵)\n(2) معجم الکبیر (۸۷۲/۲۴) مجمع الزوائد (۲۵۶/۹)\n(3) مجمع الزوائد (۲۵۷/۹)\n(4) المعجم الکبیر (۸۷۳/۲۴)، مجمع الزوائد (۲۵۶/۹)\n(5) نسب قریش (۱۶)"}],[11542,"§۱۱۵۸۱ ۔ فاطمہ بنت ابی الاسد\n(1) بعض کا قول ہے: بنت اسود بن عبد الاسد: ابو عمر فرماتے ہیں،(2) یہ وہی ہیں، کہ نبی کریم صلی اللہ علیہ وسلم نے چوری کی وجہ سے ان کا ہاتھ کاٹنے کا حکم فرمایا، اور جب اسامہ بن زید نے ان کے لیے سفارش کی تو فرمایا: “کیا تم اللہ کی حدوں میں سے ایک حد کے بارے میں سفارش کرتے ہو؟” حبیب بن ابو ثابت نے ان کی حدیث روایت کی اور ان کا نام لیا ہے۔ میں کہتا ہوں: عبد الغنی بن سعید نے مہمات میں یحییٰ بن سلمہ بن کہیل کے طریق سے، عمار دہنی سے بحوالہ ابو وائل نقل کیا ہے۔ فرماتے ہیں: فاطمہ بنت ابوالاسد نے جو ابو سلمہ کے بھائی کی بیٹی ہیں چوری کی، قریش کو خوف ہوا کہ ان کا ہاتھ کاٹ دیا جائے گا، انہوں نے اسامہ سے گفتگو کی۔۔۔۔ الحدیث ابن سعد کا قول ہے: فاطمہ بنت اسود بن عبد الاسد اسلام لائیں اور بیعت کی، یہ وہی ہیں جنہوں نے چوری کی، تو نبی کریم صلی اللہ علیہ وسلم نے ان کا ہاتھ کاٹنے کا حکم دیا۔ ہم سے ابن نمیر نے اصبغ سے بحوالہ حبیب بن ابو ثابت مرفوع حدیث بیان کی کہ فاطمہ بنت اسود بن عبدالاسد نے رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں زیور چوری کیا، بہت سے لوگوں نے نبی کریم صلی اللہ علیہ وسلم سے سفارش کی، انہوں نے اسامہ بن زید سے گفتگو کی تا کہ وہ نبی کریم صلی اللہ علیہ وسلم سے ان کی سفارش کریں، جب اسامہ آئے اور ان کو نبی کریم صلی اللہ علیہ وسلم نے دیکھا تو فرمایا: “اے اسامہ مجھ سے سفارش نہ کرنا، کیونکہ حدود جب میرے سپرد کی جاتی ہیں تو ان کے ترک کرنے کی گنجائش نہیں رہتی، اگر محمد کی بیٹی فاطمہ بھی ایسا کرتی تو میں اس کے ہاتھ کاٹنے کا حکم دیتا۔”(3) ابن سعد(4) کا قول ہے: اہل مدینہ وغیرہ کی اہل مکہ کی روایت ہے کہ جس خاتون نے چوری کی، اور رسول اللہ صلی اللہ علیہ وسلم نے ان کا ہاتھ کاٹنے کا حکم دیا، وہ ام عمرو بنت سفیان بن عبدالاسد۔","",{"fn":"(1) اسد الغابۃ (۷۱۶۹)، تجرید (۲۹۳/۲)\n(2) الاستيعاب (۱۸۹۲/۴)\n(3) بخاری (الحدیث ۳۴۷۵، ۳۷۳۲، ۶۷۸۷) مسلم (الحدیث ۴۳۸۶) ابوداؤد (۴۳۷۳)، ترمذی (۱۴۳۰) نسائی (۴۹۱۴)، ابن ماجہ (۲۵۴۷)\n(4) الطبقات الکبریٰ (۱۹۲/۸)"}],[11543,"§۱۱۵۸۲ ۔ فاطمہ بنت جنید\nبن عمرو بن عبد شمس بن عمرو، عباس بن عبدالمطلب کی زوجہ اور حارث کی والدہ ہیں جو ان کا بیٹا ہے۔ زبیر بن بکار نے ان کا ذکر کیا ہے۔"],[11544,"§۱۱۵۸۳ ۔ فاطمہ بنت الحارث\n(1) بن خالد بن صحر بن عامر بن کعب بن سعد بن تیم بن مرہ قرشیہ تیمیہ، ان کی والدہ رائطہ کے سوانح میں ان کا ذکر ہو چکا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۱۷۰)، الاستيعاب (۵۳۰۲)، تجرید (۲۹۳/۲)"}],[11545,"§۱۱۵۸۴ ۔ فاطمہ بنت ابی حبیش\n(1) بن مطلب بن اسد بن عبد العزیٰ بن قصی قرشیہ اسدیہ صحیحین(2) میں ہشام بن عروہ کے طریق سے بحوالہ ان کے والد، سیدہ عائشہ رضی اللہ عنہا سے روایت ہے، فرماتی ہیں: فاطمہ بنت ابی حبیش نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں اور کہنے لگیں: یا رسول اللہ صلی اللہ علیہ وسلم مجھے حیض آتا ہے اور میں کبھی پاک نہیں ہوتی، کیا میں نماز چھوڑ دوں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: نہیں، یہ ایک رگ ہے، حیض نہیں” الحدیث۔ اسے منذر بن مغیرہ نے بحوالہ عروہ روایت کیا ہے، کہ فاطمہ بنت ابی حبیش ہیں، ایک روایت میں الفاظ ہیں بحوالہ فاطمہ، ایک اور روایت میں ہے، مجھ سے فاطمہ نے بیان کیا، ان کی حدیث کو ابوداؤد اور نسائی نے نقل کیا ہے، اور پہلی مشہور ہے۔(3)","",{"fn":"(1) اسد الغابۃ (۷۱۷۱) الاستيعاب (۳۵۰۳) تجرید (۲۹۴/۲)\n(2) بخاری (الحدیث ۲۲۳) مسلم (الحدیث ۷۵۲)\n(3) ابوداؤد (الحدیث ۲۸۰)، نسائی (الحدیث ۳۵۶)"}]])